import importlib.abc
import importlib.util
import sys

_PACKAGES = {'dashboard.pages', 'gis', 'database', 'ai', 'irrigation', 'utils', 'finance', 'api', 'config', 'analytics', 'reports', 'app', 'core', 'satellite', 'dashboard', 'ml', 'weather', 'market'}

_SOURCES = {
    'ai': '"""Built-in AI assistant: offline natural-language analytics over the database."""\n',
    'ai.engine': '"""Rule-based natural-language analytics engine (fully offline).\n\nUnderstands Uzbek questions like "Jizzaxda bug\'doy hosili nima uchun pasaydi?"\nby extracting entities (region, crop, year) from the live database, detecting\nthe intent, running the relevant analytics and composing an evidence-backed\nanswer: yield dynamics, weather anomalies, irrigation deficit, price context\nand a forecast where relevant.\n"""\nfrom __future__ import annotations\n\nimport logging\nimport re\nfrom dataclasses import dataclass, field\n\nimport pandas as pd\n\nfrom analytics.timeseries import linear_forecast, percent_change\nfrom database.engine import read_df\n\nlog = logging.getLogger(__name__)\n\nINTENT_KEYWORDS: dict[str, list[str]] = {\n    "why": ["nega", "nima uchun", "sabab", "pasaydi", "kamaydi", "tushdi"],\n    "forecast": ["prognoz", "bashorat", "kelgusi", "keyingi yil", "qancha bo\'ladi"],\n    "price": ["narx", "narxi", "qancha turadi", "bozor"],\n    "recommend": ["tavsiya", "qaysi ekin", "nima eksam", "eng foydali", "maslahat"],\n    "weather": ["ob-havo", "harorat", "yog\'in", "yomg\'ir", "namlik", "iqlim"],\n    "compare": ["solishtir", "taqqosla", "farqi", "qaysi yaxshi"],\n    "finance": ["daromad", "foyda", "zarar", "roi", "xarajat", "kredit", "subsidiya"],\n}\n\n\ndef _normalize(text: str) -> str:\n    text = text.lower()\n    for apostrophe in ("‘", "’", "ʻ", "ʼ", "`", "´"):\n        text = text.replace(apostrophe, "\'")\n    return re.sub(r"\\s+", " ", text).strip()\n\n\n@dataclass\nclass QueryContext:\n    """Entities extracted from a natural-language question."""\n\n    intent: str = "stats"\n    region: str | None = None\n    region_id: int | None = None\n    crop: str | None = None\n    crop_id: int | None = None\n    year: int | None = None\n    matched: list[str] = field(default_factory=list)\n\n\nclass AIAssistant:\n    """Offline NL query engine over the analytics database."""\n\n    def parse(self, question: str) -> QueryContext:\n        text = _normalize(question)\n        context = QueryContext()\n\n        for intent, keywords in INTENT_KEYWORDS.items():\n            if any(keyword in text for keyword in keywords):\n                context.intent = intent\n                break\n\n        regions = read_df("SELECT id, name FROM regions")\n        for row in regions.itertuples():\n            stem = _normalize(row.name)[:5]\n            if stem in text:\n                context.region, context.region_id = row.name, int(row.id)\n                context.matched.append(row.name)\n                break\n\n        crops = read_df("SELECT id, name FROM crops")\n        for row in crops.itertuples():\n            stem = _normalize(row.name)[:5]\n            if stem in text:\n                context.crop, context.crop_id = row.name, int(row.id)\n                context.matched.append(row.name)\n                break\n\n        year_match = re.search(r"(20\\d{2})", text)\n        if year_match:\n            context.year = int(year_match.group(1))\n        return context\n\n    def ask(self, question: str) -> dict:\n        """Answer a question; returns {\'answer\': str, \'table\': DataFrame|None}."""\n        try:\n            context = self.parse(question)\n            handler = {\n                "why": self._answer_why,\n                "forecast": self._answer_forecast,\n                "price": self._answer_price,\n                "recommend": self._answer_recommend,\n                "weather": self._answer_weather,\n                "compare": self._answer_compare,\n                "finance": self._answer_finance,\n                "stats": self._answer_stats,\n            }[context.intent]\n            return handler(context)\n        except Exception:  # noqa: BLE001\n            log.exception("AI so\'rovi xatosi")\n            return {"answer": "So\'rovni tahlil qilishda xatolik yuz berdi. "\n                              "Savolni boshqacha ifodalab ko\'ring.", "table": None}\n\n    # ------------------------------------------------------------------\n    def _yield_series(self, context: QueryContext) -> pd.DataFrame:\n        sql = (\n            "SELECT y.year, ROUND(AVG(y.yield_t_ha),2) AS avg_yield,"\n            " ROUND(SUM(y.production_t),0) AS production"\n            " FROM yield_records y"\n            " JOIN fields f ON f.id = y.field_id"\n            " JOIN farms fa ON fa.id = f.farm_id"\n            " JOIN districts d ON d.id = fa.district_id"\n            " JOIN regions r ON r.id = d.region_id"\n        )\n        clauses, params = [], {}\n        if context.region_id:\n            clauses.append("r.id = :region_id")\n            params["region_id"] = context.region_id\n        if context.crop_id:\n            clauses.append("y.crop_id = :crop_id")\n            params["crop_id"] = context.crop_id\n        if clauses:\n            sql += " WHERE " + " AND ".join(clauses)\n        sql += " GROUP BY y.year ORDER BY y.year"\n        return read_df(sql, params)\n\n    def _scope_label(self, context: QueryContext) -> str:\n        parts = []\n        if context.region:\n            parts.append(context.region)\n        if context.crop:\n            parts.append(context.crop.lower())\n        return " — ".join(parts) if parts else "respublika bo\'yicha"\n\n    def _answer_why(self, context: QueryContext) -> dict:\n        series = self._yield_series(context)\n        if len(series) < 2:\n            return {"answer": "Tahlil uchun yetarli tarixiy ma\'lumot topilmadi.",\n                    "table": series}\n        target_year = context.year or int(series.iloc[-1]["year"])\n        row = series[series.year == target_year]\n        prev = series[series.year == target_year - 1]\n        if row.empty or prev.empty:\n            return {"answer": f"{target_year}-yil uchun ma\'lumot topilmadi.",\n                    "table": series}\n        current = float(row.iloc[0]["avg_yield"])\n        previous = float(prev.iloc[0]["avg_yield"])\n        change = percent_change(previous, current)\n        scope = self._scope_label(context)\n\n        reasons: list[str] = []\n        if context.region:\n            from weather.service import season_summary\n\n            this_season = season_summary(context.region, target_year)\n            history = [season_summary(context.region, y)\n                       for y in range(target_year - 4, target_year)]\n            history = [h for h in history if h]\n            if this_season and history:\n                mean_precip = sum(h["precip"] for h in history) / len(history)\n                precip_change = percent_change(mean_precip, this_season["precip"])\n                if precip_change < -15:\n                    reasons.append(\n                        f"mavsumiy yog\'ingarchilik o\'rtachadan {abs(precip_change):.0f}% "\n                        f"kam bo\'ldi ({this_season[\'precip\']:.0f} mm)")\n                mean_temp = sum(h["t_avg"] for h in history) / len(history)\n                if this_season["t_avg"] - mean_temp > 1:\n                    reasons.append(\n                        f"o\'rtacha harorat {this_season[\'t_avg\'] - mean_temp:.1f}°C yuqori bo\'ldi")\n\n            irrigation = read_df(\n                "SELECT CAST(strftime(\'%Y\', i.date) AS INTEGER) AS year,"\n                " SUM(i.water_m3) AS water"\n                " FROM irrigation_records i"\n                " JOIN fields f ON f.id = i.field_id"\n                " JOIN farms fa ON fa.id = f.farm_id"\n                " JOIN districts d ON d.id = fa.district_id"\n                " JOIN regions r ON r.id = d.region_id"\n                " WHERE r.id = :rid GROUP BY year ORDER BY year",\n                {"rid": context.region_id},\n            )\n            this_water = irrigation[irrigation.year == target_year]\n            past_water = irrigation[irrigation.year < target_year]\n            if not this_water.empty and not past_water.empty:\n                water_change = percent_change(\n                    float(past_water["water"].mean()), float(this_water.iloc[0]["water"]))\n                if water_change < -10:\n                    reasons.append(\n                        f"sug\'orish hajmi o\'rtachadan {abs(water_change):.0f}% kamaydi")\n\n        if change < 0:\n            answer = (f"{scope.capitalize()}: {target_year}-yilda o\'rtacha hosildorlik "\n                      f"{previous:.2f} t/ga dan {current:.2f} t/ga ga tushdi "\n                      f"({change:+.1f}%).\\n\\n")\n            if reasons:\n                answer += "Asosiy sabablar (ma\'lumotlar tahlili):\\n" + "\\n".join(\n                    f"• {reason};" for reason in reasons)\n            else:\n                answer += ("Ob-havo va sug\'orish ko\'rsatkichlarida keskin og\'ish "\n                           "aniqlanmadi — pasayish agrotexnika yoki navlar bilan "\n                           "bog\'liq bo\'lishi mumkin.")\n        else:\n            answer = (f"{scope.capitalize()}: {target_year}-yilda hosildorlik aslida "\n                      f"pasaymagan — {previous:.2f} dan {current:.2f} t/ga ga "\n                      f"o\'zgardi ({change:+.1f}%).")\n        return {"answer": answer, "table": series}\n\n    def _answer_forecast(self, context: QueryContext) -> dict:\n        series = self._yield_series(context)\n        if len(series) < 3:\n            return {"answer": "Prognoz uchun kamida 3 yillik ma\'lumot kerak.",\n                    "table": series}\n        values = series["avg_yield"].tolist()\n        forecast, lower, upper = linear_forecast(values, periods=1)\n        next_year = int(series.iloc[-1]["year"]) + 1\n        answer = (\n            f"{self._scope_label(context).capitalize()} uchun {next_year}-yil prognozi: "\n            f"o\'rtacha hosildorlik ≈ {forecast[0]:.2f} t/ga "\n            f"(ishonch oralig\'i: {lower[0]:.2f} – {upper[0]:.2f} t/ga).\\n"\n            f"So\'nggi 5 yil trendi: {values[0]:.2f} → {values[-1]:.2f} t/ga."\n        )\n        return {"answer": answer, "table": series}\n\n    def _answer_price(self, context: QueryContext) -> dict:\n        if not context.crop_id:\n            from market.service import latest_prices\n\n            table = latest_prices()\n            return {"answer": "Barcha ekinlar bo\'yicha so\'nggi bozor narxlari quyida.",\n                    "table": table}\n        prices = read_df(\n            "SELECT date, price_per_kg FROM market_prices"\n            " WHERE crop_id = :c ORDER BY date DESC LIMIT 52", {"c": context.crop_id},\n        ).sort_values("date")\n        latest = float(prices.iloc[-1]["price_per_kg"])\n        mean = float(prices["price_per_kg"].mean())\n        forecast, lower, upper = linear_forecast(prices["price_per_kg"].tolist(), 4)\n        answer = (\n            f"{context.crop}: joriy narx {latest:,.0f} so\'m/kg "\n            f"(yillik o\'rtacha {mean:,.0f} so\'m/kg).\\n"\n            f"1 oylik prognoz: {forecast[-1]:,.0f} so\'m/kg atrofida "\n            f"({lower[-1]:,.0f} – {upper[-1]:,.0f})."\n        )\n        return {"answer": answer, "table": prices.tail(10)}\n\n    def _answer_recommend(self, context: QueryContext) -> dict:\n        from ml.service import recommend_crops\n        from weather.service import season_summary\n\n        region = context.region or "Toshkent"\n        region_row = read_df(\n            "SELECT id, fertility FROM regions WHERE name = :n", {"n": region})\n        if region_row.empty:\n            return {"answer": "Viloyat topilmadi — savolda viloyat nomini keltiring.",\n                    "table": None}\n        from analytics.kpi import latest_year\n\n        season = season_summary(region, latest_year()) or {"precip": 150, "t_avg": 24}\n        recommendations = recommend_crops(\n            int(region_row.iloc[0]["id"]), season["precip"], season["t_avg"],\n            float(region_row.iloc[0]["fertility"]))\n        lines = "\\n".join(\n            f"{i + 1}. {rec[\'crop\']} (model ishonchi: {rec[\'confidence\']}%)"\n            for i, rec in enumerate(recommendations))\n        answer = (f"{region} viloyati uchun ML modeli tavsiya qilgan eng foydali "\n                  f"ekinlar (tarixiy foyda va iqlim asosida):\\n{lines}")\n        return {"answer": answer, "table": pd.DataFrame(recommendations)}\n\n    def _answer_weather(self, context: QueryContext) -> dict:\n        from analytics.kpi import latest_year\n\n        region = context.region or "Toshkent"\n        year = context.year or latest_year()\n        from weather.service import season_summary\n\n        season = season_summary(region, year)\n        if season is None:\n            return {"answer": f"{region} bo\'yicha {year}-yil ob-havo ma\'lumoti topilmadi.",\n                    "table": None}\n        answer = (\n            f"{region} viloyati, {year}-yil vegetatsiya mavsumi (aprel–sentabr):\\n"\n            f"• Yog\'ingarchilik: {season[\'precip\']:.0f} mm\\n"\n            f"• O\'rtacha harorat: {season[\'t_avg\']:.1f}°C\\n"\n            f"• O\'rtacha namlik: {season[\'humidity\']:.0f}%"\n        )\n        return {"answer": answer, "table": None}\n\n    def _answer_compare(self, context: QueryContext) -> dict:\n        from analytics.kpi import latest_year, yield_by_region\n\n        table = yield_by_region(context.year or latest_year())\n        best, worst = table.iloc[0], table.iloc[-1]\n        answer = (\n            f"{context.year or latest_year()}-yil viloyatlar taqqoslamasi:\\n"\n            f"• Eng yuqori ishlab chiqarish: {best.region} ({best.production:,.0f} t)\\n"\n            f"• Eng past: {worst.region} ({worst.production:,.0f} t)\\n"\n            f"To\'liq jadval quyida."\n        )\n        return {"answer": answer, "table": table}\n\n    def _answer_finance(self, context: QueryContext) -> dict:\n        from analytics.kpi import latest_year\n        from finance.service import yearly_summary\n\n        table = yearly_summary()\n        year = context.year or latest_year()\n        row = table[table.year == year]\n        if row.empty:\n            return {"answer": f"{year}-yil moliya ma\'lumotlari topilmadi.", "table": table}\n        record = row.iloc[0]\n        answer = (\n            f"{year}-yil moliyaviy natijalar (platforma bo\'yicha):\\n"\n            f"• Daromad: {record.income / 1e9:,.1f} mlrd so\'m\\n"\n            f"• Xarajat: {record.expense / 1e9:,.1f} mlrd so\'m\\n"\n            f"• Sof foyda: {record.profit / 1e9:,.1f} mlrd so\'m (ROI: {record.roi}%)\\n"\n            f"• Kreditlar: {record.credit / 1e9:,.1f} mlrd, subsidiyalar: "\n            f"{record.subsidy / 1e9:,.1f} mlrd so\'m"\n        )\n        return {"answer": answer, "table": table}\n\n    def _answer_stats(self, context: QueryContext) -> dict:\n        from analytics.kpi import compute_kpi\n\n        kpi = compute_kpi(context.year)\n        series = self._yield_series(context)\n        scope = self._scope_label(context)\n        extra = ""\n        if not series.empty and (context.region or context.crop):\n            last = series.iloc[-1]\n            extra = (f"\\n{scope.capitalize()}: {int(last.year)}-yilda o\'rtacha "\n                     f"hosildorlik {last.avg_yield} t/ga, ishlab chiqarish "\n                     f"{last.production:,.0f} t.")\n        answer = (\n            f"{kpi.year}-yil umumiy ko\'rsatkichlari:\\n"\n            f"• Yer maydoni: {kpi.total_area_ha:,.0f} ga | Fermerlar: {kpi.farmers} | "\n            f"Xo\'jaliklar: {kpi.farms} | Dalalar: {kpi.fields}\\n"\n            f"• O\'rtacha hosildorlik: {kpi.avg_yield_t_ha} t/ga, jami "\n            f"{kpi.production_t:,.0f} t mahsulot\\n"\n            f"• Moliyaviy natija: foyda {kpi.profit / 1e9:,.1f} mlrd so\'m "\n            f"(ROI {kpi.roi_percent}%)\\n"\n            f"• O\'rtacha NDVI (so\'nggi 60 kun): {kpi.avg_ndvi}" + extra\n        )\n        return {"answer": answer, "table": series if not series.empty else None}\n\n\nassistant = AIAssistant()\n',
    'analytics': '"""Analytics layer: KPIs, time series, forecasting, insights."""\n',
    'analytics.insights': '"""Automatic insight/alert generation shown on the dashboard and used by the AI."""\nfrom __future__ import annotations\n\nimport pandas as pd\n\nfrom analytics.kpi import latest_year\nfrom analytics.timeseries import percent_change, zscore_anomalies\nfrom core.cache import cached\nfrom database.engine import read_df\n\n\n@cached(ttl=300)\ndef generate_alerts() -> list[dict[str, str]]:\n    """Rule-based alerts: droughts, yield drops, price spikes, NDVI decline, losses."""\n    alerts: list[dict[str, str]] = []\n    year = latest_year()\n    alerts.extend(_drought_alerts(year))\n    alerts.extend(_yield_drop_alerts(year))\n    alerts.extend(_price_spike_alerts())\n    alerts.extend(_ndvi_alerts())\n    alerts.extend(_loss_alerts(year))\n    severity_rank = {"error": 0, "warning": 1, "info": 2}\n    alerts.sort(key=lambda a: severity_rank.get(a["level"], 3))\n    return alerts[:12]\n\n\ndef _drought_alerts(year: int) -> list[dict[str, str]]:\n    df = read_df(\n        "SELECT r.name AS region, CAST(strftime(\'%Y\', w.date) AS INTEGER) AS year,"\n        " SUM(w.precipitation_mm) AS precip"\n        " FROM weather_records w"\n        " JOIN districts d ON d.id = w.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE CAST(strftime(\'%m\', w.date) AS INTEGER) BETWEEN 4 AND 9"\n        " GROUP BY r.name, year"\n    )\n    alerts = []\n    for region, group in df.groupby("region"):\n        group = group.sort_values("year")\n        mean = group["precip"].mean()\n        last = group[group.year == year]\n        if last.empty or mean <= 0:\n            continue\n        value = float(last.iloc[0]["precip"])\n        deficit = (mean - value) / mean * 100\n        if deficit > 30:\n            alerts.append({\n                "level": "error", "title": f"{region}: qurg\'oqchilik xavfi",\n                "detail": f"{year}-yil mavsumida yog\'ingarchilik o\'rtachadan "\n                          f"{deficit:.0f}% kam ({value:.0f} mm).",\n            })\n    return alerts\n\n\ndef _yield_drop_alerts(year: int) -> list[dict[str, str]]:\n    df = read_df(\n        "SELECT r.name AS region, y.year, AVG(y.yield_t_ha) AS avg_yield"\n        " FROM yield_records y"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " GROUP BY r.name, y.year"\n    )\n    alerts = []\n    for region, group in df.groupby("region"):\n        group = group.sort_values("year")\n        if len(group) < 2:\n            continue\n        prev, curr = group.iloc[-2]["avg_yield"], group.iloc[-1]["avg_yield"]\n        change = percent_change(float(prev), float(curr))\n        if change < -12:\n            alerts.append({\n                "level": "warning", "title": f"{region}: hosildorlik pasaygan",\n                "detail": f"{int(group.iloc[-1][\'year\'])}-yilda o\'rtacha hosildorlik "\n                          f"{change:.1f}% ga kamaydi ({prev:.2f} → {curr:.2f} t/ga).",\n            })\n    return alerts\n\n\ndef _price_spike_alerts() -> list[dict[str, str]]:\n    df = read_df(\n        "SELECT c.name AS crop, m.date, m.price_per_kg FROM market_prices m"\n        " JOIN crops c ON c.id = m.crop_id"\n        " WHERE m.date >= date(\'now\',\'-180 day\') ORDER BY m.date"\n    )\n    alerts = []\n    for crop, group in df.groupby("crop"):\n        prices = group["price_per_kg"].tolist()\n        anomalies = zscore_anomalies(prices, threshold=2.4)\n        if anomalies and anomalies[-1] >= len(prices) - 3:\n            latest = prices[anomalies[-1]]\n            mean = float(pd.Series(prices).mean())\n            direction = "keskin oshdi" if latest > mean else "keskin tushdi"\n            alerts.append({\n                "level": "info", "title": f"{crop} narxi {direction}",\n                "detail": f"So\'nggi narx {latest:,.0f} so\'m/kg "\n                          f"(6 oylik o\'rtacha: {mean:,.0f} so\'m/kg).",\n            })\n    return alerts[:3]\n\n\ndef _ndvi_alerts() -> list[dict[str, str]]:\n    df = read_df(\n        "SELECT f.name AS field, fa.name AS farm, s.ndvi, s.date"\n        " FROM satellite_indices s"\n        " JOIN fields f ON f.id = s.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " WHERE s.date >= date(\'now\',\'-45 day\')"\n    )\n    if df.empty:\n        return []\n    latest = df.sort_values("date").groupby("field").last().reset_index()\n    weak = latest[latest.ndvi < 0.25].head(3)\n    return [\n        {\n            "level": "warning", "title": f"{row.field}: past vegetatsiya indeksi",\n            "detail": f"{row.farm} dalasida NDVI={row.ndvi:.2f} — o\'simlik holati zaif.",\n        }\n        for row in weak.itertuples()\n    ]\n\n\ndef _loss_alerts(year: int) -> list[dict[str, str]]:\n    df = read_df(\n        "SELECT fa.name AS farm,"\n        " SUM(CASE WHEN fr.category=\'income\' THEN fr.amount ELSE 0 END) AS income,"\n        " SUM(CASE WHEN fr.category=\'expense\' THEN fr.amount ELSE 0 END) AS expense"\n        " FROM finance_records fr JOIN farms fa ON fa.id = fr.farm_id"\n        " WHERE fr.year = :y GROUP BY fa.id", {"y": year},\n    )\n    losers = df[df.income < df.expense]\n    if losers.empty:\n        return []\n    worst = losers.assign(loss=losers.expense - losers.income).nlargest(2, "loss")\n    return [\n        {\n            "level": "warning", "title": f"{row.farm}: zarar bilan ishlamoqda",\n            "detail": f"{year}-yilda zarar {row.loss / 1e6:,.0f} mln so\'m "\n                      f"(daromad {row.income / 1e6:,.0f}, xarajat {row.expense / 1e6:,.0f} mln).",\n        }\n        for row in worst.itertuples()\n    ]\n',
    'analytics.kpi': '"""Business KPI computations backed by SQL + pandas."""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nimport pandas as pd\n\nfrom core.cache import cached\nfrom database.engine import read_df\n\n\n@dataclass\nclass KPISummary:\n    """Headline figures shown on the main dashboard."""\n\n    year: int\n    total_area_ha: float\n    farms: int\n    farmers: int\n    fields: int\n    crops: int\n    avg_yield_t_ha: float\n    production_t: float\n    income: float\n    expense: float\n    profit: float\n    roi_percent: float\n    avg_ndvi: float\n    water_million_m3: float\n\n\n@cached(ttl=120)\ndef latest_year() -> int:\n    """Most recent year that has yield records."""\n    df = read_df("SELECT MAX(year) AS y FROM yield_records")\n    value = df.iloc[0]["y"]\n    return int(value) if pd.notna(value) else pd.Timestamp.now().year\n\n\n@cached(ttl=120)\ndef available_years() -> list[int]:\n    df = read_df("SELECT DISTINCT year FROM yield_records ORDER BY year")\n    return [int(y) for y in df["year"].tolist()]\n\n\n@cached(ttl=120)\ndef compute_kpi(year: int | None = None) -> KPISummary:\n    """Aggregate the platform-wide KPI card values for a given year."""\n    year = year or latest_year()\n    counts = read_df(\n        "SELECT (SELECT COUNT(*) FROM farms) AS farms,"\n        " (SELECT COUNT(*) FROM farmers) AS farmers,"\n        " (SELECT COUNT(*) FROM fields) AS fields,"\n        " (SELECT COUNT(*) FROM crops) AS crops,"\n        " (SELECT COALESCE(SUM(area_ha),0) FROM fields) AS area"\n    ).iloc[0]\n    yields = read_df(\n        "SELECT COALESCE(AVG(yield_t_ha),0) AS avg_yield,"\n        " COALESCE(SUM(production_t),0) AS production"\n        " FROM yield_records WHERE year = :y", {"y": year},\n    ).iloc[0]\n    finance = read_df(\n        "SELECT category, COALESCE(SUM(amount),0) AS total FROM finance_records"\n        " WHERE year = :y GROUP BY category", {"y": year},\n    ).set_index("category")["total"]\n    income = float(finance.get("income", 0.0))\n    expense = float(finance.get("expense", 0.0))\n    profit = income - expense\n    ndvi = read_df(\n        "SELECT COALESCE(AVG(ndvi),0) AS ndvi FROM satellite_indices"\n        " WHERE date >= date(\'now\',\'-60 day\')"\n    ).iloc[0]["ndvi"]\n    water = read_df(\n        "SELECT COALESCE(SUM(water_m3),0) AS w FROM irrigation_records"\n        " WHERE strftime(\'%Y\', date) = :y", {"y": str(year)},\n    ).iloc[0]["w"]\n\n    return KPISummary(\n        year=year,\n        total_area_ha=round(float(counts["area"]), 1),\n        farms=int(counts["farms"]), farmers=int(counts["farmers"]),\n        fields=int(counts["fields"]), crops=int(counts["crops"]),\n        avg_yield_t_ha=round(float(yields["avg_yield"]), 2),\n        production_t=round(float(yields["production"]), 0),\n        income=income, expense=expense, profit=profit,\n        roi_percent=round(profit / expense * 100, 1) if expense else 0.0,\n        avg_ndvi=round(float(ndvi), 3),\n        water_million_m3=round(float(water) / 1_000_000, 2),\n    )\n\n\n@cached(ttl=120)\ndef yield_trend() -> pd.DataFrame:\n    """Average yield and total production per year."""\n    return read_df(\n        "SELECT year, ROUND(AVG(yield_t_ha),2) AS avg_yield,"\n        " ROUND(SUM(production_t),0) AS production"\n        " FROM yield_records GROUP BY year ORDER BY year"\n    )\n\n\n@cached(ttl=120)\ndef yield_by_region(year: int | None = None) -> pd.DataFrame:\n    """Average yield / production / area grouped by region for a year."""\n    year = year or latest_year()\n    return read_df(\n        "SELECT r.name AS region, ROUND(AVG(y.yield_t_ha),2) AS avg_yield,"\n        " ROUND(SUM(y.production_t),0) AS production,"\n        " ROUND(SUM(y.area_ha),0) AS area"\n        " FROM yield_records y"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE y.year = :y GROUP BY r.name ORDER BY production DESC", {"y": year},\n    )\n\n\n@cached(ttl=120)\ndef crop_distribution(year: int | None = None) -> pd.DataFrame:\n    """Sown area share per crop for a year."""\n    year = year or latest_year()\n    return read_df(\n        "SELECT c.name AS crop, ROUND(SUM(y.area_ha),0) AS area,"\n        " ROUND(SUM(y.production_t),0) AS production,"\n        " ROUND(AVG(y.yield_t_ha),2) AS avg_yield"\n        " FROM yield_records y JOIN crops c ON c.id = y.crop_id"\n        " WHERE y.year = :y GROUP BY c.name ORDER BY area DESC", {"y": year},\n    )\n\n\n@cached(ttl=120)\ndef region_crop_matrix(year: int | None = None) -> pd.DataFrame:\n    """Region x crop average-yield pivot used for the analytics heatmap."""\n    year = year or latest_year()\n    df = read_df(\n        "SELECT r.name AS region, c.name AS crop, AVG(y.yield_t_ha) AS avg_yield"\n        " FROM yield_records y"\n        " JOIN crops c ON c.id = y.crop_id"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE y.year = :y GROUP BY r.name, c.name", {"y": year},\n    )\n    if df.empty:\n        return df\n    return df.pivot_table(index="region", columns="crop", values="avg_yield").round(2)\n\n\n@cached(ttl=120)\ndef rainfall_yield_correlation() -> tuple[pd.DataFrame, float]:\n    """Season rainfall vs average yield per district-year, plus correlation."""\n    df = read_df(\n        "SELECT d.id AS district_id, d.name AS district, y.year,"\n        " AVG(y.yield_t_ha) AS avg_yield"\n        " FROM yield_records y"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " GROUP BY d.id, y.year"\n    )\n    rain = read_df(\n        "SELECT district_id, CAST(strftime(\'%Y\', date) AS INTEGER) AS year,"\n        " SUM(precipitation_mm) AS precip"\n        " FROM weather_records"\n        " WHERE CAST(strftime(\'%m\', date) AS INTEGER) BETWEEN 4 AND 9"\n        " GROUP BY district_id, year"\n    )\n    merged = df.merge(rain, on=["district_id", "year"], how="inner")\n    corr = float(merged["precip"].corr(merged["avg_yield"])) if len(merged) > 2 else 0.0\n    return merged, round(corr, 3)\n\n\n@cached(ttl=120)\ndef top_farms(year: int | None = None, limit: int = 10) -> pd.DataFrame:\n    """Most productive farms of the year."""\n    year = year or latest_year()\n    return read_df(\n        "SELECT fa.name AS farm, r.name AS region,"\n        " ROUND(SUM(y.production_t),0) AS production,"\n        " ROUND(AVG(y.yield_t_ha),2) AS avg_yield"\n        " FROM yield_records y"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE y.year = :y GROUP BY fa.id ORDER BY production DESC LIMIT :n",\n        {"y": year, "n": limit},\n    )\n',
    'analytics.timeseries': '"""Pure-numpy time-series toolkit: trend, seasonality, forecasting, anomalies."""\nfrom __future__ import annotations\n\nimport numpy as np\n\n\ndef moving_average(values: list[float], window: int = 3) -> list[float]:\n    """Simple trailing moving average (leading values use a growing window)."""\n    result: list[float] = []\n    for i in range(len(values)):\n        chunk = values[max(0, i - window + 1): i + 1]\n        result.append(float(np.mean(chunk)))\n    return result\n\n\ndef trend_slope(values: list[float]) -> float:\n    """Least-squares slope per step; 0 for degenerate series."""\n    if len(values) < 2:\n        return 0.0\n    x = np.arange(len(values), dtype=float)\n    return float(np.polyfit(x, np.asarray(values, dtype=float), 1)[0])\n\n\ndef linear_forecast(\n    values: list[float], periods: int = 1,\n) -> tuple[list[float], list[float], list[float]]:\n    """Linear-trend forecast with a residual-based ~95% confidence band."""\n    data = np.asarray(values, dtype=float)\n    if len(data) == 0:\n        return [], [], []\n    if len(data) == 1:\n        flat = [float(data[0])] * periods\n        return flat, flat, flat\n    x = np.arange(len(data), dtype=float)\n    slope, intercept = np.polyfit(x, data, 1)\n    residual_std = float(np.std(data - (slope * x + intercept)))\n    future_x = np.arange(len(data), len(data) + periods, dtype=float)\n    forecast = slope * future_x + intercept\n    band = 1.96 * residual_std * np.sqrt(1 + (future_x - x.mean()) ** 2 / max(1e-9, ((x - x.mean()) ** 2).sum()))\n    return (\n        [round(float(v), 3) for v in forecast],\n        [round(float(v), 3) for v in forecast - band],\n        [round(float(v), 3) for v in forecast + band],\n    )\n\n\ndef seasonal_forecast(\n    values: list[float], season_length: int = 12, periods: int = 12,\n) -> tuple[list[float], list[float], list[float]]:\n    """Trend + multiplicative seasonal-index forecast (classic decomposition)."""\n    data = np.asarray(values, dtype=float)\n    if len(data) < season_length * 2:\n        return linear_forecast(values, periods)\n    x = np.arange(len(data), dtype=float)\n    slope, intercept = np.polyfit(x, data, 1)\n    trend = slope * x + intercept\n    safe_trend = np.where(np.abs(trend) < 1e-9, 1e-9, trend)\n    ratio = data / safe_trend\n    seasonal = np.array([\n        float(np.mean(ratio[i::season_length])) for i in range(season_length)\n    ])\n    residual_std = float(np.std(data - trend * seasonal[np.arange(len(data)) % season_length]))\n    future_x = np.arange(len(data), len(data) + periods, dtype=float)\n    future_trend = slope * future_x + intercept\n    future_seasonal = seasonal[np.arange(len(data), len(data) + periods) % season_length]\n    forecast = future_trend * future_seasonal\n    return (\n        [round(float(v), 3) for v in forecast],\n        [round(float(v - 1.96 * residual_std), 3) for v in forecast],\n        [round(float(v + 1.96 * residual_std), 3) for v in forecast],\n    )\n\n\ndef zscore_anomalies(values: list[float], threshold: float = 2.0) -> list[int]:\n    """Indices whose z-score magnitude exceeds the threshold."""\n    data = np.asarray(values, dtype=float)\n    if len(data) < 3:\n        return []\n    std = data.std()\n    if std < 1e-12:\n        return []\n    z = (data - data.mean()) / std\n    return [int(i) for i in np.where(np.abs(z) > threshold)[0]]\n\n\ndef percent_change(previous: float, current: float) -> float:\n    """Safe percentage change from previous to current."""\n    if abs(previous) < 1e-12:\n        return 0.0\n    return round((current - previous) / abs(previous) * 100, 1)\n',
    'api': '"""REST API exposed by the embedded FastAPI app (token-protected)."""\n',
    'api.routes': '"""REST API routes registered on NiceGUI\'s underlying FastAPI application.\n\nAuth flow: POST /api/token with username/password -> signed HMAC bearer token;\nall data endpoints require ``Authorization: Bearer <token>``.\n"""\nfrom __future__ import annotations\n\nimport logging\nfrom dataclasses import asdict\n\nfrom fastapi import Depends, Header, HTTPException\nfrom pydantic import BaseModel\n\nfrom config import settings\nfrom core.security import (\n    api_limiter, create_token, login_limiter, verify_password, verify_token,\n)\nfrom database.engine import read_df, session_scope\nfrom database.models import User\n\nlog = logging.getLogger(__name__)\n\n\nclass TokenRequest(BaseModel):\n    username: str\n    password: str\n\n\ndef _require_token(authorization: str = Header(default="")) -> dict:\n    if not authorization.startswith("Bearer "):\n        raise HTTPException(status_code=401, detail="Bearer token talab qilinadi")\n    payload = verify_token(authorization.removeprefix("Bearer ").strip())\n    if payload is None:\n        raise HTTPException(status_code=401, detail="Token yaroqsiz yoki muddati o\'tgan")\n    if api_limiter.is_locked(payload["sub"]):\n        raise HTTPException(status_code=429, detail="So\'rovlar chegarasi oshib ketdi")\n    api_limiter.register_failure(payload["sub"])  # counts requests per minute\n    return payload\n\n\ndef register_api() -> None:\n    """Attach every /api/* route to the running FastAPI app."""\n    from nicegui import app\n\n    @app.get("/api/health")\n    def health() -> dict:\n        from database.engine import db_stats\n\n        return {"status": "ok", "app": settings.APP_NAME,\n                "version": settings.APP_VERSION, "tables": db_stats()}\n\n    @app.post("/api/token")\n    def token(request: TokenRequest) -> dict:\n        if login_limiter.is_locked(request.username):\n            raise HTTPException(status_code=429,\n                                detail="Juda ko\'p urinish — keyinroq qayta urining")\n        with session_scope() as session:\n            user = session.query(User).filter_by(\n                username=request.username, active=True).first()\n        if user is None or not verify_password(request.password, user.password_hash):\n            login_limiter.register_failure(request.username)\n            raise HTTPException(status_code=401, detail="Login yoki parol noto\'g\'ri")\n        login_limiter.register_success(request.username)\n        return {"access_token": create_token(user.username, user.role),\n                "token_type": "bearer", "role": user.role}\n\n    @app.get("/api/kpi")\n    def kpi(year: int | None = None, _payload: dict = Depends(_require_token)) -> dict:\n        from analytics.kpi import compute_kpi\n\n        return asdict(compute_kpi(year))\n\n    @app.get("/api/regions")\n    def regions(_payload: dict = Depends(_require_token)) -> list[dict]:\n        return read_df(\n            "SELECT id, name, lat, lon FROM regions ORDER BY name"\n        ).to_dict(orient="records")\n\n    @app.get("/api/yields")\n    def yields(year: int | None = None,\n               _payload: dict = Depends(_require_token)) -> list[dict]:\n        from analytics.kpi import latest_year, yield_by_region\n\n        return yield_by_region(year or latest_year()).to_dict(orient="records")\n\n    @app.get("/api/prices/{crop_id}")\n    def prices(crop_id: int, days: int = 365,\n               _payload: dict = Depends(_require_token)) -> list[dict]:\n        from market.service import price_history\n\n        df = price_history(crop_id, days)\n        df["date"] = df["date"].astype(str)\n        return df.to_dict(orient="records")\n\n    @app.get("/api/weather/{district_id}")\n    def weather(district_id: int, days: int = 90,\n                _payload: dict = Depends(_require_token)) -> list[dict]:\n        from weather.service import history_frame\n\n        df = history_frame(district_id, days)\n        df["date"] = df["date"].astype(str)\n        return df.to_dict(orient="records")\n\n    @app.post("/api/ai/ask")\n    def ai_ask(question: dict, payload: dict = Depends(_require_token)) -> dict:\n        from ai.engine import assistant\n\n        result = assistant.ask(str(question.get("question", "")))\n        table = result.get("table")\n        return {\n            "answer": result["answer"],\n            "table": table.to_dict(orient="records") if table is not None else None,\n            "asked_by": payload["sub"],\n        }\n\n    log.info("REST API marshrutlari ro\'yxatdan o\'tdi (/api/*).")\n',
    'app': '"""Application layer: NiceGUI assembly, theme, layout, charts."""\n',
    'app.charts': '"""ECharts option builders (rendered offline via NiceGUI\'s bundled ECharts)."""\nfrom __future__ import annotations\n\nfrom typing import Any, Sequence\n\nfrom app.theme import PALETTE\n\n_BASE: dict[str, Any] = {\n    "animationDuration": 400,\n    "grid": {"left": 60, "right": 24, "top": 48, "bottom": 42},\n    "tooltip": {"trigger": "axis"},\n}\n\n\ndef _title(text: str) -> dict[str, Any]:\n    return {"text": text, "textStyle": {"fontSize": 14}}\n\n\ndef line_chart(title: str, x: Sequence, series: dict[str, Sequence],\n               y_name: str = "", dashed: set[str] | None = None) -> dict[str, Any]:\n    """Multi-series line chart; names in ``dashed`` render as dashed lines."""\n    dashed = dashed or set()\n    return {\n        **_BASE,\n        "title": _title(title),\n        "color": PALETTE,\n        "legend": {"top": 24},\n        "xAxis": {"type": "category", "data": list(x)},\n        "yAxis": {"type": "value", "name": y_name},\n        "series": [\n            {\n                "name": name, "type": "line", "smooth": True,\n                "data": [None if v is None else round(float(v), 3) for v in values],\n                "lineStyle": {"type": "dashed" if name in dashed else "solid"},\n                "connectNulls": False,\n            }\n            for name, values in series.items()\n        ],\n    }\n\n\ndef bar_chart(title: str, x: Sequence, series: dict[str, Sequence],\n              horizontal: bool = False, y_name: str = "") -> dict[str, Any]:\n    """Vertical or horizontal bar chart."""\n    category_axis = {"type": "category", "data": list(x)}\n    value_axis = {"type": "value", "name": y_name}\n    return {\n        **_BASE,\n        "title": _title(title),\n        "color": PALETTE,\n        "legend": {"top": 24} if len(series) > 1 else {"show": False},\n        "xAxis": value_axis if horizontal else category_axis,\n        "yAxis": category_axis if horizontal else value_axis,\n        "series": [\n            {"name": name, "type": "bar",\n             "data": [round(float(v), 2) for v in values]}\n            for name, values in series.items()\n        ],\n    }\n\n\ndef pie_chart(title: str, pairs: list[tuple[str, float]]) -> dict[str, Any]:\n    """Donut chart for share breakdowns."""\n    return {\n        "title": _title(title),\n        "color": PALETTE,\n        "tooltip": {"trigger": "item", "formatter": "{b}: {c} ({d}%)"},\n        "legend": {"orient": "vertical", "left": "left", "top": 40,\n                   "textStyle": {"fontSize": 10}},\n        "series": [{\n            "type": "pie", "radius": ["38%", "68%"], "center": ["60%", "55%"],\n            "itemStyle": {"borderRadius": 6},\n            "label": {"show": False},\n            "data": [{"name": name, "value": round(float(value), 1)}\n                     for name, value in pairs],\n        }],\n    }\n\n\ndef heatmap_chart(title: str, x_labels: Sequence[str], y_labels: Sequence[str],\n                  points: list[list[float]], unit: str = "") -> dict[str, Any]:\n    """Matrix heatmap; points are [x_index, y_index, value]."""\n    values = [p[2] for p in points] or [0]\n    return {\n        "title": _title(title),\n        "tooltip": {"position": "top"},\n        "grid": {"left": 110, "right": 30, "top": 40, "bottom": 90},\n        "xAxis": {"type": "category", "data": list(x_labels),\n                  "axisLabel": {"rotate": 45, "fontSize": 10}},\n        "yAxis": {"type": "category", "data": list(y_labels),\n                  "axisLabel": {"fontSize": 10}},\n        "visualMap": {\n            "min": min(values), "max": max(values), "calculable": True,\n            "orient": "horizontal", "left": "center", "bottom": 0,\n            "inRange": {"color": ["#c62828", "#f9a825", "#2e7d32"]},\n        },\n        "series": [{"type": "heatmap", "data": points,\n                    "label": {"show": True, "fontSize": 9, "formatter": "{@[2]}"},\n                    "tooltip": {"valueFormatter": f"value => value + \' {unit}\'"}}],\n    }\n\n\ndef scatter_chart(title: str, points: list[list[float]], x_name: str,\n                  y_name: str) -> dict[str, Any]:\n    """Scatter plot for correlation views."""\n    return {\n        "title": _title(title),\n        "color": PALETTE,\n        "tooltip": {"trigger": "item"},\n        "grid": {"left": 60, "right": 30, "top": 48, "bottom": 48},\n        "xAxis": {"type": "value", "name": x_name, "nameLocation": "middle",\n                  "nameGap": 28},\n        "yAxis": {"type": "value", "name": y_name},\n        "series": [{"type": "scatter", "symbolSize": 9, "data": points,\n                    "itemStyle": {"opacity": 0.75}}],\n    }\n\n\ndef gauge_chart(title: str, value: float, max_value: float = 100,\n                unit: str = "%") -> dict[str, Any]:\n    """Single-value gauge (e.g. disease-risk probability)."""\n    return {\n        "title": _title(title),\n        "series": [{\n            "type": "gauge", "min": 0, "max": max_value,\n            "progress": {"show": True, "width": 14},\n            "axisLine": {"lineStyle": {"width": 14}},\n            "axisTick": {"show": False}, "splitLine": {"length": 8},\n            "detail": {"formatter": f"{{value}}{unit}", "fontSize": 20},\n            "data": [{"value": round(value, 1)}],\n            "color": ["#2e7d32"],\n        }],\n    }\n',
    'app.layout': '"""Shared page shell: header, sidebar, auth guard, search, reusable widgets."""\nfrom __future__ import annotations\n\nimport logging\nfrom contextlib import contextmanager\nfrom typing import Iterator\n\nimport pandas as pd\nfrom nicegui import app, ui\n\nfrom app import theme\nfrom config import settings\nfrom core.i18n import translate\nfrom core.plugin_manager import get_plugins\nfrom core.security import audit, has_permission\nfrom database.engine import get_setting\n\nlog = logging.getLogger(__name__)\n\nNAV_ITEMS: list[tuple[str, str, str, str]] = [\n    ("/", "space_dashboard", "Bosh sahifa", "view_dashboard"),\n    ("/map", "map", "Xarita", "view_dashboard"),\n    ("/analytics", "insights", "Analitika", "view_dashboard"),\n    ("/ml", "psychology", "Machine Learning", "view_dashboard"),\n    ("/satellite", "satellite_alt", "Sun\'iy yo\'ldosh", "view_dashboard"),\n    ("/weather", "partly_cloudy_day", "Ob-havo", "view_dashboard"),\n    ("/market", "storefront", "Bozor", "view_dashboard"),\n    ("/irrigation", "water_drop", "Sug\'orish", "view_dashboard"),\n    ("/finance", "payments", "Moliya", "view_finance"),\n    ("/ai", "smart_toy", "AI Yordamchi", "use_ai"),\n    ("/reports", "description", "Hisobotlar", "export_reports"),\n    ("/admin", "admin_panel_settings", "Administrator", "manage_users"),\n    ("/settings", "settings", "Sozlamalar", "manage_settings"),\n]\n\n\n# --------------------------------------------------------------------------\n# Auth helpers\n# --------------------------------------------------------------------------\ndef current_user() -> dict | None:\n    """The authenticated user dict from the per-browser session storage."""\n    return app.storage.user.get("auth")\n\n\ndef require_login(permission: str | None = None) -> dict | None:\n    """Guard for pages: redirects to /login (or /) when access is missing."""\n    user = current_user()\n    if user is None:\n        ui.navigate.to("/login")\n        return None\n    if permission and not has_permission(user.get("role"), permission):\n        ui.notify("Bu bo\'limga ruxsatingiz yo\'q.", type="negative")\n        ui.navigate.to("/")\n        return None\n    return user\n\n\ndef logout() -> None:\n    user = current_user()\n    if user:\n        audit("logout", user["username"])\n    app.storage.user.clear()\n    ui.navigate.to("/login")\n\n\ndef lang() -> str:\n    return app.storage.user.get("language") or get_setting("language", "uz")\n\n\ndef t(text: str) -> str:\n    return translate(text, lang())\n\n\n# --------------------------------------------------------------------------\n# Page shell\n# --------------------------------------------------------------------------\n@contextmanager\ndef shell(user: dict, title: str) -> Iterator[None]:\n    """Standard chrome: header, nav drawer, content column."""\n    theme.apply()\n    stored_dark = app.storage.user.get("dark_mode")\n    if stored_dark is None:\n        stored_dark = get_setting("theme", "light") == "dark"\n    dark = ui.dark_mode(value=bool(stored_dark))\n\n    with ui.left_drawer(value=True, bordered=True).props("width=230") as drawer:\n        with ui.row().classes("items-center gap-2 p-2"):\n            ui.icon("agriculture").classes("text-3xl text-primary")\n            with ui.column().classes("gap-0"):\n                ui.label(settings.APP_NAME).classes("text-lg font-bold text-primary")\n                ui.label(f"v{settings.APP_VERSION}").classes("text-xs opacity-60")\n        ui.separator()\n        for route, icon, label, permission in NAV_ITEMS:\n            if not has_permission(user["role"], permission):\n                continue\n            ui.button(t(label), icon=icon,\n                      on_click=lambda r=route: ui.navigate.to(r)) \\\n                .props("flat no-caps align=left").classes("w-full nav-btn")\n        plugins = get_plugins()\n        if plugins:\n            ui.separator()\n            ui.label("Plaginlar").classes("text-xs opacity-60 pl-3")\n            for plugin in plugins:\n                ui.button(plugin.name, icon=plugin.icon,\n                          on_click=lambda r=plugin.route: ui.navigate.to(r)) \\\n                    .props("flat no-caps align=left").classes("w-full nav-btn")\n\n    with ui.header(elevated=True).classes("items-center justify-between px-3"):\n        with ui.row().classes("items-center gap-2"):\n            ui.button(icon="menu", on_click=drawer.toggle) \\\n                .props("flat round color=white")\n            ui.label(title).classes("text-lg font-medium")\n        with ui.row().classes("items-center gap-2"):\n            search_input = ui.input(placeholder=t("Qidiruv") + "...") \\\n                .props("dense standout dark clearable").classes("w-56")\n            search_input.on("keydown.enter",\n                            lambda: _open_search(search_input.value or ""))\n            _online_chip()\n            ui.button(icon="dark_mode",\n                      on_click=lambda: _toggle_dark(dark)) \\\n                .props("flat round color=white").tooltip("Tungi/kunduzgi rejim")\n            with ui.button(icon="account_circle").props("flat round color=white"):\n                with ui.menu():\n                    ui.menu_item(f"{user[\'name\']} ({user[\'role\']})") \\\n                        .props("disable")\n                    ui.separator()\n                    ui.menu_item(t("Chiqish"), on_click=logout)\n\n    content = ui.column().classes("w-full p-4 gap-4 max-w-[1500px] mx-auto")\n    with content:\n        yield\n\n\ndef _toggle_dark(dark: ui.dark_mode) -> None:\n    dark.value = not dark.value\n    app.storage.user["dark_mode"] = dark.value\n\n\ndef _online_chip() -> None:\n    from weather.service import is_online\n\n    online = is_online()\n    ui.chip(t("Onlayn") if online else t("Offlayn rejim"),\n            icon="wifi" if online else "wifi_off",\n            color="green-6" if online else "orange-8") \\\n        .props("dense text-color=white")\n\n\ndef _open_search(query: str) -> None:\n    from utils.search import global_search\n\n    results = global_search(query)\n    with ui.dialog() as dialog, ui.card().classes("min-w-[560px]"):\n        ui.label(f"Qidiruv: “{query}” — {len(results)} natija") \\\n            .classes("text-lg font-medium")\n        if results.empty:\n            ui.label("Hech narsa topilmadi.").classes("opacity-70")\n        else:\n            df_table(results, rows_per_page=8)\n        ui.button("Yopish", on_click=dialog.close).props("flat")\n    dialog.open()\n\n\n# --------------------------------------------------------------------------\n# Reusable widgets\n# --------------------------------------------------------------------------\ndef kpi_card(icon: str, value: str, label: str, color: str = "primary") -> None:\n    """Small KPI stat card used across dashboards."""\n    with ui.card().classes("kpi-card items-start p-4"):\n        ui.icon(icon).classes(f"text-2xl text-{color}")\n        ui.label(value).classes("kpi-value")\n        ui.label(label).classes("kpi-label")\n\n\ndef df_table(df: pd.DataFrame, rows_per_page: int = 10,\n             title: str | None = None) -> None:\n    """Render any DataFrame as a sortable, paginated table."""\n    if title:\n        ui.label(title).classes("section-title")\n    if df is None or df.empty:\n        ui.label("Ma\'lumot topilmadi.").classes("opacity-70")\n        return\n    display = df.copy()\n    for column in display.columns:\n        if pd.api.types.is_float_dtype(display[column]):\n            display[column] = display[column].round(2)\n    columns = [{"name": str(column), "label": str(column).replace("_", " ").title(),\n                "field": str(column), "sortable": True, "align": "left"}\n               for column in display.columns]\n    ui.table(columns=columns, rows=display.to_dict(orient="records"),\n             pagination=rows_per_page).classes("w-full")\n\n\ndef chart(options: dict, height: str = "h-80") -> None:\n    """Render an ECharts options dict inside a styled card."""\n    with ui.card().classes("chart-card"):\n        ui.echart(options).classes(f"w-full {height}")\n\n\ndef download_file(path) -> None:\n    """Trigger a browser download for a server-side file (NiceGUI 2/3 API)."""\n    try:\n        ui.download.file(str(path))  # NiceGUI >= 2.14\n    except AttributeError:\n        ui.download(str(path))\n\n\ndef raw_html(content: str) -> ui.html:\n    """Render trusted server-generated HTML (e.g. folium maps) unsanitized.\n\n    NiceGUI 3.x sanitizes ui.html by default, which strips the map iframe;\n    our content never contains user input, so it is safe to disable.\n    """\n    try:\n        return ui.html(content, sanitize=False)  # NiceGUI >= 3.0\n    except TypeError:\n        return ui.html(content)\n',
    'app.main': '"""NiceGUI application assembly and launch."""\nfrom __future__ import annotations\n\nimport logging\n\nfrom config import settings\n\nlog = logging.getLogger(__name__)\n\n\ndef start(host: str = settings.DEFAULT_HOST, port: int = settings.DEFAULT_PORT,\n          open_browser: bool = True, debug: bool = False) -> None:\n    """Register pages, API, plugins and background jobs, then run the server."""\n    from nicegui import ui\n\n    import dashboard.pages  # noqa: F401 - registers every @ui.page route\n    from api.routes import register_api\n    from core import background\n    from core.plugin_manager import load_plugins\n\n    register_api()\n    load_plugins()\n    background.start_default_jobs()\n\n    log.info("Dashboard ishga tushmoqda: http://%s:%d", host, port)\n    ui.run(\n        host=host,\n        port=port,\n        title=settings.APP_TITLE,\n        favicon="🌾",\n        storage_secret=settings.get_storage_secret(),\n        reload=False,\n        show=open_browser,\n        uvicorn_logging_level="warning",\n    )\n',
    'app.theme': '"""Visual theme: brand colors and global CSS for the enterprise dashboard."""\nfrom __future__ import annotations\n\nPRIMARY = "#2e7d32"\nSECONDARY = "#66bb6a"\nACCENT = "#f9a825"\n\nPALETTE = ["#2e7d32", "#66bb6a", "#f9a825", "#ef6c00", "#0288d1",\n           "#7b1fa2", "#c62828", "#00897b", "#5d4037", "#3949ab"]\n\nGLOBAL_CSS = """\n.kpi-card {border-radius: 14px; min-width: 170px; transition: transform .15s;}\n.kpi-card:hover {transform: translateY(-3px);}\n.kpi-value {font-size: 1.55rem; font-weight: 700; line-height: 1.2;}\n.kpi-label {font-size: .8rem; opacity: .75;}\n.nav-btn {justify-content: flex-start !important; text-transform: none !important;}\n.section-title {font-size: 1.1rem; font-weight: 600; margin-top: .25rem;}\n.chart-card {border-radius: 14px; width: 100%;}\n.alert-error {border-left: 4px solid #c62828;}\n.alert-warning {border-left: 4px solid #f9a825;}\n.alert-info {border-left: 4px solid #0288d1;}\n::-webkit-scrollbar {width: 9px; height: 9px;}\n::-webkit-scrollbar-thumb {background: #9e9e9e66; border-radius: 5px;}\n"""\n\n\ndef apply() -> None:\n    """Apply brand colors + CSS to the current client."""\n    from nicegui import ui\n\n    ui.colors(primary=PRIMARY, secondary=SECONDARY, accent=ACCENT,\n              positive="#43a047", negative="#c62828", warning="#f9a825")\n    ui.add_css(GLOBAL_CSS)\n',
    'config': '"""Configuration package for the AgroVision platform."""\n',
    'config.settings': '"""AgroVision — application configuration, filesystem layout and constants.\n\nEvery path in the project is derived from ``BASE_DIR`` so the whole platform\nworks both as the modular package and as the generated single-file monolith.\n"""\nfrom __future__ import annotations\n\nimport os\nimport secrets\nimport sys\nfrom pathlib import Path\n\nAPP_NAME = "AgroVision"\nAPP_TITLE = "AgroVision — Qishloq xo\'jaligi analitik platformasi"\nAPP_VERSION = "1.0.0"\nDEFAULT_HOST = "127.0.0.1"\nDEFAULT_PORT = 8080\n\n\ndef _resolve_base_dir() -> Path:\n    """Resolve the project root for both modular and monolith execution."""\n    env = os.environ.get("AGRIDASH_HOME")\n    if env:\n        return Path(env).resolve()\n    main = sys.modules.get("__main__")\n    main_file = getattr(main, "__file__", None)\n    if main_file:\n        candidate = Path(main_file).resolve().parent\n        if (\n            (candidate / "run.py").exists()\n            or (candidate / "AgricultureDashboard.py").exists()\n            or (candidate / "config").is_dir()\n        ):\n            return candidate\n    return Path.cwd()\n\n\nBASE_DIR: Path = _resolve_base_dir()\nDATA_DIR = BASE_DIR / "data"\nCACHE_DIR = DATA_DIR / "cache"\nLOG_DIR = BASE_DIR / "logs"\nBACKUP_DIR = BASE_DIR / "backups"\nEXPORT_DIR = BASE_DIR / "exports"\nUPLOAD_DIR = BASE_DIR / "uploads"\nMODELS_DIR = BASE_DIR / "models"\nSTATIC_DIR = BASE_DIR / "static"\nTEMPLATES_DIR = BASE_DIR / "templates"\nPLUGINS_DIR = BASE_DIR / "plugins"\n\nRUNTIME_DIRS = [\n    DATA_DIR, CACHE_DIR, LOG_DIR, BACKUP_DIR, EXPORT_DIR,\n    UPLOAD_DIR, MODELS_DIR, STATIC_DIR, TEMPLATES_DIR, PLUGINS_DIR,\n]\n\nDB_PATH = DATA_DIR / "agriculture.db"\nSECRET_FILE = DATA_DIR / "secret.key"\n\n# pip package name -> importable module name\nREQUIRED_PACKAGES: dict[str, str] = {\n    "nicegui": "nicegui",\n    "sqlalchemy": "sqlalchemy",\n    "pandas": "pandas",\n    "numpy": "numpy",\n    "requests": "requests",\n    "openpyxl": "openpyxl",\n    "folium": "folium",\n    "fpdf2": "fpdf",\n    "scikit-learn": "sklearn",\n}\n\n# Optional accelerators / integrations — the platform degrades gracefully\n# to fully working fallbacks when any of these are missing.\nOPTIONAL_PACKAGES: dict[str, str] = {\n    "xgboost": "xgboost",\n    "lightgbm": "lightgbm",\n    "catboost": "catboost",\n    "tensorflow": "tensorflow",\n    "geopandas": "geopandas",\n    "shapely": "shapely",\n    "pyproj": "pyproj",\n    "fiona": "fiona",\n    "rasterio": "rasterio",\n    "pyshp": "shapefile",\n    "python-docx": "docx",\n    "matplotlib": "matplotlib",\n    "meteostat": "meteostat",\n    "earthengine-api": "ee",\n    "Pillow": "PIL",\n    "cryptography": "cryptography",\n}\n\n# Default values written into the ``settings`` table on first launch.\nDEFAULT_SETTINGS: dict[str, str] = {\n    "theme": "light",\n    "language": "uz",\n    "offline_mode": "auto",              # auto | on | off\n    "weather_provider": "open-meteo",    # open-meteo | nasa-power\n    "gee_service_account": "",\n    "gee_key_file": "",\n    "planet_api_key": "",\n    "map_default_lat": "41.3",\n    "map_default_lon": "64.5",\n    "map_default_zoom": "6",\n    "ml_auto_retrain_days": "30",\n    "backup_keep": "20",\n    "auto_backup_hours": "24",\n}\n\nTOKEN_TTL_SECONDS = 12 * 3600\nLOGIN_MAX_ATTEMPTS = 5\nLOGIN_LOCK_MINUTES = 10\nAPI_RATE_LIMIT_PER_MINUTE = 120\n\nWEATHER_SEASON_MONTHS = (4, 5, 6, 7, 8, 9)   # vegetation season Apr..Sep\nHISTORY_START_YEAR = 2021\n\n\ndef ensure_directories() -> None:\n    """Installer step: create every runtime folder if missing."""\n    for directory in RUNTIME_DIRS:\n        directory.mkdir(parents=True, exist_ok=True)\n\n\ndef get_storage_secret() -> str:\n    """Persistent random secret used for sessions and API token signing."""\n    ensure_directories()\n    if SECRET_FILE.exists():\n        secret = SECRET_FILE.read_text(encoding="utf-8").strip()\n        if secret:\n            return secret\n    secret = secrets.token_hex(32)\n    SECRET_FILE.write_text(secret, encoding="utf-8")\n    return secret\n',
    'core': '"""Core infrastructure: logging, security, caching, plugins, background jobs."""\n',
    'core.background': '"""Background execution: shared thread pool and periodic daemon jobs."""\nfrom __future__ import annotations\n\nimport logging\nimport threading\nfrom concurrent.futures import Future, ThreadPoolExecutor\nfrom typing import Any, Callable\n\nlog = logging.getLogger(__name__)\n\n_executor = ThreadPoolExecutor(max_workers=4, thread_name_prefix="agro-bg")\n_periodic_stops: dict[str, threading.Event] = {}\n\n\ndef submit(func: Callable[..., Any], *args: Any, **kwargs: Any) -> Future:\n    """Run a task on the shared background pool with error logging."""\n\n    def safe() -> Any:\n        try:\n            return func(*args, **kwargs)\n        except Exception:  # noqa: BLE001\n            log.exception("Background task \'%s\' failed", getattr(func, "__name__", func))\n            return None\n\n    return _executor.submit(safe)\n\n\ndef start_periodic(name: str, interval_seconds: float, func: Callable[[], Any],\n                   run_immediately: bool = False) -> None:\n    """Start (or restart) a named periodic daemon job."""\n    stop_periodic(name)\n    stop = threading.Event()\n    _periodic_stops[name] = stop\n\n    def loop() -> None:\n        if run_immediately:\n            submit(func)\n        while not stop.wait(interval_seconds):\n            submit(func)\n\n    thread = threading.Thread(target=loop, name=f"periodic-{name}", daemon=True)\n    thread.start()\n    log.info("Periodic job \'%s\' started (every %.0fs)", name, interval_seconds)\n\n\ndef stop_periodic(name: str) -> None:\n    """Signal a periodic job to stop."""\n    event = _periodic_stops.pop(name, None)\n    if event:\n        event.set()\n\n\ndef start_default_jobs() -> None:\n    """Kick off the platform\'s standing background jobs."""\n    from database import backup as db_backup\n    from database.engine import get_setting\n    from weather.service import refresh_all_districts\n\n    hours = float(get_setting("auto_backup_hours", "24") or 24)\n    start_periodic("auto-backup", hours * 3600, lambda: db_backup.create_backup("auto"))\n    start_periodic("weather-refresh", 3600, refresh_all_districts, run_immediately=True)\n',
    'core.cache': '"""Thread-safe in-process TTL cache with a decorator API."""\nfrom __future__ import annotations\n\nimport functools\nimport threading\nimport time\nfrom typing import Any, Callable, TypeVar\n\nF = TypeVar("F", bound=Callable[..., Any])\n\n_registry: list["TTLCache"] = []\n_registry_lock = threading.Lock()\n\n\nclass TTLCache:\n    """Small dictionary cache where each entry expires after ``ttl`` seconds."""\n\n    def __init__(self, ttl: float = 300.0, max_items: int = 512) -> None:\n        self.ttl = ttl\n        self.max_items = max_items\n        self._data: dict[Any, tuple[float, Any]] = {}\n        self._lock = threading.Lock()\n        with _registry_lock:\n            _registry.append(self)\n\n    def get(self, key: Any) -> Any | None:\n        with self._lock:\n            entry = self._data.get(key)\n            if entry is None:\n                return None\n            expires, value = entry\n            if time.monotonic() > expires:\n                del self._data[key]\n                return None\n            return value\n\n    def set(self, key: Any, value: Any) -> None:\n        with self._lock:\n            if len(self._data) >= self.max_items:\n                # Drop the oldest half to stay bounded.\n                for stale in sorted(self._data, key=lambda k: self._data[k][0])[\n                    : self.max_items // 2\n                ]:\n                    del self._data[stale]\n            self._data[key] = (time.monotonic() + self.ttl, value)\n\n    def clear(self) -> None:\n        with self._lock:\n            self._data.clear()\n\n    def __len__(self) -> int:\n        with self._lock:\n            return len(self._data)\n\n\ndef cached(ttl: float = 300.0) -> Callable[[F], F]:\n    """Decorator caching a function\'s result per-arguments for ``ttl`` seconds."""\n\n    def decorator(func: F) -> F:\n        store = TTLCache(ttl=ttl)\n\n        @functools.wraps(func)\n        def wrapper(*args: Any, **kwargs: Any) -> Any:\n            key = (args, tuple(sorted(kwargs.items())))\n            hit = store.get(key)\n            if hit is not None:\n                return hit\n            value = func(*args, **kwargs)\n            if value is not None:\n                store.set(key, value)\n            return value\n\n        wrapper.cache = store  # type: ignore[attr-defined]\n        return wrapper  # type: ignore[return-value]\n\n    return decorator\n\n\ndef clear_all_caches() -> int:\n    """Flush every registered cache (used after imports / restores)."""\n    with _registry_lock:\n        for cache in _registry:\n            cache.clear()\n        return len(_registry)\n',
    'core.i18n': '"""Lightweight i18n for UI chrome. Default language is Uzbek (latin)."""\nfrom __future__ import annotations\n\n_TRANSLATIONS: dict[str, dict[str, str]] = {\n    "uz": {},  # Uzbek strings are the keys themselves.\n    "en": {\n        "Bosh sahifa": "Home",\n        "Xarita": "Map",\n        "Analitika": "Analytics",\n        "Ob-havo": "Weather",\n        "Bozor": "Market",\n        "Sug\'orish": "Irrigation",\n        "Moliya": "Finance",\n        "Sun\'iy yo\'ldosh": "Satellite",\n        "Machine Learning": "Machine Learning",\n        "AI Yordamchi": "AI Assistant",\n        "Hisobotlar": "Reports",\n        "Administrator": "Administrator",\n        "Sozlamalar": "Settings",\n        "Chiqish": "Log out",\n        "Qidiruv": "Search",\n        "Kirish": "Sign in",\n        "Offlayn rejim": "Offline mode",\n        "Onlayn": "Online",\n    },\n    "ru": {\n        "Bosh sahifa": "Главная",\n        "Xarita": "Карта",\n        "Analitika": "Аналитика",\n        "Ob-havo": "Погода",\n        "Bozor": "Рынок",\n        "Sug\'orish": "Орошение",\n        "Moliya": "Финансы",\n        "Sun\'iy yo\'ldosh": "Спутник",\n        "Machine Learning": "Машинное обучение",\n        "AI Yordamchi": "AI Ассистент",\n        "Hisobotlar": "Отчёты",\n        "Administrator": "Администратор",\n        "Sozlamalar": "Настройки",\n        "Chiqish": "Выход",\n        "Qidiruv": "Поиск",\n        "Kirish": "Вход",\n        "Offlayn rejim": "Оффлайн режим",\n        "Onlayn": "Онлайн",\n    },\n}\n\nLANGUAGES = {"uz": "O\'zbekcha", "en": "English", "ru": "Русский"}\n\n\ndef translate(text: str, language: str = "uz") -> str:\n    """Translate a UI string; unknown keys fall back to the Uzbek original."""\n    return _TRANSLATIONS.get(language, {}).get(text, text)\n',
    'core.logging_setup': '"""Centralised logging configuration with rotating files and crash reports."""\nfrom __future__ import annotations\n\nimport logging\nimport sys\nimport traceback\nfrom datetime import datetime\nfrom logging.handlers import RotatingFileHandler\n\nfrom config import settings\n\n_configured = False\n\n\ndef setup_logging(debug: bool = False) -> logging.Logger:\n    """Configure root logging once: console + rotating file + crash hook."""\n    global _configured\n    logger = logging.getLogger()\n    if _configured:\n        logger.setLevel(logging.DEBUG if debug else logging.INFO)\n        return logger\n\n    settings.ensure_directories()\n    logger.setLevel(logging.DEBUG if debug else logging.INFO)\n    fmt = logging.Formatter(\n        "%(asctime)s | %(levelname)-8s | %(name)s | %(message)s",\n        datefmt="%Y-%m-%d %H:%M:%S",\n    )\n\n    file_handler = RotatingFileHandler(\n        settings.LOG_DIR / "agrovision.log",\n        maxBytes=2_000_000,\n        backupCount=5,\n        encoding="utf-8",\n    )\n    file_handler.setFormatter(fmt)\n    logger.addHandler(file_handler)\n\n    console = logging.StreamHandler(sys.stdout)\n    console.setFormatter(fmt)\n    console.setLevel(logging.INFO if not debug else logging.DEBUG)\n    logger.addHandler(console)\n\n    # Quieten noisy third-party loggers.\n    for noisy in ("watchfiles", "urllib3", "httpx", "matplotlib", "fontTools"):\n        logging.getLogger(noisy).setLevel(logging.WARNING)\n\n    sys.excepthook = _crash_hook\n    _configured = True\n    return logger\n\n\ndef _crash_hook(exc_type, exc_value, exc_tb) -> None:\n    """Write an unhandled exception to a timestamped crash report file."""\n    if issubclass(exc_type, KeyboardInterrupt):\n        sys.__excepthook__(exc_type, exc_value, exc_tb)\n        return\n    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n    report = settings.LOG_DIR / f"crash_{stamp}.txt"\n    try:\n        text = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))\n        report.write_text(\n            f"{settings.APP_NAME} {settings.APP_VERSION} crash report\\n"\n            f"Time: {datetime.now().isoformat()}\\n\\n{text}",\n            encoding="utf-8",\n        )\n    except OSError:\n        pass\n    logging.getLogger("crash").critical(\n        "Unhandled exception", exc_info=(exc_type, exc_value, exc_tb)\n    )\n',
    'core.optional': '"""Safe optional-dependency loader.\n\nHeavy or platform-fragile libraries (GeoPandas, Rasterio, TensorFlow, ...)\nare imported through :func:`try_import` so a missing wheel never breaks the\nplatform — every feature has a pure-Python fallback path.\n"""\nfrom __future__ import annotations\n\nimport importlib\nimport importlib.util\nimport logging\nfrom types import ModuleType\n\nlog = logging.getLogger(__name__)\n_cache: dict[str, ModuleType | None] = {}\n\n\ndef try_import(module_name: str) -> ModuleType | None:\n    """Import a module, returning ``None`` (and caching) when unavailable."""\n    if module_name in _cache:\n        return _cache[module_name]\n    try:\n        if importlib.util.find_spec(module_name) is None:\n            _cache[module_name] = None\n            return None\n        module = importlib.import_module(module_name)\n        _cache[module_name] = module\n        return module\n    except Exception as exc:  # pragma: no cover - import-time env issues\n        log.warning("Optional module \'%s\' failed to import: %s", module_name, exc)\n        _cache[module_name] = None\n        return None\n\n\ndef available(module_name: str) -> bool:\n    """Return True when the optional module can be imported."""\n    return try_import(module_name) is not None\n\n\ndef optional_status() -> dict[str, bool]:\n    """Availability map of every registered optional package."""\n    from config import settings\n\n    return {pip: available(mod) for pip, mod in settings.OPTIONAL_PACKAGES.items()}\n',
    'core.plugin_manager': '"""Plugin system: drop a .py file into ``plugins/`` and it appears in the UI.\n\nContract — each plugin module defines:\n\n    PLUGIN = {"name": "...", "icon": "...", "route": "/plugin/..."}\n\n    def register() -> None:\n        # registers its own @ui.page(PLUGIN["route"]) here\n"""\nfrom __future__ import annotations\n\nimport importlib.util\nimport logging\nfrom dataclasses import dataclass\n\nfrom config import settings\n\nlog = logging.getLogger(__name__)\n\n\n@dataclass\nclass PluginInfo:\n    name: str\n    icon: str\n    route: str\n    module_name: str\n\n\n_plugins: list[PluginInfo] = []\n_loaded = False\n\n\ndef load_plugins() -> list[PluginInfo]:\n    """Import every plugin module once and collect nav metadata."""\n    global _loaded\n    if _loaded:\n        return _plugins\n    _loaded = True\n    settings.ensure_directories()\n    for path in sorted(settings.PLUGINS_DIR.glob("*.py")):\n        if path.name.startswith("_"):\n            continue\n        module_name = f"agro_plugin_{path.stem}"\n        try:\n            spec = importlib.util.spec_from_file_location(module_name, path)\n            if spec is None or spec.loader is None:\n                continue\n            module = importlib.util.module_from_spec(spec)\n            spec.loader.exec_module(module)\n            meta = getattr(module, "PLUGIN", None)\n            register = getattr(module, "register", None)\n            if not isinstance(meta, dict) or not callable(register):\n                log.warning("Plugin %s kontraktga mos emas — o\'tkazib yuborildi.", path.name)\n                continue\n            register()\n            _plugins.append(PluginInfo(\n                name=str(meta.get("name", path.stem)),\n                icon=str(meta.get("icon", "extension")),\n                route=str(meta.get("route", f"/plugin/{path.stem}")),\n                module_name=module_name,\n            ))\n            log.info("Plugin yuklandi: %s (%s)", meta.get("name"), path.name)\n        except Exception:  # noqa: BLE001 - one broken plugin must not kill the app\n            log.exception("Plugin yuklashda xato: %s", path.name)\n    return _plugins\n\n\ndef get_plugins() -> list[PluginInfo]:\n    """Loaded plugin registry (for the navigation drawer)."""\n    return _plugins\n',
    'core.security': '"""Security services: password hashing, HMAC tokens, RBAC, rate limiting, audit."""\nfrom __future__ import annotations\n\nimport base64\nimport hashlib\nimport hmac\nimport json\nimport logging\nimport secrets\nimport threading\nimport time\nfrom typing import Any\n\nfrom config import settings\n\nlog = logging.getLogger(__name__)\n\nPBKDF2_ITERATIONS = 120_000\n\n# Role -> set of granted permissions.\nROLES: dict[str, set[str]] = {\n    "admin": {\n        "view_dashboard", "edit_data", "import_data", "export_reports",\n        "manage_users", "manage_settings", "backup", "use_ai", "view_finance",\n    },\n    "manager": {\n        "view_dashboard", "edit_data", "import_data", "export_reports",\n        "use_ai", "view_finance",\n    },\n    "viewer": {"view_dashboard", "use_ai"},\n}\n\n\n# --------------------------------------------------------------------------\n# Password hashing (PBKDF2-HMAC-SHA256, constant-time verification)\n# --------------------------------------------------------------------------\ndef hash_password(password: str) -> str:\n    """Hash a password as ``pbkdf2$iterations$salt$digest`` (all hex)."""\n    salt = secrets.token_hex(16)\n    digest = hashlib.pbkdf2_hmac(\n        "sha256", password.encode("utf-8"), bytes.fromhex(salt), PBKDF2_ITERATIONS\n    ).hex()\n    return f"pbkdf2${PBKDF2_ITERATIONS}${salt}${digest}"\n\n\ndef verify_password(password: str, stored: str) -> bool:\n    """Constant-time verification of a password against a stored hash."""\n    try:\n        scheme, iterations, salt, digest = stored.split("$")\n        if scheme != "pbkdf2":\n            return False\n        candidate = hashlib.pbkdf2_hmac(\n            "sha256", password.encode("utf-8"), bytes.fromhex(salt), int(iterations)\n        ).hex()\n        return hmac.compare_digest(candidate, digest)\n    except (ValueError, TypeError):\n        return False\n\n\n# --------------------------------------------------------------------------\n# Signed API tokens (JWT-style: base64(payload).hex(hmac_sha256))\n# --------------------------------------------------------------------------\ndef create_token(username: str, role: str, ttl: int | None = None) -> str:\n    """Create a signed, expiring API token for the given user."""\n    payload = {\n        "sub": username,\n        "role": role,\n        "exp": int(time.time()) + (ttl or settings.TOKEN_TTL_SECONDS),\n        "jti": secrets.token_hex(8),\n    }\n    body = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode()\n    signature = hmac.new(\n        settings.get_storage_secret().encode("utf-8"), body.encode(), hashlib.sha256\n    ).hexdigest()\n    return f"{body}.{signature}"\n\n\ndef verify_token(token: str) -> dict[str, Any] | None:\n    """Return the payload for a valid non-expired token, else ``None``."""\n    try:\n        body, signature = token.split(".")\n        expected = hmac.new(\n            settings.get_storage_secret().encode("utf-8"), body.encode(), hashlib.sha256\n        ).hexdigest()\n        if not hmac.compare_digest(signature, expected):\n            return None\n        payload = json.loads(base64.urlsafe_b64decode(body.encode()))\n        if payload.get("exp", 0) < time.time():\n            return None\n        return payload\n    except (ValueError, TypeError, json.JSONDecodeError):\n        return None\n\n\n# --------------------------------------------------------------------------\n# RBAC helpers\n# --------------------------------------------------------------------------\ndef has_permission(role: str | None, permission: str) -> bool:\n    """Check whether a role grants a permission."""\n    return permission in ROLES.get(role or "", set())\n\n\n# --------------------------------------------------------------------------\n# Login rate limiting (in-process, per username)\n# --------------------------------------------------------------------------\nclass RateLimiter:\n    """Counts failures per key and locks the key after too many attempts."""\n\n    def __init__(self, max_attempts: int, lock_minutes: int) -> None:\n        self.max_attempts = max_attempts\n        self.lock_seconds = lock_minutes * 60\n        self._attempts: dict[str, list[float]] = {}\n        self._locked_until: dict[str, float] = {}\n        self._lock = threading.Lock()\n\n    def is_locked(self, key: str) -> bool:\n        with self._lock:\n            until = self._locked_until.get(key, 0)\n            if until > time.time():\n                return True\n            self._locked_until.pop(key, None)\n            return False\n\n    def register_failure(self, key: str) -> None:\n        now = time.time()\n        with self._lock:\n            history = [t for t in self._attempts.get(key, []) if now - t < 600]\n            history.append(now)\n            self._attempts[key] = history\n            if len(history) >= self.max_attempts:\n                self._locked_until[key] = now + self.lock_seconds\n                self._attempts[key] = []\n\n    def register_success(self, key: str) -> None:\n        with self._lock:\n            self._attempts.pop(key, None)\n            self._locked_until.pop(key, None)\n\n\nlogin_limiter = RateLimiter(settings.LOGIN_MAX_ATTEMPTS, settings.LOGIN_LOCK_MINUTES)\napi_limiter = RateLimiter(settings.API_RATE_LIMIT_PER_MINUTE, 1)\n\n\n# --------------------------------------------------------------------------\n# Audit trail\n# --------------------------------------------------------------------------\ndef audit(action: str, username: str = "system", details: str = "") -> None:\n    """Persist an audit record; failures are logged, never raised."""\n    try:\n        from database.engine import session_scope\n        from database.models import AuditLog\n\n        with session_scope() as session:\n            session.add(AuditLog(username=username, action=action, details=details[:1000]))\n    except Exception as exc:  # noqa: BLE001 - audit must never break the app\n        log.warning("Audit yozuvi saqlanmadi (%s): %s", action, exc)\n',
    'dashboard': '"""Dashboard package: every UI page of the platform."""\n',
    'dashboard.pages': '"""Page registry — importing this package registers every @ui.page route."""\nfrom dashboard.pages import (  # noqa: F401 - imports register the routes\n    admin_page,\n    ai_page,\n    analytics_page,\n    finance_page,\n    home,\n    irrigation_page,\n    login,\n    map_page,\n    market_page,\n    ml_page,\n    reports_page,\n    satellite_page,\n    settings_page,\n    weather_page,\n)\n',
    'dashboard.pages.admin_page': '"""Administration: users, audit log, backups, imported files, DB health."""\nfrom __future__ import annotations\n\nimport pandas as pd\nfrom nicegui import ui\n\nfrom app import layout\nfrom core.security import audit, hash_password\nfrom database import backup as db_backup\nfrom database.engine import db_stats, read_df, session_scope\nfrom database.models import User\n\n\ndef _users_frame() -> pd.DataFrame:\n    return read_df(\n        "SELECT id, username, full_name, role, active, created_at FROM users"\n        " ORDER BY id")\n\n\n@ui.page("/admin")\ndef admin_page() -> None:\n    user = layout.require_login("manage_users")\n    if user is None:\n        return\n    with layout.shell(user, "Administrator paneli"):\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            # ---------------- Users ---------------------------------------\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Foydalanuvchilar").classes("section-title")\n                users_box = ui.column().classes("w-full")\n\n                def render_users() -> None:\n                    users_box.clear()\n                    with users_box:\n                        layout.df_table(_users_frame(), rows_per_page=8)\n\n                with ui.row().classes("gap-2 items-end flex-wrap"):\n                    new_username = ui.input("Login").classes("w-32")\n                    new_name = ui.input("F.I.Sh.").classes("w-40")\n                    new_password = ui.input("Parol", password=True).classes("w-32")\n                    new_role = ui.select(["admin", "manager", "viewer"],\n                                         value="viewer", label="Rol").classes("w-28")\n\n                    def add_user() -> None:\n                        username = (new_username.value or "").strip().lower()\n                        if not username or not new_password.value:\n                            ui.notify("Login va parol majburiy.", type="warning")\n                            return\n                        with session_scope() as session:\n                            if session.query(User).filter_by(\n                                    username=username).first():\n                                ui.notify("Bunday login mavjud.", type="negative")\n                                return\n                            session.add(User(\n                                username=username,\n                                full_name=new_name.value or username,\n                                password_hash=hash_password(new_password.value),\n                                role=new_role.value))\n                        audit("user_created", user["username"], username)\n                        ui.notify("Foydalanuvchi qo\'shildi.", type="positive")\n                        render_users()\n\n                    ui.button("Qo\'shish", icon="person_add", on_click=add_user) \\\n                        .props("unelevated")\n\n                with ui.row().classes("gap-2 items-end flex-wrap"):\n                    toggle_login = ui.input("Login (faollik/parol)").classes("w-40")\n                    reset_password = ui.input("Yangi parol", password=True) \\\n                        .classes("w-32")\n\n                    def toggle_active() -> None:\n                        with session_scope() as session:\n                            target = session.query(User).filter_by(\n                                username=(toggle_login.value or "").strip().lower()\n                            ).first()\n                            if target is None:\n                                ui.notify("Topilmadi.", type="negative")\n                                return\n                            if target.username == user["username"]:\n                                ui.notify("O\'zingizni bloklay olmaysiz.",\n                                          type="warning")\n                                return\n                            target.active = not target.active\n                            state = "faollashtirildi" if target.active \\\n                                else "bloklandi"\n                        audit("user_toggled", user["username"],\n                              f"{toggle_login.value}: {state}")\n                        ui.notify(f"Foydalanuvchi {state}.", type="positive")\n                        render_users()\n\n                    def do_reset_password() -> None:\n                        if not reset_password.value:\n                            ui.notify("Yangi parolni kiriting.", type="warning")\n                            return\n                        with session_scope() as session:\n                            target = session.query(User).filter_by(\n                                username=(toggle_login.value or "").strip().lower()\n                            ).first()\n                            if target is None:\n                                ui.notify("Topilmadi.", type="negative")\n                                return\n                            target.password_hash = hash_password(\n                                reset_password.value)\n                        audit("password_reset", user["username"],\n                              toggle_login.value)\n                        ui.notify("Parol yangilandi.", type="positive")\n\n                    ui.button("Faollik", icon="toggle_on",\n                              on_click=toggle_active).props("outline")\n                    ui.button("Parolni tiklash", icon="lock_reset",\n                              on_click=do_reset_password).props("outline")\n                render_users()\n\n            # ---------------- Backups -------------------------------------\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Zaxira nusxalar (Backup / Restore)") \\\n                    .classes("section-title")\n                backups_box = ui.column().classes("w-full")\n\n                def render_backups() -> None:\n                    backups_box.clear()\n                    with backups_box:\n                        layout.df_table(pd.DataFrame(db_backup.list_backups()),\n                                        rows_per_page=6)\n\n                encrypt_switch = ui.switch(\n                    "Shifrlash (cryptography o\'rnatilgan bo\'lsa)")\n\n                def create() -> None:\n                    path = db_backup.create_backup(\n                        "manual", encrypt=bool(encrypt_switch.value))\n                    ui.notify(f"Zaxira yaratildi: {path.name}", type="positive")\n                    render_backups()\n\n                restore_name = ui.input("Tiklash uchun fayl nomi").classes("w-full")\n\n                def restore() -> None:\n                    if db_backup.restore_backup((restore_name.value or "").strip()):\n                        ui.notify("Baza tiklandi. Sahifani yangilang.",\n                                  type="positive")\n                    else:\n                        ui.notify("Tiklash muvaffaqiyatsiz — fayl nomini "\n                                  "tekshiring.", type="negative")\n\n                with ui.row().classes("gap-2"):\n                    ui.button("Zaxira yaratish", icon="backup", on_click=create) \\\n                        .props("unelevated")\n                    ui.button("Tiklash", icon="restore", on_click=restore) \\\n                        .props("outline color=negative")\n                render_backups()\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            with ui.card().classes("chart-card"):\n                audit_df = read_df(\n                    "SELECT timestamp, username, action, details FROM audit_log"\n                    " ORDER BY id DESC LIMIT 200")\n                layout.df_table(audit_df, title="Audit jurnali (so\'nggi 200)",\n                                rows_per_page=10)\n            with ui.column().classes("gap-4 w-full"):\n                with ui.card().classes("chart-card"):\n                    imports = read_df(\n                        "SELECT uploaded_at, filename, file_type, uploaded_by,"\n                        " summary FROM imported_files ORDER BY id DESC LIMIT 50")\n                    layout.df_table(imports, title="Import qilingan fayllar",\n                                    rows_per_page=5)\n                with ui.card().classes("chart-card"):\n                    stats = db_stats()\n                    layout.df_table(\n                        pd.DataFrame({"jadval": list(stats.keys()),\n                                      "yozuvlar": list(stats.values())}),\n                        title="Ma\'lumotlar bazasi holati", rows_per_page=13)\n',
    'dashboard.pages.ai_page': '"""AI assistant page: chat over the analytics database (fully offline)."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom ai.engine import assistant\nfrom app import layout\n\nSAMPLE_QUESTIONS = [\n    "Jizzaxda bug\'doy hosili nima uchun pasaydi?",\n    "Kelgusi yil paxta hosildorligi prognozi qanday?",\n    "Pomidor narxi qancha?",\n    "Samarqand uchun qaysi ekin tavsiya etiladi?",\n    "2024-yil Jizzax ob-havosi qanday bo\'lgan?",\n    "Viloyatlarni solishtirib bering",\n    "Daromad va foyda qanday?",\n]\n\n\n@ui.page("/ai")\ndef ai_page() -> None:\n    user = layout.require_login("use_ai")\n    if user is None:\n        return\n    with layout.shell(user, "AI Yordamchi"):\n        ui.label("Savolni oddiy tilda yozing — yordamchi bazadagi barcha "\n                 "ma\'lumotlarni tahlil qilib, dalillarga asoslangan javob beradi. "\n                 "Internet talab qilinmaydi.").classes("opacity-70")\n\n        messages = ui.column().classes(\n            "w-full gap-3 min-h-[300px] max-h-[520px] overflow-y-auto p-2")\n\n        def ask(question: str) -> None:\n            question = (question or "").strip()\n            if not question:\n                return\n            with messages:\n                with ui.row().classes("w-full justify-end"):\n                    with ui.card().classes("bg-primary text-white p-3 rounded-xl "\n                                           "max-w-[75%]"):\n                        ui.label(question)\n            result = assistant.ask(question)\n            with messages:\n                with ui.row().classes("w-full justify-start"):\n                    with ui.card().classes("p-3 rounded-xl max-w-[85%]"):\n                        with ui.row().classes("items-center gap-2"):\n                            ui.icon("smart_toy").classes("text-primary")\n                            ui.label("AgroAI").classes("font-medium text-primary")\n                        ui.markdown(result["answer"].replace("\\n", "\\n\\n"))\n                        table = result.get("table")\n                        if table is not None and not table.empty:\n                            layout.df_table(table.head(12), rows_per_page=6)\n            input_box.value = ""\n\n        with ui.row().classes("w-full flex-wrap gap-2"):\n            for sample in SAMPLE_QUESTIONS:\n                ui.chip(sample, icon="help_outline",\n                        on_click=lambda s=sample: ask(s)) \\\n                    .props("clickable outline color=primary")\n\n        with ui.row().classes("w-full items-center gap-2"):\n            input_box = ui.input(placeholder="Masalan: Jizzaxda bug\'doy hosili "\n                                             "nima uchun pasaydi?") \\\n                .props("outlined dense").classes("flex-grow")\n            input_box.on("keydown.enter", lambda: ask(input_box.value))\n            ui.button("So\'rash", icon="send",\n                      on_click=lambda: ask(input_box.value)).props("unelevated")\n',
    'dashboard.pages.analytics_page': '"""Deep analytics: trends, heatmap, correlation, seasonality, clustering."""\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\nfrom nicegui import ui\nfrom sklearn.cluster import KMeans\nfrom sklearn.preprocessing import StandardScaler\n\nfrom analytics import kpi as kpi_module\nfrom analytics.timeseries import linear_forecast\nfrom app import charts, layout\nfrom database.engine import read_df\n\n\ndef _cluster_regions(year: int) -> pd.DataFrame:\n    """K-Means segmentation of regions by yield, rainfall and water use."""\n    df = read_df(\n        "SELECT r.name AS region, AVG(y.yield_t_ha) AS avg_yield,"\n        " SUM(y.production_t) AS production"\n        " FROM yield_records y"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE y.year = :y GROUP BY r.name", {"y": year},\n    )\n    rain = read_df(\n        "SELECT r.name AS region, SUM(w.precipitation_mm)/COUNT(DISTINCT d.id) AS precip"\n        " FROM weather_records w"\n        " JOIN districts d ON d.id = w.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE CAST(strftime(\'%Y\', w.date) AS INTEGER) = :y"\n        " AND CAST(strftime(\'%m\', w.date) AS INTEGER) BETWEEN 4 AND 9"\n        " GROUP BY r.name", {"y": year},\n    )\n    df = df.merge(rain, on="region", how="left").fillna(0)\n    if len(df) < 3:\n        df["klaster"] = "A"\n        return df\n    features = StandardScaler().fit_transform(\n        df[["avg_yield", "production", "precip"]])\n    labels = KMeans(n_clusters=3, random_state=42, n_init=10).fit_predict(features)\n    names = {0: "A — yuqori salohiyat", 1: "B — o\'rtacha", 2: "C — e\'tibor talab"}\n    order = df.assign(_label=labels).groupby("_label")["avg_yield"].mean() \\\n        .sort_values(ascending=False).index.tolist()\n    remap = {cluster: names[rank] for rank, cluster in enumerate(order)}\n    df["klaster"] = [remap[label] for label in labels]\n    return df.round(2).sort_values("klaster")\n\n\n@ui.page("/analytics")\ndef analytics_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Analitika va prognozlash"):\n        state = {"year": kpi_module.latest_year()}\n        container = ui.column().classes("w-full gap-4")\n\n        def render() -> None:\n            year = state["year"]\n            container.clear()\n            with container:\n                # --- Trend + forecast -------------------------------------\n                trend = kpi_module.yield_trend()\n                values = trend["avg_yield"].tolist()\n                forecast, lower, upper = linear_forecast(values, 3)\n                x = [str(y) for y in trend["year"]] + \\\n                    [str(int(trend["year"].iloc[-1]) + i) for i in (1, 2, 3)]\n                pad = [None] * (len(values) - 1)\n                with ui.grid(columns=2).classes("w-full gap-4"):\n                    layout.chart(charts.line_chart(\n                        "Hosildorlik: trend, prognoz va ishonch oralig\'i (t/ga)", x,\n                        {\n                            "Haqiqiy": values + [None] * 3,\n                            "Prognoz": pad + [values[-1]] + forecast,\n                            "Quyi chegara": pad + [values[-1]] + lower,\n                            "Yuqori chegara": pad + [values[-1]] + upper,\n                        },\n                        dashed={"Prognoz", "Quyi chegara", "Yuqori chegara"}))\n\n                    regions = kpi_module.yield_by_region(year)\n                    layout.chart(charts.bar_chart(\n                        f"Viloyatlar — o\'rtacha hosildorlik, {year} (t/ga)",\n                        regions["region"].tolist(),\n                        {"t/ga": regions["avg_yield"].tolist()}, horizontal=True))\n\n                # --- Region x crop heatmap --------------------------------\n                matrix = kpi_module.region_crop_matrix(year)\n                if not matrix.empty:\n                    top_crops = matrix.count().sort_values(ascending=False) \\\n                        .head(10).index.tolist()\n                    matrix = matrix[top_crops]\n                    points = []\n                    for yi, region in enumerate(matrix.index):\n                        for xi, crop in enumerate(matrix.columns):\n                            value = matrix.loc[region, crop]\n                            if pd.notna(value):\n                                points.append([xi, yi, round(float(value), 1)])\n                    layout.chart(charts.heatmap_chart(\n                        f"Issiqlik xaritasi: viloyat × ekin hosildorligi, {year} (t/ga)",\n                        list(matrix.columns), list(matrix.index), points, "t/ga"),\n                        height="h-96")\n\n                # --- Correlation + seasonality ----------------------------\n                with ui.grid(columns=2).classes("w-full gap-4"):\n                    merged, correlation = kpi_module.rainfall_yield_correlation()\n                    layout.chart(charts.scatter_chart(\n                        f"Yog\'ingarchilik ↔ hosildorlik (r = {correlation})",\n                        [[round(float(r.precip), 0), round(float(r.avg_yield), 2)]\n                         for r in merged.itertuples()],\n                        "Mavsumiy yog\'in (mm)", "Hosildorlik (t/ga)"))\n\n                    monthly = read_df(\n                        "SELECT CAST(strftime(\'%m\', date) AS INTEGER) AS month,"\n                        " AVG(price_per_kg) AS price FROM market_prices"\n                        " GROUP BY month ORDER BY month")\n                    index = (monthly["price"] / monthly["price"].mean() * 100)\n                    layout.chart(charts.line_chart(\n                        "Narxlarning mavsumiyligi (indeks, o\'rtacha=100)",\n                        [f"{m:02d}" for m in monthly["month"]],\n                        {"Narx indeksi": index.round(1).tolist()}))\n\n                # --- Clustering -------------------------------------------\n                with ui.card().classes("chart-card"):\n                    layout.df_table(\n                        _cluster_regions(year),\n                        title=f"Viloyatlar segmentatsiyasi (K-Means), {year}")\n\n        ui.select(kpi_module.available_years(), value=state["year"], label="Yil",\n                  on_change=lambda e: (state.update(year=e.value), render())) \\\n            .classes("w-32")\n        render()\n',
    'dashboard.pages.finance_page': '"""Finance page: P&L, ROI, credits & subsidies."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom analytics.kpi import available_years, latest_year\nfrom app import charts, layout\nfrom finance.service import (\n    by_region, credits_and_subsidies, farm_profitability, yearly_summary,\n)\n\n\n@ui.page("/finance")\ndef finance_page() -> None:\n    user = layout.require_login("view_finance")\n    if user is None:\n        return\n    with layout.shell(user, "Moliya va iqtisod"):\n        state = {"year": latest_year()}\n        container = ui.column().classes("w-full gap-4")\n\n        def render() -> None:\n            year = state["year"]\n            container.clear()\n            with container:\n                summary = yearly_summary()\n                row = summary[summary.year == year]\n                if not row.empty:\n                    record = row.iloc[0]\n                    with ui.row().classes("w-full flex-wrap gap-3"):\n                        layout.kpi_card("trending_up",\n                                        f"{record.income / 1e9:,.1f} mlrd",\n                                        f"Daromad, {year} (so\'m)")\n                        layout.kpi_card("trending_down",\n                                        f"{record.expense / 1e9:,.1f} mlrd",\n                                        "Xarajat (so\'m)", "warning")\n                        layout.kpi_card("savings",\n                                        f"{record.profit / 1e9:,.1f} mlrd",\n                                        "Sof foyda (so\'m)",\n                                        "positive" if record.profit >= 0\n                                        else "negative")\n                        layout.kpi_card("percent", f"{record.roi}%", "ROI")\n                        layout.kpi_card("account_balance",\n                                        f"{record.credit / 1e9:,.1f} mlrd",\n                                        "Kreditlar (so\'m)", "info")\n                        layout.kpi_card("volunteer_activism",\n                                        f"{record.subsidy / 1e9:,.1f} mlrd",\n                                        "Subsidiyalar (so\'m)", "secondary")\n\n                years = [str(y) for y in summary["year"].tolist()]\n                with ui.grid(columns=2).classes("w-full gap-4"):\n                    layout.chart(charts.bar_chart(\n                        "Daromad va xarajat dinamikasi (mlrd so\'m)", years,\n                        {"Daromad": (summary["income"] / 1e9).round(1).tolist(),\n                         "Xarajat": (summary["expense"] / 1e9).round(1).tolist(),\n                         "Foyda": (summary["profit"] / 1e9).round(1).tolist()}))\n                    layout.chart(charts.line_chart(\n                        "ROI trendi (%)", years,\n                        {"ROI": summary["roi"].tolist()}))\n\n                regions = by_region(year)\n                if not regions.empty:\n                    layout.chart(charts.bar_chart(\n                        f"Viloyatlar bo\'yicha sof foyda, {year} (mlrd so\'m)",\n                        regions["region"].tolist(),\n                        {"Foyda": (regions["profit"] / 1e9).round(2).tolist()},\n                        horizontal=True), height="h-96")\n\n                with ui.grid(columns=2).classes("w-full gap-4"):\n                    with ui.card().classes("chart-card"):\n                        farms = farm_profitability(year)\n                        display = farms.assign(\n                            income=(farms["income"] / 1e6).round(0),\n                            expense=(farms["expense"] / 1e6).round(0),\n                            profit=(farms["profit"] / 1e6).round(0),\n                        ).rename(columns={"income": "daromad_mln",\n                                          "expense": "xarajat_mln",\n                                          "profit": "foyda_mln"})\n                        layout.df_table(display,\n                                        title=f"Xo\'jaliklar reytingi, {year} "\n                                              f"(mln so\'m)")\n                    with ui.card().classes("chart-card"):\n                        credits = credits_and_subsidies(year)\n                        if not credits.empty:\n                            credits = credits.assign(\n                                amount=(credits["amount"] / 1e6).round(1))\n                            credits = credits.rename(\n                                columns={"amount": "summa_mln"})\n                        layout.df_table(credits,\n                                        title=f"Kredit va subsidiyalar, {year} "\n                                              f"(mln so\'m)")\n\n        ui.select(available_years(), value=state["year"], label="Yil",\n                  on_change=lambda e: (state.update(year=e.value), render())) \\\n            .classes("w-32")\n        render()\n',
    'dashboard.pages.home': '"""Main dashboard: KPI cards, headline charts, alerts, top farms."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom analytics import kpi as kpi_module\nfrom analytics.insights import generate_alerts\nfrom analytics.timeseries import linear_forecast\nfrom app import charts, layout\n\n\n@ui.page("/")\ndef home_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Bosh sahifa"):\n        year = kpi_module.latest_year()\n        kpi = kpi_module.compute_kpi(year)\n\n        with ui.row().classes("w-full flex-wrap gap-3"):\n            layout.kpi_card("landscape", f"{kpi.total_area_ha:,.0f} ga",\n                            "Umumiy yer maydoni")\n            layout.kpi_card("groups", f"{kpi.farmers}", "Fermerlar")\n            layout.kpi_card("home_work", f"{kpi.farms}", "Fermer xo\'jaliklari")\n            layout.kpi_card("grid_on", f"{kpi.fields}", "Dalalar (konturlar)")\n            layout.kpi_card("agriculture", f"{kpi.avg_yield_t_ha} t/ga",\n                            f"O\'rtacha hosildorlik ({year})")\n            layout.kpi_card("inventory", f"{kpi.production_t:,.0f} t",\n                            "Ishlab chiqarish", "secondary")\n            layout.kpi_card("payments", f"{kpi.profit / 1e9:,.1f} mlrd",\n                            f"Sof foyda, so\'m (ROI {kpi.roi_percent}%)",\n                            "positive" if kpi.profit >= 0 else "negative")\n            layout.kpi_card("eco", f"{kpi.avg_ndvi}", "O\'rtacha NDVI (60 kun)",\n                            "secondary")\n            layout.kpi_card("water_drop", f"{kpi.water_million_m3} mln m³",\n                            "Sug\'orish suvi", "info")\n\n        trend = kpi_module.yield_trend()\n        forecast, lower, upper = linear_forecast(trend["avg_yield"].tolist(), 2)\n        x_labels = [str(y) for y in trend["year"].tolist()] + \\\n                   [str(int(trend["year"].iloc[-1]) + i) for i in (1, 2)]\n        history = trend["avg_yield"].tolist()\n        forecast_series = [None] * (len(history) - 1) + [history[-1]] + forecast\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            layout.chart(charts.line_chart(\n                "Hosildorlik trendi va prognoz (t/ga)", x_labels,\n                {"Haqiqiy": history + [None, None], "Prognoz": forecast_series},\n                dashed={"Prognoz"}))\n            layout.chart(charts.pie_chart(\n                "Ekin maydonlari taqsimoti",\n                [(row.crop, row.area) for row in\n                 kpi_module.crop_distribution(year).head(9).itertuples()]))\n\n        regions = kpi_module.yield_by_region(year)\n        layout.chart(charts.bar_chart(\n            f"Viloyatlar bo\'yicha ishlab chiqarish, {year} (t)",\n            regions["region"].tolist(),\n            {"Ishlab chiqarish": regions["production"].tolist()},\n            horizontal=True), height="h-96")\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            with ui.card().classes("chart-card"):\n                ui.label("Ogohlantirishlar va tahliliy xulosalar") \\\n                    .classes("section-title")\n                alerts = generate_alerts()\n                if not alerts:\n                    ui.label("Faol ogohlantirishlar yo\'q.").classes("opacity-70")\n                for alert in alerts[:6]:\n                    with ui.card().classes(\n                            f"w-full p-3 alert-{alert[\'level\']} shadow-1"):\n                        ui.label(alert["title"]).classes("font-medium")\n                        ui.label(alert["detail"]).classes("text-sm opacity-80")\n            with ui.card().classes("chart-card"):\n                layout.df_table(kpi_module.top_farms(year),\n                                title=f"Eng samarali xo\'jaliklar, {year}")\n',
    'dashboard.pages.irrigation_page': '"""Irrigation analytics page."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom analytics.kpi import available_years, latest_year\nfrom app import charts, layout\nfrom irrigation.service import (\n    efficiency_by_crop, monthly_usage, usage_by_method, usage_by_region,\n)\n\nMONTHS_UZ = {4: "Aprel", 5: "May", 6: "Iyun", 7: "Iyul", 8: "Avgust"}\n\n\n@ui.page("/irrigation")\ndef irrigation_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Sug\'orish tahlili"):\n        state = {"year": latest_year()}\n        container = ui.column().classes("w-full gap-4")\n\n        def render() -> None:\n            year = state["year"]\n            container.clear()\n            with container:\n                regions = usage_by_region(year)\n                methods = usage_by_method(year)\n                monthly = monthly_usage(year)\n\n                total = float(regions["water_mln_m3"].sum()) if not regions.empty else 0\n                with ui.row().classes("w-full flex-wrap gap-3"):\n                    layout.kpi_card("water_drop", f"{total:,.1f} mln m³",\n                                    f"Jami sug\'orish suvi, {year}")\n                    if not methods.empty:\n                        drip = methods[methods.method == "tomchilatib"]\n                        share = (float(drip["water_mln_m3"].iloc[0]) / total * 100\n                                 if not drip.empty and total else 0)\n                        layout.kpi_card("opacity", f"{share:.1f}%",\n                                        "Tomchilatib sug\'orish ulushi", "secondary")\n\n                with ui.grid(columns=2).classes("w-full gap-4"):\n                    layout.chart(charts.bar_chart(\n                        f"Viloyatlar bo\'yicha suv sarfi, {year} (mln m³)",\n                        regions["region"].tolist(),\n                        {"mln m³": regions["water_mln_m3"].tolist()},\n                        horizontal=True))\n                    layout.chart(charts.pie_chart(\n                        "Sug\'orish usullari bo\'yicha taqsimot",\n                        [(row.method, row.water_mln_m3)\n                         for row in methods.itertuples()]))\n\n                with ui.grid(columns=2).classes("w-full gap-4"):\n                    layout.chart(charts.bar_chart(\n                        f"Oylik suv sarfi, {year} (mln m³)",\n                        [MONTHS_UZ.get(int(m), str(m))\n                         for m in monthly["month"].tolist()],\n                        {"mln m³": monthly["water_mln_m3"].tolist()}))\n                    with ui.card().classes("chart-card"):\n                        layout.df_table(\n                            efficiency_by_crop(year)[\n                                ["crop", "production", "m3_per_tonne"]],\n                            title="Suv samaradorligi: 1 tonna mahsulotga m³")\n\n        ui.select(available_years(), value=state["year"], label="Yil",\n                  on_change=lambda e: (state.update(year=e.value), render())) \\\n            .classes("w-32")\n        render()\n',
    'dashboard.pages.login': '"""Login page with rate limiting and audit logging."""\nfrom __future__ import annotations\n\nfrom nicegui import app, ui\n\nfrom app import theme\nfrom config import settings\nfrom core.security import audit, login_limiter, verify_password\nfrom database.engine import session_scope\nfrom database.models import User\n\n\ndef _attempt_login(username: str, password: str) -> None:\n    username = (username or "").strip().lower()\n    if not username or not password:\n        ui.notify("Login va parolni kiriting.", type="warning")\n        return\n    if login_limiter.is_locked(username):\n        ui.notify("Juda ko\'p muvaffaqiyatsiz urinish. "\n                  f"{settings.LOGIN_LOCK_MINUTES} daqiqadan so\'ng qayta urining.",\n                  type="negative")\n        return\n    with session_scope() as session:\n        user = session.query(User).filter_by(username=username, active=True).first()\n    if user is None or not verify_password(password, user.password_hash):\n        login_limiter.register_failure(username)\n        audit("login_failed", username)\n        ui.notify("Login yoki parol noto\'g\'ri.", type="negative")\n        return\n    login_limiter.register_success(username)\n    app.storage.user["auth"] = {\n        "username": user.username, "name": user.full_name or user.username,\n        "role": user.role,\n    }\n    audit("login", user.username)\n    ui.navigate.to("/")\n\n\n@ui.page("/login")\ndef login_page() -> None:\n    theme.apply()\n    ui.query("body").classes("bg-green-1")\n    with ui.column().classes("absolute-center items-center gap-4"):\n        with ui.card().classes("p-8 items-center gap-3 rounded-2xl shadow-6 w-96"):\n            ui.icon("agriculture").classes("text-6xl text-primary")\n            ui.label(settings.APP_NAME).classes("text-2xl font-bold text-primary")\n            ui.label("Qishloq xo\'jaligi analitik platformasi") \\\n                .classes("text-sm opacity-70 text-center")\n            username = ui.input("Login").props("outlined dense") \\\n                .classes("w-full")\n            password = ui.input("Parol", password=True,\n                                password_toggle_button=True) \\\n                .props("outlined dense").classes("w-full")\n            password.on("keydown.enter",\n                        lambda: _attempt_login(username.value, password.value))\n            ui.button("Kirish",\n                      on_click=lambda: _attempt_login(username.value, password.value)) \\\n                .props("unelevated size=lg").classes("w-full")\n            with ui.expansion("Demo hisoblar").classes("w-full text-xs"):\n                ui.markdown(\n                    "| Login | Parol | Rol |\\n|---|---|---|\\n"\n                    "| `admin` | `admin123` | Administrator |\\n"\n                    "| `menejer` | `manager123` | Menejer |\\n"\n                    "| `kuzatuvchi` | `viewer123` | Kuzatuvchi |"\n                )\n',
    'dashboard.pages.map_page': '"""Interactive GIS map page with metric/region/year filters."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom analytics.kpi import available_years, latest_year\nfrom app import layout\nfrom gis.maps import build_map, region_options\nfrom weather.service import is_online\n\n\n@ui.page("/map")\ndef map_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Interaktiv xarita"):\n        if not is_online():\n            ui.chip("Offlayn rejim: xarita plitkalari internetsiz yuklanmaydi, "\n                    "poligon ma\'lumotlari esa to\'liq ishlaydi.",\n                    icon="wifi_off", color="orange-8") \\\n                .props("text-color=white").classes("w-full")\n\n        state = {"metric": "yield", "region": 0, "year": latest_year()}\n        container = ui.column().classes("w-full")\n\n        def render() -> None:\n            container.clear()\n            with container:\n                with ui.card().classes("w-full p-1 chart-card"):\n                    html = build_map(metric=state["metric"],\n                                     year=state["year"],\n                                     region_id=state["region"] or None)\n                    layout.raw_html(html).classes("w-full")\n\n        with ui.row().classes("w-full items-end gap-4"):\n            ui.select({"yield": "Hosildorlik (t/ga)", "ndvi": "NDVI indeksi"},\n                      value="yield", label="Ko\'rsatkich",\n                      on_change=lambda e: (state.update(metric=e.value), render())) \\\n                .classes("w-48")\n            ui.select(region_options(), value=0, label="Viloyat",\n                      on_change=lambda e: (state.update(region=e.value), render())) \\\n                .classes("w-56")\n            ui.select(available_years(), value=state["year"], label="Yil",\n                      on_change=lambda e: (state.update(year=e.value), render())) \\\n                .classes("w-32")\n            ui.label("Qatlamlar: ko\'cha / sun\'iy yo\'ldosh / relyef, poligonlar, "\n                     "klasterlar, issiqlik xaritasi — xaritaning o\'ng yuqori "\n                     "burchagida.").classes("text-xs opacity-60")\n\n        render()\n',
    'dashboard.pages.market_page': '"""Market page: latest prices, history, forecast, manual entry."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom app import charts, layout\nfrom core.security import has_permission\nfrom market.service import (\n    add_price, crop_options, latest_prices, price_forecast, price_history,\n)\n\n\n@ui.page("/market")\ndef market_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Bozor narxlari"):\n        crops = crop_options()\n        state = {"crop": next(iter(crops))}\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            with ui.card().classes("chart-card"):\n                layout.df_table(latest_prices(),\n                                title="So\'nggi narxlar (30 kunlik o\'zgarish bilan)",\n                                rows_per_page=12)\n\n            with ui.column().classes("gap-4 w-full"):\n                chart_box = ui.column().classes("w-full")\n\n                def render_chart() -> None:\n                    chart_box.clear()\n                    with chart_box:\n                        history = price_history(state["crop"], days=540)\n                        if history.empty:\n                            ui.label("Narx tarixi topilmadi.").classes("opacity-70")\n                            return\n                        forecast = price_forecast(state["crop"], periods=8)\n                        x = [str(d)[:10] for d in history["date"].tolist()[-26:]]\n                        x += [f"+{i + 1} hafta" for i in range(8)]\n                        pad = [None] * (len(forecast["history"]) - 1)\n                        layout.chart(charts.line_chart(\n                            f"{crops[state[\'crop\']]} — narx dinamikasi va prognoz "\n                            f"(so\'m/kg)", x,\n                            {\n                                "Narx": forecast["history"] + [None] * 8,\n                                "Prognoz": pad + [forecast["history"][-1]]\n                                + forecast["forecast"],\n                            },\n                            dashed={"Prognoz"}))\n\n                ui.select(crops, value=state["crop"], label="Ekin",\n                          on_change=lambda e: (state.update(crop=e.value),\n                                               render_chart())) \\\n                    .classes("w-64")\n                render_chart()\n\n                if has_permission(user["role"], "edit_data"):\n                    with ui.card().classes("chart-card p-4 gap-2"):\n                        ui.label("Narx kiritish (qo\'lda)").classes("section-title")\n                        entry_crop = ui.select(crops, value=next(iter(crops)),\n                                               label="Ekin").classes("w-full")\n                        entry_price = ui.number("Narx (so\'m/kg)", value=5000,\n                                                min=1).classes("w-full")\n                        entry_market = ui.input("Bozor nomi",\n                                                value="Chorsu bozori") \\\n                            .classes("w-full")\n\n                        def save_price() -> None:\n                            add_price(int(entry_crop.value),\n                                      float(entry_price.value or 0),\n                                      entry_market.value or "Qo\'lda kiritilgan")\n                            ui.notify("Narx saqlandi.", type="positive")\n                            ui.navigate.reload()\n\n                        ui.button("Saqlash", icon="save", on_click=save_price) \\\n                            .props("unelevated")\n                        ui.label("CSV/Excel orqali ommaviy import — "\n                                 "Hisobotlar sahifasida.").classes("text-xs opacity-60")\n',
    'dashboard.pages.ml_page': '"""Machine Learning workbench: metrics, predictions, recommendations."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom app import charts, layout\nfrom core import background\nfrom database.engine import read_df\nfrom ml import service as ml_service\n\n\ndef _crop_map() -> dict[int, str]:\n    df = read_df("SELECT id, name, water_need_mm FROM crops ORDER BY name")\n    return {int(row.id): row.name for row in df.itertuples()}\n\n\ndef _region_map() -> dict[int, str]:\n    df = read_df("SELECT id, name FROM regions ORDER BY name")\n    return {int(row.id): row.name for row in df.itertuples()}\n\n\n@ui.page("/ml")\ndef ml_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Machine Learning"):\n        metrics = ml_service.model_status()\n        with ui.row().classes("w-full flex-wrap gap-3"):\n            layout.kpi_card("agriculture",\n                            f"R² = {metrics.get(\'yield\', {}).get(\'r2\', \'-\')}",\n                            f"Hosil prognozi ({metrics.get(\'yield\', {}).get(\'algorithm\', \'-\')})")\n            layout.kpi_card("coronavirus",\n                            f"{metrics.get(\'disease\', {}).get(\'accuracy\', \'-\')}",\n                            "Kasallik xavfi (aniqlik)")\n            layout.kpi_card("water_drop",\n                            f"R² = {metrics.get(\'water\', {}).get(\'r2\', \'-\')}",\n                            "Suv ehtiyoji modeli")\n            layout.kpi_card("recommend",\n                            f"{metrics.get(\'crop\', {}).get(\'accuracy\', \'-\')}",\n                            "Ekin tavsiyasi (aniqlik)")\n            layout.kpi_card("schedule", metrics.get("trained_at", "-")[:16],\n                            "So\'nggi o\'qitish vaqti")\n        if user["role"] == "admin":\n            def retrain() -> None:\n                ui.notify("Modellar fonda qayta o\'qitilmoqda...", type="info")\n                background.submit(ml_service.train_all, True)\n            ui.button("Modellarni qayta o\'qitish", icon="model_training",\n                      on_click=retrain).props("outline")\n\n        crops = _crop_map()\n        regions = _region_map()\n        crop_needs = {int(r.id): float(r.water_need_mm) for r in read_df(\n            "SELECT id, water_need_mm FROM crops").itertuples()}\n        fertilities = {int(r.id): float(r.fertility) for r in read_df(\n            "SELECT id, fertility FROM regions").itertuples()}\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            # ---------------- Yield prediction ----------------------------\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Hosil prognozi (t/ga)").classes("section-title")\n                crop_select = ui.select(crops, value=next(iter(crops)),\n                                        label="Ekin").classes("w-full")\n                region_select = ui.select(regions, value=next(iter(regions)),\n                                          label="Viloyat").classes("w-full")\n                area = ui.number("Maydon (ga)", value=50, min=1, max=1000) \\\n                    .classes("w-full")\n                precip = ui.slider(min=30, max=500, value=150) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("Mavsumiy yog\'in (mm)").classes("text-xs opacity-60")\n                t_avg = ui.slider(min=15, max=35, value=24, step=0.5) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("O\'rtacha harorat (°C)").classes("text-xs opacity-60")\n                irrigation = ui.slider(min=0, max=900, value=350) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("Sug\'orish (mm)").classes("text-xs opacity-60")\n                yield_result = ui.label("").classes("text-xl font-bold text-primary")\n\n                def predict_yield() -> None:\n                    value = ml_service.predict_yield(\n                        crop_id=int(crop_select.value),\n                        region_id=int(region_select.value),\n                        area_ha=float(area.value or 50),\n                        precip=float(precip.value), t_avg=float(t_avg.value),\n                        irrigation_mm=float(irrigation.value),\n                        water_need_mm=crop_needs[int(crop_select.value)],\n                        fertility=fertilities[int(region_select.value)])\n                    yield_result.text = f"Prognoz: {value} t/ga"\n\n                ui.button("Bashorat qilish", icon="online_prediction",\n                          on_click=predict_yield).props("unelevated")\n\n            # ---------------- Disease risk --------------------------------\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Kasallik xavfi (zamburug\'li)").classes("section-title")\n                humidity = ui.slider(min=10, max=95, value=65) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("Namlik (%)").classes("text-xs opacity-60")\n                d_temp = ui.slider(min=5, max=40, value=23, step=0.5) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("Harorat (°C)").classes("text-xs opacity-60")\n                d_precip = ui.slider(min=0, max=200, value=60) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("Oylik yog\'in (mm)").classes("text-xs opacity-60")\n                d_ndvi = ui.slider(min=0.05, max=0.9, value=0.5, step=0.01) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("NDVI").classes("text-xs opacity-60")\n                gauge_box = ui.column().classes("w-full items-center")\n\n                def predict_disease() -> None:\n                    risk = ml_service.predict_disease_risk(\n                        float(humidity.value), float(d_temp.value),\n                        float(d_precip.value), float(d_ndvi.value)) * 100\n                    gauge_box.clear()\n                    with gauge_box:\n                        ui.echart(charts.gauge_chart("Xavf darajasi", risk)) \\\n                            .classes("w-64 h-52")\n                        advice = ("Profilaktik fungitsid ishlovi tavsiya etiladi."\n                                  if risk > 60 else\n                                  "Monitoringni davom ettiring." if risk > 30\n                                  else "Xavf past.")\n                        ui.label(advice).classes("text-sm opacity-80")\n\n                ui.button("Xavfni baholash", icon="health_and_safety",\n                          on_click=predict_disease).props("unelevated")\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            # ---------------- Water need ----------------------------------\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Suv ehtiyoji (mavsum, m³/ga)").classes("section-title")\n                w_crop = ui.select(crops, value=next(iter(crops)), label="Ekin") \\\n                    .classes("w-full")\n                w_precip = ui.slider(min=30, max=500, value=150) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("Kutilayotgan yog\'in (mm)").classes("text-xs opacity-60")\n                w_temp = ui.slider(min=15, max=35, value=25, step=0.5) \\\n                    .props("label-always").classes("w-full mt-6")\n                ui.label("O\'rtacha harorat (°C)").classes("text-xs opacity-60")\n                w_area = ui.number("Maydon (ga)", value=50, min=1).classes("w-full")\n                water_result = ui.label("").classes("text-xl font-bold text-primary")\n\n                def predict_water() -> None:\n                    per_ha = ml_service.predict_water_need(\n                        crop_needs[int(w_crop.value)], float(w_precip.value),\n                        float(w_temp.value), float(w_area.value or 50))\n                    total = per_ha * float(w_area.value or 50)\n                    water_result.text = (f"{per_ha:,.0f} m³/ga — jami "\n                                         f"{total / 1000:,.1f} ming m³")\n\n                ui.button("Hisoblash", icon="calculate",\n                          on_click=predict_water).props("unelevated")\n\n            # ---------------- Crop recommendation -------------------------\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Ekin tavsiyasi (foydalilik bo\'yicha)") \\\n                    .classes("section-title")\n                r_region = ui.select(regions, value=next(iter(regions)),\n                                     label="Viloyat").classes("w-full")\n                recommendation_box = ui.column().classes("w-full gap-1")\n\n                def recommend() -> None:\n                    from analytics.kpi import latest_year\n                    from weather.service import season_summary\n\n                    region_name = regions[int(r_region.value)]\n                    season = season_summary(region_name, latest_year()) \\\n                        or {"precip": 150, "t_avg": 24}\n                    results = ml_service.recommend_crops(\n                        int(r_region.value), season["precip"], season["t_avg"],\n                        fertilities[int(r_region.value)])\n                    recommendation_box.clear()\n                    with recommendation_box:\n                        for i, rec in enumerate(results):\n                            with ui.row().classes("items-center gap-2"):\n                                ui.badge(f"{i + 1}").props("color=primary")\n                                ui.label(rec["crop"]).classes("font-medium")\n                                ui.linear_progress(rec["confidence"] / 100,\n                                                   show_value=False) \\\n                                    .classes("w-40")\n                                ui.label(f"{rec[\'confidence\']}%") \\\n                                    .classes("text-sm opacity-70")\n\n                ui.button("Tavsiya olish", icon="recommend",\n                          on_click=recommend).props("unelevated")\n',
    'dashboard.pages.reports_page': '"""Reports page: dataset exports, KPI reports, universal import."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom analytics.kpi import available_years, latest_year\nfrom app import layout\nfrom core.security import has_permission\nfrom reports import exporter\n\n\n@ui.page("/reports")\ndef reports_page() -> None:\n    user = layout.require_login("export_reports")\n    if user is None:\n        return\n    with layout.shell(user, "Hisobotlar, import va eksport"):\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            # ---------------- KPI reports ---------------------------------\n            with ui.card().classes("chart-card p-4 gap-3"):\n                ui.label("Yakuniy KPI hisoboti").classes("section-title")\n                year_select = ui.select(available_years(), value=latest_year(),\n                                        label="Hisobot yili").classes("w-48")\n\n                def make(report_fn, label: str) -> None:\n                    path = report_fn(int(year_select.value), user["username"])\n                    if path is None:\n                        ui.notify(f"{label} uchun qo\'shimcha paket kerak "\n                                  "(README ga qarang).", type="warning")\n                        return\n                    layout.download_file(path)\n                    ui.notify(f"{label} tayyor: {path.name}", type="positive")\n\n                with ui.row().classes("flex-wrap gap-2"):\n                    ui.button("PDF", icon="picture_as_pdf",\n                              on_click=lambda: make(exporter.kpi_report_pdf, "PDF")) \\\n                        .props("unelevated")\n                    ui.button("HTML", icon="language",\n                              on_click=lambda: make(exporter.kpi_report_html, "HTML")) \\\n                        .props("unelevated")\n                    ui.button("Word", icon="article",\n                              on_click=lambda: make(exporter.kpi_report_word, "Word")) \\\n                        .props("unelevated")\n                    ui.button("PNG (dashboard)", icon="image",\n                              on_click=lambda: make(exporter.dashboard_png, "PNG")) \\\n                        .props("unelevated")\n\n            # ---------------- Dataset export -------------------------------\n            with ui.card().classes("chart-card p-4 gap-3"):\n                ui.label("Ma\'lumotlar eksporti").classes("section-title")\n                dataset = ui.select(list(exporter.DATASETS.keys()),\n                                    value=next(iter(exporter.DATASETS)),\n                                    label="Ma\'lumotlar to\'plami").classes("w-full")\n                format_select = ui.select(["csv", "xlsx", "json"], value="xlsx",\n                                          label="Format").classes("w-40")\n\n                def export_dataset() -> None:\n                    frame = exporter.dataset_frame(dataset.value)\n                    path = exporter.export_dataframe(\n                        frame, dataset.value.replace(" ", "_").lower(),\n                        format_select.value, user["username"])\n                    layout.download_file(path)\n                    ui.notify(f"Eksport tayyor: {path.name} "\n                              f"({len(frame)} qator)", type="positive")\n\n                with ui.row().classes("gap-2"):\n                    ui.button("Eksport", icon="download",\n                              on_click=export_dataset).props("unelevated")\n                    ui.button("GeoJSON (dalalar)", icon="public",\n                              on_click=lambda: (\n                                  layout.download_file(\n                                      exporter.export_fields_geojson(\n                                          user["username"])),\n                                  ui.notify("GeoJSON tayyor.", type="positive"),\n                              )).props("outline")\n\n        # ---------------- Import --------------------------------------------\n        if has_permission(user["role"], "import_data"):\n            with ui.card().classes("chart-card p-4 gap-2 w-full"):\n                ui.label("Universal import").classes("section-title")\n                ui.label("Qo\'llab-quvvatlanadi: CSV, Excel, JSON, GeoJSON, "\n                         "Shapefile, KML, TIFF/GeoTIFF, ZIP, SQLite. Narxlar "\n                         "uchun ustunlar: [ekin, narx, sana]; hosildorlik uchun: "\n                         "[ekin, yil, hosildorlik, dala].") \\\n                    .classes("text-sm opacity-70")\n                result_label = ui.label("").classes("text-sm text-primary")\n\n                def on_upload(event) -> None:\n                    from utils.importer import handle_upload\n\n                    summary = handle_upload(event.name, event.content.read(),\n                                            user["username"])\n                    result_label.text = summary\n                    ui.notify(summary[:120], type="info", timeout=8000)\n\n                ui.upload(on_upload=on_upload, auto_upload=True,\n                          max_file_size=200_000_000, multiple=True) \\\n                    .props("label=\'Fayllarni tanlang yoki tashlang\'") \\\n                    .classes("w-full")\n',
    'dashboard.pages.satellite_page': '"""Satellite & drone page: NDVI/EVI series, field health, imagery upload."""\nfrom __future__ import annotations\n\nfrom nicegui import ui\n\nfrom app import charts, layout\nfrom core.security import has_permission\nfrom satellite.service import field_health, field_options, get_provider, ndvi_series\n\n\n@ui.page("/satellite")\ndef satellite_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Sun\'iy yo\'ldosh va dron monitoringi"):\n        provider = get_provider()\n        ui.chip(f"Faol provayder: {provider.name}", icon="satellite_alt",\n                color="green-6").props("dense text-color=white")\n\n        fields = field_options()\n        state = {"field": next(iter(fields))}\n        chart_box = ui.column().classes("w-full")\n\n        def render_chart() -> None:\n            chart_box.clear()\n            with chart_box:\n                series = ndvi_series(state["field"])\n                if series.empty:\n                    ui.label("Bu dala uchun indeks ma\'lumotlari yo\'q.") \\\n                        .classes("opacity-70")\n                    return\n                layout.chart(charts.line_chart(\n                    f"{fields[state[\'field\']]} — NDVI/EVI dinamikasi",\n                    [str(d)[:10] for d in series["date"].tolist()],\n                    {"NDVI": series["ndvi"].tolist(),\n                     "EVI": series["evi"].tolist()}))\n\n        with ui.row().classes("w-full items-end gap-4"):\n            ui.select(fields, value=state["field"], label="Dala (kontur)",\n                      on_change=lambda e: (state.update(field=e.value),\n                                           render_chart())) \\\n                .classes("w-96")\n        render_chart()\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            with ui.card().classes("chart-card"):\n                health = field_health()\n                if not health.empty:\n                    health = health[["field", "farm", "region", "ndvi", "evi",\n                                     "holat"]]\n                layout.df_table(health, title="Dalalar salomatligi (so\'nggi NDVI)",\n                                rows_per_page=12)\n\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Dron / sun\'iy yo\'ldosh tasvirini yuklash") \\\n                    .classes("section-title")\n                ui.label("Qo\'llab-quvvatlanadi: GeoTIFF, TIFF, JPG, PNG "\n                         "(ortomozaika, NDVI raster). 4 kanalli GeoTIFF dan "\n                         "NDVI avtomatik hisoblanadi.") \\\n                    .classes("text-sm opacity-70")\n                target_field = ui.select(fields, value=next(iter(fields)),\n                                         label="Qaysi dalaga biriktirish") \\\n                    .classes("w-full")\n\n                if has_permission(user["role"], "import_data"):\n                    def on_upload(event) -> None:\n                        from pathlib import Path\n\n                        from config import settings\n                        from satellite.service import process_drone_image\n\n                        settings.ensure_directories()\n                        target = settings.UPLOAD_DIR / event.name\n                        target.write_bytes(event.content.read())\n                        summary = process_drone_image(\n                            Path(target), field_id=int(target_field.value),\n                            username=user["username"])\n                        ui.notify(summary, type="positive", timeout=8000)\n\n                    ui.upload(on_upload=on_upload, auto_upload=True,\n                              max_file_size=200_000_000) \\\n                        .props("accept=.tif,.tiff,.jpg,.jpeg,.png "\n                               "label=\'Faylni tanlang yoki tashlang\'") \\\n                        .classes("w-full")\n                else:\n                    ui.label("Yuklash uchun menejer yoki admin huquqi kerak.") \\\n                        .classes("text-sm text-orange-8")\n',
    'dashboard.pages.settings_page': '"""Settings page: theme, language, providers, API keys, ML, optional packages."""\nfrom __future__ import annotations\n\nimport pandas as pd\nfrom nicegui import app, ui\n\nfrom app import layout\nfrom core import background\nfrom core.i18n import LANGUAGES\nfrom core.optional import optional_status\nfrom core.security import audit\nfrom database.engine import get_setting, set_setting\n\n\n@ui.page("/settings")\ndef settings_page() -> None:\n    user = layout.require_login("manage_settings")\n    if user is None:\n        return\n    with layout.shell(user, "Sozlamalar"):\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            # ---------------- Appearance & language -----------------------\n            with ui.card().classes("chart-card p-4 gap-3"):\n                ui.label("Ko\'rinish va til").classes("section-title")\n                theme_select = ui.select(\n                    {"light": "Kunduzgi (light)", "dark": "Tungi (dark)"},\n                    value=get_setting("theme", "light"),\n                    label="Standart mavzu").classes("w-full")\n                language_select = ui.select(\n                    LANGUAGES, value=get_setting("language", "uz"),\n                    label="Interfeys tili").classes("w-full")\n                offline_select = ui.select(\n                    {"auto": "Avto (internetni tekshirish)",\n                     "on": "Majburiy offlayn", "off": "Majburiy onlayn"},\n                    value=get_setting("offline_mode", "auto"),\n                    label="Offlayn rejim").classes("w-full")\n\n            # ---------------- Integrations --------------------------------\n            with ui.card().classes("chart-card p-4 gap-3"):\n                ui.label("Integratsiyalar (API)").classes("section-title")\n                weather_select = ui.select(\n                    {"open-meteo": "Open-Meteo (kalitsiz)",\n                     "nasa-power": "NASA POWER"},\n                    value=get_setting("weather_provider", "open-meteo"),\n                    label="Ob-havo provayderi").classes("w-full")\n                gee_account = ui.input(\n                    "Google Earth Engine service account",\n                    value=get_setting("gee_service_account")).classes("w-full")\n                gee_key = ui.input(\n                    "GEE kalit fayli yo\'li (.json)",\n                    value=get_setting("gee_key_file")).classes("w-full")\n                planet_key = ui.input(\n                    "Planet API kaliti (plagin)",\n                    value=get_setting("planet_api_key")).classes("w-full")\n                ui.label("Kalitlar bo\'sh qolsa, platforma lokal demo "\n                         "provayderlarda to\'liq ishlaydi.") \\\n                    .classes("text-xs opacity-60")\n\n        with ui.grid(columns=2).classes("w-full gap-4"):\n            # ---------------- ML & backup ----------------------------------\n            with ui.card().classes("chart-card p-4 gap-3"):\n                ui.label("ML va zaxira").classes("section-title")\n                retrain_days = ui.number(\n                    "ML avtomatik qayta o\'qitish (kun)",\n                    value=int(get_setting("ml_auto_retrain_days", "30")),\n                    min=1, max=365).classes("w-full")\n                backup_keep = ui.number(\n                    "Saqlanadigan zaxiralar soni",\n                    value=int(get_setting("backup_keep", "20")),\n                    min=3, max=100).classes("w-full")\n                backup_hours = ui.number(\n                    "Avtomatik zaxira oralig\'i (soat)",\n                    value=float(get_setting("auto_backup_hours", "24")),\n                    min=1, max=168).classes("w-full")\n\n                def retrain_now() -> None:\n                    from ml.service import train_all\n\n                    ui.notify("Modellar fonda qayta o\'qitilmoqda...", type="info")\n                    background.submit(train_all, True)\n\n                ui.button("ML modellarini hozir qayta o\'qitish",\n                          icon="model_training", on_click=retrain_now) \\\n                    .props("outline")\n\n            # ---------------- Optional packages ----------------------------\n            with ui.card().classes("chart-card p-4 gap-2"):\n                ui.label("Ixtiyoriy paketlar holati").classes("section-title")\n                status = optional_status()\n                frame = pd.DataFrame({\n                    "paket": list(status.keys()),\n                    "holat": ["✅ o\'rnatilgan" if ok else "— yo\'q"\n                              for ok in status.values()],\n                })\n                layout.df_table(frame, rows_per_page=8)\n                ui.label("Yetishmayotgan paketni o\'rnatish: "\n                         "pip install <paket nomi>").classes("text-xs opacity-60")\n\n        def save() -> None:\n            set_setting("theme", theme_select.value)\n            set_setting("language", language_select.value)\n            set_setting("offline_mode", offline_select.value)\n            set_setting("weather_provider", weather_select.value)\n            set_setting("gee_service_account", gee_account.value or "")\n            set_setting("gee_key_file", gee_key.value or "")\n            set_setting("planet_api_key", planet_key.value or "")\n            set_setting("ml_auto_retrain_days", str(int(retrain_days.value or 30)))\n            set_setting("backup_keep", str(int(backup_keep.value or 20)))\n            set_setting("auto_backup_hours", str(float(backup_hours.value or 24)))\n            app.storage.user["language"] = language_select.value\n            audit("settings_saved", user["username"])\n            ui.notify("Sozlamalar saqlandi.", type="positive")\n\n        ui.button("Barchasini saqlash", icon="save", on_click=save) \\\n            .props("unelevated size=lg")\n',
    'dashboard.pages.weather_page': '"""Weather page: live forecast, history charts, climate profile."""\nfrom __future__ import annotations\n\nimport pandas as pd\nfrom nicegui import ui\n\nfrom app import charts, layout\nfrom database.engine import read_df\nfrom weather.service import fetch_forecast, history_frame, is_online, monthly_climate\n\nMONTHS_UZ = ["Yan", "Fev", "Mar", "Apr", "May", "Iyn",\n             "Iyl", "Avg", "Sen", "Okt", "Noy", "Dek"]\n\n\ndef _district_map() -> dict[int, str]:\n    df = read_df(\n        "SELECT d.id, d.name || \' (\' || r.name || \')\' AS label"\n        " FROM districts d JOIN regions r ON r.id = d.region_id ORDER BY r.name")\n    return {int(row.id): row.label for row in df.itertuples()}\n\n\n@ui.page("/weather")\ndef weather_page() -> None:\n    user = layout.require_login()\n    if user is None:\n        return\n    with layout.shell(user, "Ob-havo monitoringi"):\n        districts = _district_map()\n        state = {"district": next(iter(districts))}\n        container = ui.column().classes("w-full gap-4")\n\n        def render() -> None:\n            district_id = state["district"]\n            container.clear()\n            with container:\n                coords = read_df(\n                    "SELECT lat, lon FROM districts WHERE id = :d",\n                    {"d": district_id}).iloc[0]\n\n                # ---------------- 7-day forecast --------------------------\n                forecast = fetch_forecast(float(coords.lat), float(coords.lon))\n                with ui.card().classes("chart-card p-4"):\n                    with ui.row().classes("items-center gap-3"):\n                        ui.label("7 kunlik prognoz").classes("section-title")\n                        source = forecast.get("_source", "-") if forecast else \\\n                            "ma\'lumot yo\'q (offlayn, kesh bo\'sh)"\n                        ui.chip(source, icon="cloud_sync",\n                                color="green-6" if is_online() else "orange-8") \\\n                            .props("dense text-color=white")\n                    if forecast and "daily" in forecast:\n                        daily = forecast["daily"]\n                        with ui.row().classes("w-full flex-wrap gap-2"):\n                            for i, day in enumerate(daily["time"]):\n                                with ui.card().classes("p-3 items-center w-28"):\n                                    ui.label(day[5:]).classes("text-xs opacity-60")\n                                    ui.label(\n                                        f"{daily[\'temperature_2m_max\'][i]:.0f}°"\n                                        f"/{daily[\'temperature_2m_min\'][i]:.0f}°") \\\n                                        .classes("font-bold")\n                                    rain = daily["precipitation_sum"][i] or 0\n                                    ui.label(f"{rain:.1f} mm") \\\n                                        .classes("text-xs text-blue-6")\n                    else:\n                        ui.label("Prognoz mavjud emas — internet ulanishi va "\n                                 "keshni tekshiring.").classes("opacity-70")\n\n                # ---------------- History ---------------------------------\n                history = history_frame(district_id, days=365)\n                if not history.empty:\n                    history["date"] = history["date"].astype(str)\n                    monthly = history.assign(month=history["date"].str[:7]) \\\n                        .groupby("month") \\\n                        .agg(t_max=("t_max", "mean"), t_min=("t_min", "mean"),\n                             precip=("precipitation_mm", "sum"),\n                             humidity=("humidity", "mean")).reset_index()\n                    with ui.grid(columns=2).classes("w-full gap-4"):\n                        layout.chart(charts.line_chart(\n                            "Harorat, so\'nggi 12 oy (°C)",\n                            monthly["month"].tolist(),\n                            {"Maks": monthly["t_max"].round(1).tolist(),\n                             "Min": monthly["t_min"].round(1).tolist()}))\n                        layout.chart(charts.bar_chart(\n                            "Oylik yog\'ingarchilik (mm)",\n                            monthly["month"].tolist(),\n                            {"Yog\'in": monthly["precip"].round(1).tolist()}))\n\n                # ---------------- Climate profile -------------------------\n                climate = monthly_climate(district_id)\n                if not climate.empty:\n                    labels = [MONTHS_UZ[m - 1] for m in climate["month"]]\n                    with ui.grid(columns=2).classes("w-full gap-4"):\n                        layout.chart(charts.line_chart(\n                            "Ko\'p yillik iqlim profili — harorat (°C)", labels,\n                            {"Maks": climate["t_max"].tolist(),\n                             "Min": climate["t_min"].tolist()}))\n                        layout.chart(charts.bar_chart(\n                            "Ko\'p yillik o\'rtacha oylik yog\'in (mm)", labels,\n                            {"Yog\'in": climate["precip"].tolist()}))\n\n        ui.select(districts, value=state["district"], label="Tuman",\n                  on_change=lambda e: (state.update(district=e.value), render())) \\\n            .classes("w-80")\n        render()\n',
    'database': '"""Database layer: SQLAlchemy models, engine, seeding and backups."""\n',
    'database.backup': '"""Backup / restore of the SQLite database with optional encryption."""\nfrom __future__ import annotations\n\nimport logging\nimport shutil\nfrom datetime import datetime\nfrom pathlib import Path\n\nfrom config import settings\nfrom core.optional import try_import\nfrom core.security import audit\n\nlog = logging.getLogger(__name__)\n\n\ndef _encryption_key() -> bytes | None:\n    """Derive a Fernet key from the app secret when cryptography is available."""\n    crypto = try_import("cryptography")\n    if crypto is None:\n        return None\n    import base64\n    import hashlib\n\n    digest = hashlib.sha256(settings.get_storage_secret().encode()).digest()\n    return base64.urlsafe_b64encode(digest)\n\n\ndef create_backup(reason: str = "manual", encrypt: bool = False) -> Path | None:\n    """Copy the live database into ``backups/`` (optionally Fernet-encrypted)."""\n    if not settings.DB_PATH.exists():\n        return None\n    settings.ensure_directories()\n    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n    target = settings.BACKUP_DIR / f"agriculture_{stamp}_{reason}.db"\n    shutil.copy2(settings.DB_PATH, target)\n\n    if encrypt:\n        key = _encryption_key()\n        if key is not None:\n            from cryptography.fernet import Fernet\n\n            encrypted = settings.BACKUP_DIR / (target.name + ".enc")\n            encrypted.write_bytes(Fernet(key).encrypt(target.read_bytes()))\n            target.unlink()\n            target = encrypted\n\n    _rotate_backups()\n    audit("backup_created", details=target.name)\n    log.info("Zaxira nusxa yaratildi: %s", target.name)\n    return target\n\n\ndef list_backups() -> list[dict[str, str]]:\n    """Available backups, newest first."""\n    if not settings.BACKUP_DIR.exists():\n        return []\n    items = []\n    for path in sorted(settings.BACKUP_DIR.glob("agriculture_*.db*"), reverse=True):\n        items.append({\n            "name": path.name,\n            "size_mb": f"{path.stat().st_size / 1_048_576:.2f}",\n            "created": datetime.fromtimestamp(path.stat().st_mtime).strftime("%Y-%m-%d %H:%M"),\n        })\n    return items\n\n\ndef restore_backup(name: str) -> bool:\n    """Replace the live database with a backup (decrypting when needed)."""\n    source = settings.BACKUP_DIR / name\n    if not source.exists() or ".." in name:\n        return False\n\n    from core.cache import clear_all_caches\n    from database.engine import dispose_engine\n\n    dispose_engine()\n    if name.endswith(".enc"):\n        key = _encryption_key()\n        if key is None:\n            log.error("Shifrlangan zaxirani tiklash uchun \'cryptography\' kerak.")\n            return False\n        from cryptography.fernet import Fernet\n\n        settings.DB_PATH.write_bytes(Fernet(key).decrypt(source.read_bytes()))\n    else:\n        shutil.copy2(source, settings.DB_PATH)\n    clear_all_caches()\n    audit("backup_restored", details=name)\n    log.info("Ma\'lumotlar bazasi tiklandi: %s", name)\n    return True\n\n\ndef _rotate_backups() -> None:\n    """Keep only the newest N backups (configured in settings)."""\n    from database.engine import get_setting\n\n    keep = int(get_setting("backup_keep", "20") or 20)\n    backups = sorted(settings.BACKUP_DIR.glob("agriculture_*.db*"), reverse=True)\n    for stale in backups[keep:]:\n        try:\n            stale.unlink()\n        except OSError:\n            pass\n',
    'database.engine': '"""Database engine management for SQLite (+ optional SpatiaLite extension)."""\nfrom __future__ import annotations\n\nimport logging\nfrom contextlib import contextmanager\nfrom typing import Any, Iterator\n\nimport pandas as pd\nfrom sqlalchemy import create_engine, event, text\nfrom sqlalchemy.engine import Engine\nfrom sqlalchemy.orm import Session, sessionmaker\nfrom sqlalchemy.pool import StaticPool\n\nfrom config import settings\nfrom database.models import Base, Setting\n\nlog = logging.getLogger(__name__)\n\n_engine: Engine | None = None\n_session_factory: sessionmaker | None = None\nspatialite_enabled = False\n\n\ndef _try_load_spatialite(dbapi_connection: Any) -> bool:\n    """Attempt to load the SpatiaLite extension; plain SQLite is the fallback."""\n    try:\n        dbapi_connection.enable_load_extension(True)\n        for candidate in ("mod_spatialite", "mod_spatialite.dll"):\n            try:\n                dbapi_connection.load_extension(candidate)\n                return True\n            except Exception:  # noqa: BLE001\n                continue\n    except Exception:  # noqa: BLE001\n        pass\n    finally:\n        try:\n            dbapi_connection.enable_load_extension(False)\n        except Exception:  # noqa: BLE001\n            pass\n    return False\n\n\ndef get_engine() -> Engine:\n    """Create (once) and return the shared SQLite engine."""\n    global _engine, _session_factory, spatialite_enabled\n    if _engine is not None:\n        return _engine\n\n    settings.ensure_directories()\n    _engine = create_engine(\n        f"sqlite:///{settings.DB_PATH}",\n        connect_args={"check_same_thread": False, "timeout": 30},\n        poolclass=StaticPool,\n        future=True,\n    )\n\n    @event.listens_for(_engine, "connect")\n    def _on_connect(dbapi_connection: Any, _record: Any) -> None:\n        global spatialite_enabled\n        cursor = dbapi_connection.cursor()\n        cursor.execute("PRAGMA journal_mode=WAL")\n        cursor.execute("PRAGMA foreign_keys=ON")\n        cursor.execute("PRAGMA synchronous=NORMAL")\n        cursor.close()\n        if not spatialite_enabled and _try_load_spatialite(dbapi_connection):\n            spatialite_enabled = True\n            log.info("SpatiaLite kengaytmasi yuklandi (geo-SQL yoqilgan).")\n\n    _session_factory = sessionmaker(bind=_engine, expire_on_commit=False, future=True)\n    return _engine\n\n\ndef dispose_engine() -> None:\n    """Close all pooled connections (needed before restore/replace of the DB)."""\n    global _engine, _session_factory\n    if _engine is not None:\n        _engine.dispose()\n    _engine = None\n    _session_factory = None\n\n\ndef init_db() -> None:\n    """Create all tables and ensure default settings exist."""\n    engine = get_engine()\n    Base.metadata.create_all(engine)\n    with session_scope() as session:\n        existing = {row.key for row in session.query(Setting).all()}\n        for key, value in settings.DEFAULT_SETTINGS.items():\n            if key not in existing:\n                session.add(Setting(key=key, value=value))\n\n\n@contextmanager\ndef session_scope() -> Iterator[Session]:\n    """Transactional session context manager."""\n    get_engine()\n    assert _session_factory is not None\n    session = _session_factory()\n    try:\n        yield session\n        session.commit()\n    except Exception:\n        session.rollback()\n        raise\n    finally:\n        session.close()\n\n\ndef read_df(sql: str, params: dict[str, Any] | None = None) -> pd.DataFrame:\n    """Run a parametrised SQL query and return a pandas DataFrame."""\n    with get_engine().connect() as connection:\n        return pd.read_sql(text(sql), connection, params=params or {})\n\n\ndef get_setting(key: str, default: str = "") -> str:\n    """Read a configuration value from the settings table."""\n    try:\n        with session_scope() as session:\n            row = session.get(Setting, key)\n            return row.value if row is not None else default\n    except Exception:  # noqa: BLE001 - settings must never crash callers\n        return default\n\n\ndef set_setting(key: str, value: str) -> None:\n    """Upsert a configuration value in the settings table."""\n    with session_scope() as session:\n        row = session.get(Setting, key)\n        if row is None:\n            session.add(Setting(key=key, value=value))\n        else:\n            row.value = value\n\n\ndef db_stats() -> dict[str, int]:\n    """Row counts per core table (used by health checks and the admin page)."""\n    tables = [\n        "users", "regions", "districts", "farmers", "farms", "fields", "crops",\n        "yield_records", "weather_records", "market_prices",\n        "irrigation_records", "finance_records", "satellite_indices",\n    ]\n    stats: dict[str, int] = {}\n    with get_engine().connect() as connection:\n        for table in tables:\n            stats[table] = connection.execute(\n                text(f"SELECT COUNT(*) FROM {table}")  # noqa: S608 - fixed names\n            ).scalar_one()\n    return stats\n',
    'database.models': '"""SQLAlchemy ORM models for the AgroVision platform (SQLite backend).\n\nGeometries are stored as GeoJSON text so the schema works on plain SQLite;\nwhen SpatiaLite is available the same column feeds spatial tooling.\n"""\nfrom __future__ import annotations\n\nfrom datetime import date, datetime\n\nfrom sqlalchemy import (\n    Boolean, Column, Date, DateTime, Float, ForeignKey, Integer, String, Text,\n)\nfrom sqlalchemy.orm import declarative_base, relationship\n\nBase = declarative_base()\n\n\nclass User(Base):\n    __tablename__ = "users"\n\n    id = Column(Integer, primary_key=True)\n    username = Column(String(64), unique=True, nullable=False, index=True)\n    full_name = Column(String(128), nullable=False, default="")\n    password_hash = Column(String(256), nullable=False)\n    role = Column(String(32), nullable=False, default="viewer")\n    active = Column(Boolean, nullable=False, default=True)\n    created_at = Column(DateTime, default=datetime.utcnow, nullable=False)\n\n\nclass AuditLog(Base):\n    __tablename__ = "audit_log"\n\n    id = Column(Integer, primary_key=True)\n    timestamp = Column(DateTime, default=datetime.utcnow, nullable=False, index=True)\n    username = Column(String(64), nullable=False, default="system")\n    action = Column(String(64), nullable=False)\n    details = Column(Text, nullable=False, default="")\n\n\nclass Setting(Base):\n    __tablename__ = "settings"\n\n    key = Column(String(64), primary_key=True)\n    value = Column(Text, nullable=False, default="")\n\n\nclass Region(Base):\n    __tablename__ = "regions"\n\n    id = Column(Integer, primary_key=True)\n    name = Column(String(64), unique=True, nullable=False)\n    lat = Column(Float, nullable=False)\n    lon = Column(Float, nullable=False)\n    fertility = Column(Float, nullable=False, default=1.0)  # relative soil factor\n\n    districts = relationship("District", back_populates="region")\n\n\nclass District(Base):\n    __tablename__ = "districts"\n\n    id = Column(Integer, primary_key=True)\n    region_id = Column(Integer, ForeignKey("regions.id"), nullable=False, index=True)\n    name = Column(String(64), nullable=False)\n    lat = Column(Float, nullable=False)\n    lon = Column(Float, nullable=False)\n\n    region = relationship("Region", back_populates="districts")\n    farms = relationship("Farm", back_populates="district")\n\n\nclass Farmer(Base):\n    __tablename__ = "farmers"\n\n    id = Column(Integer, primary_key=True)\n    name = Column(String(128), nullable=False, index=True)\n    phone = Column(String(32), nullable=False, default="")\n    district_id = Column(Integer, ForeignKey("districts.id"), nullable=False)\n\n    district = relationship("District")\n    farms = relationship("Farm", back_populates="farmer")\n\n\nclass Farm(Base):\n    __tablename__ = "farms"\n\n    id = Column(Integer, primary_key=True)\n    name = Column(String(128), nullable=False, index=True)\n    farmer_id = Column(Integer, ForeignKey("farmers.id"), nullable=False)\n    district_id = Column(Integer, ForeignKey("districts.id"), nullable=False, index=True)\n    area_ha = Column(Float, nullable=False, default=0.0)\n\n    farmer = relationship("Farmer", back_populates="farms")\n    district = relationship("District", back_populates="farms")\n    fields = relationship("Field", back_populates="farm")\n\n\nclass Field(Base):\n    __tablename__ = "fields"\n\n    id = Column(Integer, primary_key=True)\n    farm_id = Column(Integer, ForeignKey("farms.id"), nullable=False, index=True)\n    name = Column(String(128), nullable=False)\n    area_ha = Column(Float, nullable=False)\n    soil_type = Column(String(32), nullable=False, default="bo\'z tuproq")\n    lat = Column(Float, nullable=False)\n    lon = Column(Float, nullable=False)\n    geometry_geojson = Column(Text, nullable=False, default="")  # GeoJSON Polygon\n\n    farm = relationship("Farm", back_populates="fields")\n    yields = relationship("YieldRecord", back_populates="field")\n\n\nclass Crop(Base):\n    __tablename__ = "crops"\n\n    id = Column(Integer, primary_key=True)\n    name = Column(String(64), unique=True, nullable=False)\n    category = Column(String(32), nullable=False, default="don")\n    season = Column(String(32), nullable=False, default="yozgi")\n    water_need_mm = Column(Float, nullable=False, default=500.0)\n    base_yield_t_ha = Column(Float, nullable=False, default=3.0)\n    base_price_per_kg = Column(Float, nullable=False, default=3000.0)\n    cost_per_ha = Column(Float, nullable=False, default=6_000_000.0)\n\n\nclass YieldRecord(Base):\n    __tablename__ = "yield_records"\n\n    id = Column(Integer, primary_key=True)\n    field_id = Column(Integer, ForeignKey("fields.id"), nullable=False, index=True)\n    crop_id = Column(Integer, ForeignKey("crops.id"), nullable=False, index=True)\n    year = Column(Integer, nullable=False, index=True)\n    area_ha = Column(Float, nullable=False)\n    yield_t_ha = Column(Float, nullable=False)\n    production_t = Column(Float, nullable=False)\n\n    field = relationship("Field", back_populates="yields")\n    crop = relationship("Crop")\n\n\nclass WeatherRecord(Base):\n    __tablename__ = "weather_records"\n\n    id = Column(Integer, primary_key=True)\n    district_id = Column(Integer, ForeignKey("districts.id"), nullable=False, index=True)\n    date = Column(Date, nullable=False, index=True)\n    t_min = Column(Float, nullable=False)\n    t_max = Column(Float, nullable=False)\n    precipitation_mm = Column(Float, nullable=False, default=0.0)\n    humidity = Column(Float, nullable=False, default=50.0)\n    source = Column(String(32), nullable=False, default="demo")\n\n\nclass MarketPrice(Base):\n    __tablename__ = "market_prices"\n\n    id = Column(Integer, primary_key=True)\n    crop_id = Column(Integer, ForeignKey("crops.id"), nullable=False, index=True)\n    date = Column(Date, nullable=False, index=True)\n    price_per_kg = Column(Float, nullable=False)\n    market_name = Column(String(64), nullable=False, default="Milliy bozor")\n    source = Column(String(32), nullable=False, default="demo")\n\n    crop = relationship("Crop")\n\n\nclass IrrigationRecord(Base):\n    __tablename__ = "irrigation_records"\n\n    id = Column(Integer, primary_key=True)\n    field_id = Column(Integer, ForeignKey("fields.id"), nullable=False, index=True)\n    date = Column(Date, nullable=False, index=True)\n    water_m3 = Column(Float, nullable=False)\n    method = Column(String(32), nullable=False, default="egat")\n\n\nclass FinanceRecord(Base):\n    __tablename__ = "finance_records"\n\n    id = Column(Integer, primary_key=True)\n    farm_id = Column(Integer, ForeignKey("farms.id"), nullable=False, index=True)\n    year = Column(Integer, nullable=False, index=True)\n    category = Column(String(32), nullable=False)  # income|expense|credit|subsidy\n    amount = Column(Float, nullable=False)\n    note = Column(String(256), nullable=False, default="")\n\n\nclass SatelliteIndex(Base):\n    __tablename__ = "satellite_indices"\n\n    id = Column(Integer, primary_key=True)\n    field_id = Column(Integer, ForeignKey("fields.id"), nullable=False, index=True)\n    date = Column(Date, nullable=False, index=True)\n    ndvi = Column(Float, nullable=False)\n    evi = Column(Float, nullable=False)\n    source = Column(String(32), nullable=False, default="demo")\n\n\nclass ImportedFile(Base):\n    __tablename__ = "imported_files"\n\n    id = Column(Integer, primary_key=True)\n    filename = Column(String(256), nullable=False)\n    file_type = Column(String(32), nullable=False)\n    uploaded_at = Column(DateTime, default=datetime.utcnow, nullable=False)\n    uploaded_by = Column(String(64), nullable=False, default="")\n    summary = Column(Text, nullable=False, default="")\n\n\ndef today() -> date:\n    """Convenience wrapper so services avoid importing datetime everywhere."""\n    return date.today()\n',
    'database.seed': '"""First-launch installer: deterministic, realistic demo dataset for Uzbekistan.\n\nSeeds users, 13 regions, 26 districts, 60+ farmers, 75+ farms, 140+ fields,\n23 crops, 5 years of yields driven by generated weather (including a 2024\nJizzax drought scenario), weekly market prices, irrigation events, finance\nrecords and NDVI/EVI time series. All randomness uses a fixed seed so every\ninstallation produces the same coherent dataset.\n"""\nfrom __future__ import annotations\n\nimport json\nimport logging\nfrom datetime import date, timedelta\n\nimport numpy as np\n\nfrom config import settings\nfrom core.security import hash_password\nfrom database.engine import get_engine, session_scope\nfrom database.models import (\n    Crop, District, Farm, Farmer, Field, FinanceRecord, IrrigationRecord,\n    MarketPrice, Region, SatelliteIndex, User, WeatherRecord, YieldRecord,\n)\n\nlog = logging.getLogger(__name__)\nrng = np.random.default_rng(42)\n\nHISTORY_YEARS = list(range(settings.HISTORY_START_YEAR, settings.HISTORY_START_YEAR + 5))\n\n# region name -> (lat, lon, fertility, south_factor, [districts])\nREGIONS: dict[str, tuple[float, float, float, float, list[str]]] = {\n    "Toshkent": (41.31, 69.28, 1.05, 0.0, ["Zangiota", "Chinoz"]),\n    "Andijon": (40.78, 72.34, 1.12, 0.2, ["Asaka", "Marhamat"]),\n    "Farg\'ona": (40.39, 71.78, 1.10, 0.2, ["Quva", "Rishton"]),\n    "Namangan": (41.00, 71.67, 1.08, 0.1, ["Chust", "Pop"]),\n    "Samarqand": (39.65, 66.96, 1.06, 0.3, ["Urgut", "Ishtixon"]),\n    "Buxoro": (39.77, 64.42, 0.95, 0.5, ["G\'ijduvon", "Kogon"]),\n    "Jizzax": (40.12, 67.83, 0.98, 0.3, ["Zomin", "G\'allaorol"]),\n    "Qashqadaryo": (38.86, 65.79, 0.97, 0.6, ["Shahrisabz", "Koson"]),\n    "Surxondaryo": (37.94, 67.57, 1.02, 0.9, ["Denov", "Sherobod"]),\n    "Sirdaryo": (40.84, 68.66, 1.00, 0.1, ["Guliston", "Boyovut"]),\n    "Navoiy": (40.09, 65.38, 0.90, 0.4, ["Karmana", "Qiziltepa"]),\n    "Xorazm": (41.55, 60.63, 0.96, 0.2, ["Urganch", "Xiva"]),\n    "Qoraqalpog\'iston": (42.46, 59.61, 0.85, 0.0, ["Nukus", "Chimboy"]),\n}\n\n# name, category, season, water_mm, base_yield t/ha, price so\'m/kg, cost so\'m/ha\nCROPS: list[tuple[str, str, str, float, float, float, float]] = [\n    ("Bug\'doy", "don", "kuzgi", 450, 4.5, 3000, 6_000_000),\n    ("Paxta", "texnik", "yozgi", 700, 3.2, 8000, 12_000_000),\n    ("Sholi", "don", "yozgi", 1200, 5.0, 7000, 10_000_000),\n    ("Makkajo\'xori", "don", "yozgi", 550, 7.0, 2800, 7_000_000),\n    ("Arpa", "don", "kuzgi", 400, 3.8, 2500, 5_000_000),\n    ("Kartoshka", "sabzavot", "bahorgi", 500, 22.0, 4000, 25_000_000),\n    ("Sabzi", "sabzavot", "bahorgi", 450, 30.0, 3000, 18_000_000),\n    ("Piyoz", "sabzavot", "bahorgi", 480, 28.0, 2500, 16_000_000),\n    ("Pomidor", "sabzavot", "yozgi", 600, 40.0, 5000, 30_000_000),\n    ("Bodring", "sabzavot", "yozgi", 550, 35.0, 4500, 26_000_000),\n    ("Qovun", "poliz", "yozgi", 400, 20.0, 4000, 12_000_000),\n    ("Tarvuz", "poliz", "yozgi", 380, 25.0, 2000, 10_000_000),\n    ("Uzum", "meva", "ko\'p yillik", 500, 12.0, 8000, 20_000_000),\n    ("Olma", "meva", "ko\'p yillik", 600, 18.0, 6000, 22_000_000),\n    ("O\'rik", "meva", "ko\'p yillik", 500, 10.0, 9000, 15_000_000),\n    ("Shaftoli", "meva", "ko\'p yillik", 550, 12.0, 8500, 18_000_000),\n    ("Anor", "meva", "ko\'p yillik", 520, 14.0, 12000, 20_000_000),\n    ("Yong\'oq", "meva", "ko\'p yillik", 480, 3.0, 35000, 14_000_000),\n    ("Soya", "dukkakli", "yozgi", 450, 2.5, 6000, 6_000_000),\n    ("Kungaboqar", "moyli", "yozgi", 420, 2.2, 5500, 5_000_000),\n    ("Beda", "ozuqa", "ko\'p yillik", 800, 9.0, 1500, 4_000_000),\n    ("Qand lavlagi", "texnik", "yozgi", 600, 35.0, 1200, 15_000_000),\n    ("Sarimsoq", "sabzavot", "kuzgi", 400, 8.0, 15000, 20_000_000),\n]\n\nFIRST_NAMES = [\n    "Akmal", "Bobur", "Davron", "Eldor", "Farrux", "G\'ayrat", "Hasan", "Islom",\n    "Jasur", "Kamol", "Laziz", "Muzaffar", "Nodir", "Otabek", "Po\'lat", "Qudrat",\n    "Rustam", "Sardor", "Temur", "Ulug\'bek", "Vali", "Xurshid", "Yusuf", "Zafar",\n    "Dilnoza", "Gulnora", "Malika", "Nilufar", "Sevara", "Zulfiya",\n]\nLAST_NAMES = [\n    "Karimov", "Rahimov", "Toshmatov", "Yusupov", "Aliyev", "Islomov", "Saidov",\n    "Nazarov", "Ergashev", "Qodirov", "Mirzayev", "Abdullayev", "Sultonov",\n    "Xolmatov", "Bekmurodov", "Jo\'rayev", "Olimov", "Sharipov", "Umarov", "Vohidov",\n]\nSOIL_TYPES = ["bo\'z tuproq", "o\'tloq tuproq", "sho\'rlangan tuproq", "qumloq tuproq", "gilli tuproq"]\nIRRIGATION_METHODS = ["egat", "tomchilatib", "yomg\'irlatib", "bostirib"]\n\n# Financial calibration: farmers realise ~45% of the retail market price\n# (wholesale), and full production cost (labour, fuel, rent, inputs) runs\n# 1.5–1.9x of the base agronomic cost — keeps demo ROI in a realistic range.\nWHOLESALE_FACTOR = 0.45\nEXPENSE_FACTOR_RANGE = (1.5, 1.9)\n\n\ndef is_seeded() -> bool:\n    """The database counts as installed when at least one user exists."""\n    try:\n        with session_scope() as session:\n            return session.query(User).count() > 0\n    except Exception:  # noqa: BLE001\n        return False\n\n\ndef seed_if_empty() -> bool:\n    """Populate the demo dataset on first launch. Returns True when seeded."""\n    if is_seeded():\n        return False\n    log.info("Demo ma\'lumotlar yaratilmoqda (birinchi ishga tushirish)...")\n    _seed_users()\n    region_rows, district_rows = _seed_geography()\n    crop_rows = _seed_crops()\n    farms, fields = _seed_farms(district_rows)\n    weather = _seed_weather(district_rows)\n    ratios = _seed_yields_and_irrigation(fields, crop_rows, district_rows, weather)\n    price_index = _seed_market_prices(crop_rows)\n    _seed_finance(farms, fields, crop_rows, price_index)\n    _seed_satellite(fields, ratios)\n    log.info("Demo ma\'lumotlar tayyor: %d viloyat, %d tuman, %d dala.",\n             len(region_rows), len(district_rows), len(fields))\n    return True\n\n\ndef _seed_users() -> None:\n    with session_scope() as session:\n        session.add_all([\n            User(username="admin", full_name="Bosh administrator",\n                 password_hash=hash_password("admin123"), role="admin"),\n            User(username="menejer", full_name="Hudud menejeri",\n                 password_hash=hash_password("manager123"), role="manager"),\n            User(username="kuzatuvchi", full_name="Tahlilchi-kuzatuvchi",\n                 password_hash=hash_password("viewer123"), role="viewer"),\n        ])\n\n\ndef _seed_geography() -> tuple[list[Region], list[District]]:\n    regions: list[Region] = []\n    districts: list[District] = []\n    with session_scope() as session:\n        for name, (lat, lon, fertility, _south, district_names) in REGIONS.items():\n            region = Region(name=name, lat=lat, lon=lon, fertility=fertility)\n            session.add(region)\n            session.flush()\n            regions.append(region)\n            for i, dname in enumerate(district_names):\n                district = District(\n                    region_id=region.id, name=f"{dname} tumani",\n                    lat=lat + (0.25 if i == 0 else -0.25) + float(rng.normal(0, 0.05)),\n                    lon=lon + (0.30 if i == 0 else -0.30) + float(rng.normal(0, 0.05)),\n                )\n                session.add(district)\n                districts.append(district)\n        session.flush()\n    return regions, districts\n\n\ndef _seed_crops() -> list[Crop]:\n    crops: list[Crop] = []\n    with session_scope() as session:\n        for name, category, season, water, yield_t, price, cost in CROPS:\n            crop = Crop(name=name, category=category, season=season,\n                        water_need_mm=water, base_yield_t_ha=yield_t,\n                        base_price_per_kg=price, cost_per_ha=cost)\n            session.add(crop)\n            crops.append(crop)\n        session.flush()\n    return crops\n\n\ndef _field_polygon(lat: float, lon: float, area_ha: float) -> str:\n    """Build an irregular quadrilateral GeoJSON polygon roughly sized to area."""\n    half = max(0.0012, float(np.sqrt(area_ha)) * 0.00045)\n    jitter = lambda: float(rng.normal(0, half * 0.15))  # noqa: E731\n    ring = [\n        [lon - half + jitter(), lat - half + jitter()],\n        [lon + half + jitter(), lat - half + jitter()],\n        [lon + half + jitter(), lat + half + jitter()],\n        [lon - half + jitter(), lat + half + jitter()],\n    ]\n    ring.append(ring[0])\n    return json.dumps({"type": "Polygon", "coordinates": [ring]})\n\n\ndef _seed_farms(districts: list[District]) -> tuple[list[Farm], list[Field]]:\n    farmers: list[Farmer] = []\n    farms: list[Farm] = []\n    fields: list[Field] = []\n    with session_scope() as session:\n        for i in range(60):\n            district = districts[int(rng.integers(0, len(districts)))]\n            name = (f"{FIRST_NAMES[int(rng.integers(0, len(FIRST_NAMES)))]} "\n                    f"{LAST_NAMES[int(rng.integers(0, len(LAST_NAMES)))]}")\n            farmer = Farmer(\n                name=name, district_id=district.id,\n                phone=f"+9989{rng.integers(0, 10)}{rng.integers(1_000_000, 9_999_999)}",\n            )\n            session.add(farmer)\n            farmers.append(farmer)\n        session.flush()\n\n        farm_no = 0\n        for farmer in farmers:\n            for _ in range(1 + int(rng.random() < 0.25)):  # ~75 farms\n                farm_no += 1\n                farm = Farm(\n                    name=f"{farmer.name.split()[-1]} fermer xo\'jaligi №{farm_no}",\n                    farmer_id=farmer.id, district_id=farmer.district_id, area_ha=0.0,\n                )\n                session.add(farm)\n                farms.append(farm)\n        session.flush()\n\n        district_by_id = {d.id: d for d in districts}\n        field_no = 0\n        while len(fields) < 140:\n            farm = farms[int(rng.integers(0, len(farms)))]\n            district = district_by_id[farm.district_id]\n            field_no += 1\n            area = float(np.round(rng.uniform(5, 120), 1))\n            lat = district.lat + float(rng.uniform(-0.12, 0.12))\n            lon = district.lon + float(rng.uniform(-0.12, 0.12))\n            field = Field(\n                farm_id=farm.id, name=f"Kontur-{field_no}", area_ha=area,\n                soil_type=SOIL_TYPES[int(rng.integers(0, len(SOIL_TYPES)))],\n                lat=lat, lon=lon, geometry_geojson=_field_polygon(lat, lon, area),\n            )\n            farm.area_ha = float(np.round(farm.area_ha + area, 1))\n            session.add(field)\n            fields.append(field)\n        session.flush()\n    return farms, fields\n\n\ndef _seed_weather(districts: list[District]) -> dict[tuple[int, int], dict[str, float]]:\n    """Generate daily weather per district; return per (district, year) season stats."""\n    start = date(settings.HISTORY_START_YEAR, 1, 1)\n    end = date.today()\n    n_days = (end - start).days + 1\n    dates = [start + timedelta(days=i) for i in range(n_days)]\n    doy = np.array([d.timetuple().tm_yday for d in dates], dtype=float)\n    years = np.array([d.year for d in dates])\n    months = np.array([d.month for d in dates])\n\n    region_by_district: dict[int, tuple[str, float]] = {}\n    with session_scope() as session:\n        for district in districts:\n            region = session.get(Region, district.region_id)\n            south = REGIONS[region.name][3]\n            region_by_district[district.id] = (region.name, south)\n\n    season_mask = np.isin(months, settings.WEATHER_SEASON_MONTHS)\n    stats: dict[tuple[int, int], dict[str, float]] = {}\n    table = WeatherRecord.__table__\n    engine = get_engine()\n\n    for district in districts:\n        region_name, south = region_by_district[district.id]\n        seasonal = 14.0 + 14.5 * np.sin((doy - 105) / 365.0 * 2 * np.pi)\n        t_max = seasonal + 6 + south * 3 + rng.normal(0, 2.5, n_days)\n        t_min = seasonal - 5 + south * 2 + rng.normal(0, 2.0, n_days)\n        rain_prob = 0.22 + 0.16 * np.cos((doy - 60) / 365.0 * 2 * np.pi)\n        rain = (rng.random(n_days) < rain_prob) * rng.exponential(4.5, n_days)\n        rain = np.where(np.isin(months, (6, 7, 8)), rain * 0.25, rain)\n        # 2024 drought scenario in Jizzax region — feeds analytics & the AI module.\n        if region_name == "Jizzax":\n            rain = np.where(years == 2024, rain * 0.45, rain)\n        humidity = np.clip(78 - (t_max - 10) * 1.3 + rng.normal(0, 6, n_days), 15, 98)\n\n        rows = [\n            {\n                "district_id": district.id, "date": dates[i],\n                "t_min": round(float(t_min[i]), 1), "t_max": round(float(t_max[i]), 1),\n                "precipitation_mm": round(float(rain[i]), 1),\n                "humidity": round(float(humidity[i]), 1), "source": "demo",\n            }\n            for i in range(n_days)\n        ]\n        with engine.begin() as connection:\n            connection.execute(table.insert(), rows)\n\n        for year in set(years.tolist()):\n            mask = (years == year) & season_mask\n            if mask.any():\n                stats[(district.id, int(year))] = {\n                    "precip": float(rain[mask].sum()),\n                    "t_avg": float(((t_max + t_min) / 2)[mask].mean()),\n                    "humidity": float(humidity[mask].mean()),\n                }\n    return stats\n\n\ndef _seed_yields_and_irrigation(\n    fields: list[Field], crops: list[Crop], districts: list[District],\n    weather: dict[tuple[int, int], dict[str, float]],\n) -> dict[tuple[int, int], float]:\n    """Yields derive from water supply vs crop need — ML models learn real signal."""\n    fertility_by_district: dict[int, float] = {}\n    region_name_by_district: dict[int, str] = {}\n    with session_scope() as session:\n        for district in districts:\n            region = session.get(Region, district.region_id)\n            fertility_by_district[district.id] = region.fertility\n            region_name_by_district[district.id] = region.name\n        farms = {farm.id: farm.district_id\n                 for farm in session.query(Farm).all()}  # farm -> district\n\n    ratios: dict[tuple[int, int], float] = {}\n    yield_rows: list[dict] = []\n    irrigation_rows: list[dict] = []\n\n    for field in fields:\n        district_id = farms[field.farm_id]\n        # Real crop mix: every field\'s 3-crop rotation contains one strategic\n        # crop (wheat or cotton) so region×crop analytics are well-populated.\n        pool_idx = [int(rng.integers(0, 2))]\n        pool_idx += [int(i) for i in rng.choice(\n            np.arange(2, len(crops)), size=2, replace=False)]\n        rotation_offset = int(rng.integers(0, 3))\n        for year in HISTORY_YEARS:\n            crop = crops[pool_idx[(year + rotation_offset) % 3]]\n            season = weather.get((district_id, year), {"precip": 120.0, "t_avg": 24.0})\n            coverage = float(rng.uniform(0.45, 0.85))\n            if year == 2024 and region_name_by_district[district_id] == "Jizzax":\n                coverage *= 0.65  # drought year canal restrictions\n            irrigation_mm = crop.water_need_mm * coverage\n            supply = season["precip"] + irrigation_mm\n            ratio = float(np.clip(supply / crop.water_need_mm, 0.35, 1.15))\n            heat_penalty = 1.0 - max(0.0, season["t_avg"] - 27.0) * 0.03\n            yield_t = max(\n                0.2,\n                crop.base_yield_t_ha * ratio * fertility_by_district[district_id]\n                * heat_penalty * float(1 + rng.normal(0, 0.08)),\n            )\n            ratios[(field.id, year)] = ratio\n            yield_rows.append({\n                "field_id": field.id, "crop_id": crop.id, "year": year,\n                "area_ha": field.area_ha, "yield_t_ha": round(yield_t, 2),\n                "production_t": round(yield_t * field.area_ha, 1),\n            })\n            total_m3 = irrigation_mm * 10 * field.area_ha  # 1 mm/ha = 10 m3\n            method = IRRIGATION_METHODS[int(rng.integers(0, len(IRRIGATION_METHODS)))]\n            for month in (4, 5, 6, 7, 8):\n                irrigation_rows.append({\n                    "field_id": field.id,\n                    "date": date(year, month, int(rng.integers(1, 28))),\n                    "water_m3": round(total_m3 / 5, 0), "method": method,\n                })\n\n    engine = get_engine()\n    with engine.begin() as connection:\n        connection.execute(YieldRecord.__table__.insert(), yield_rows)\n        connection.execute(IrrigationRecord.__table__.insert(), irrigation_rows)\n    return ratios\n\n\ndef _seed_market_prices(crops: list[Crop]) -> dict[tuple[int, int], float]:\n    """Weekly national market prices with inflation + seasonality. Returns yearly avg."""\n    start = date(settings.HISTORY_START_YEAR, 1, 4)\n    end = date.today()\n    price_rows: list[dict] = []\n    yearly: dict[tuple[int, int], list[float]] = {}\n    for crop in crops:\n        phase = float(rng.uniform(0, 2 * np.pi))\n        day = start\n        while day <= end:\n            years_passed = day.year - settings.HISTORY_START_YEAR\n            seasonal = 1 + 0.13 * np.sin(2 * np.pi * day.timetuple().tm_yday / 365 + phase)\n            price = crop.base_price_per_kg * (1 + 0.09 * years_passed) * seasonal\n            price *= float(1 + rng.normal(0, 0.04))\n            price_rows.append({\n                "crop_id": crop.id, "date": day, "price_per_kg": round(price, 0),\n                "market_name": "Milliy bozor", "source": "demo",\n            })\n            yearly.setdefault((crop.id, day.year), []).append(price)\n            day += timedelta(days=7)\n    with get_engine().begin() as connection:\n        connection.execute(MarketPrice.__table__.insert(), price_rows)\n    return {key: float(np.mean(values)) for key, values in yearly.items()}\n\n\ndef _seed_finance(\n    farms: list[Farm], fields: list[Field], crops: list[Crop],\n    price_index: dict[tuple[int, int], float],\n) -> None:\n    crop_by_id = {crop.id: crop for crop in crops}\n    fields_by_farm: dict[int, list[Field]] = {}\n    for field in fields:\n        fields_by_farm.setdefault(field.farm_id, []).append(field)\n\n    from database.engine import read_df\n    yields_df = read_df(\n        "SELECT f.farm_id, y.field_id, y.crop_id, y.year, y.production_t, y.area_ha "\n        "FROM yield_records y JOIN fields f ON f.id = y.field_id"\n    )\n\n    rows: list[dict] = []\n    for farm in farms:\n        farm_yields = yields_df[yields_df.farm_id == farm.id]\n        for year in HISTORY_YEARS:\n            year_slice = farm_yields[farm_yields.year == year]\n            if year_slice.empty:\n                continue\n            expense = float(sum(\n                row.area_ha * crop_by_id[row.crop_id].cost_per_ha\n                for row in year_slice.itertuples()\n            )) * float(rng.uniform(*EXPENSE_FACTOR_RANGE))\n            income = float(sum(\n                row.production_t * 1000\n                * price_index.get((row.crop_id, year),\n                                  crop_by_id[row.crop_id].base_price_per_kg)\n                for row in year_slice.itertuples()\n            )) * WHOLESALE_FACTOR * float(rng.uniform(0.93, 1.05))\n            rows.append({"farm_id": farm.id, "year": year, "category": "expense",\n                         "amount": round(expense, 0), "note": "Yillik ishlab chiqarish xarajatlari"})\n            rows.append({"farm_id": farm.id, "year": year, "category": "income",\n                         "amount": round(income, 0), "note": "Mahsulot sotuvidan tushum"})\n            if rng.random() < 0.35:\n                rows.append({"farm_id": farm.id, "year": year, "category": "credit",\n                             "amount": round(expense * 0.3, 0), "note": "Agrobank imtiyozli krediti"})\n            if rng.random() < 0.4:\n                rows.append({"farm_id": farm.id, "year": year, "category": "subsidy",\n                             "amount": round(expense * 0.1, 0), "note": "Davlat subsidiyasi"})\n    with get_engine().begin() as connection:\n        connection.execute(FinanceRecord.__table__.insert(), rows)\n\n\ndef _seed_satellite(fields: list[Field], ratios: dict[tuple[int, int], float]) -> None:\n    """Bi-weekly NDVI/EVI series for the last ~30 months per field."""\n    end = date.today()\n    start = end - timedelta(days=900)\n    rows: list[dict] = []\n    for field in fields:\n        day = start\n        while day <= end:\n            doy = day.timetuple().tm_yday\n            year_ratio = ratios.get((field.id, min(day.year, HISTORY_YEARS[-1])), 0.8)\n            peak = 0.30 + 0.42 * year_ratio\n            ndvi = 0.14 + peak * float(np.exp(-((doy - 165) / 72.0) ** 2))\n            ndvi = float(np.clip(ndvi + rng.normal(0, 0.03), 0.05, 0.95))\n            evi = float(np.clip(ndvi * 0.85 + rng.normal(0, 0.02), 0.03, 0.9))\n            rows.append({"field_id": field.id, "date": day, "ndvi": round(ndvi, 3),\n                         "evi": round(evi, 3), "source": "demo"})\n            day += timedelta(days=14)\n    with get_engine().begin() as connection:\n        connection.execute(SatelliteIndex.__table__.insert(), rows)\n',
    'finance': '"""Finance module: income, expenses, credits, subsidies, profitability."""\n',
    'finance.service': '"""Financial analytics: P&L, ROI, credits and subsidies."""\nfrom __future__ import annotations\n\nimport pandas as pd\n\nfrom core.cache import cached\nfrom database.engine import read_df\n\n\n@cached(ttl=120)\ndef yearly_summary() -> pd.DataFrame:\n    """Income / expense / profit / ROI per year (platform-wide)."""\n    df = read_df(\n        "SELECT year,"\n        " SUM(CASE WHEN category=\'income\' THEN amount ELSE 0 END) AS income,"\n        " SUM(CASE WHEN category=\'expense\' THEN amount ELSE 0 END) AS expense,"\n        " SUM(CASE WHEN category=\'credit\' THEN amount ELSE 0 END) AS credit,"\n        " SUM(CASE WHEN category=\'subsidy\' THEN amount ELSE 0 END) AS subsidy"\n        " FROM finance_records GROUP BY year ORDER BY year"\n    )\n    if df.empty:\n        return df\n    df["profit"] = df["income"] - df["expense"]\n    df["roi"] = (df["profit"] / df["expense"].clip(lower=1) * 100).round(1)\n    return df\n\n\n@cached(ttl=120)\ndef by_region(year: int) -> pd.DataFrame:\n    """Regional profitability table."""\n    df = read_df(\n        "SELECT r.name AS region,"\n        " SUM(CASE WHEN fr.category=\'income\' THEN fr.amount ELSE 0 END) AS income,"\n        " SUM(CASE WHEN fr.category=\'expense\' THEN fr.amount ELSE 0 END) AS expense,"\n        " SUM(CASE WHEN fr.category=\'credit\' THEN fr.amount ELSE 0 END) AS credit,"\n        " SUM(CASE WHEN fr.category=\'subsidy\' THEN fr.amount ELSE 0 END) AS subsidy"\n        " FROM finance_records fr"\n        " JOIN farms fa ON fa.id = fr.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE fr.year = :y GROUP BY r.name", {"y": year},\n    )\n    if df.empty:\n        return df\n    df["profit"] = df["income"] - df["expense"]\n    df["roi"] = (df["profit"] / df["expense"].clip(lower=1) * 100).round(1)\n    return df.sort_values("profit", ascending=False)\n\n\n@cached(ttl=120)\ndef farm_profitability(year: int, limit: int = 15) -> pd.DataFrame:\n    """Per-farm profit ranking for the given year."""\n    df = read_df(\n        "SELECT fa.name AS farm, r.name AS region,"\n        " SUM(CASE WHEN fr.category=\'income\' THEN fr.amount ELSE 0 END) AS income,"\n        " SUM(CASE WHEN fr.category=\'expense\' THEN fr.amount ELSE 0 END) AS expense"\n        " FROM finance_records fr"\n        " JOIN farms fa ON fa.id = fr.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE fr.year = :y GROUP BY fa.id", {"y": year},\n    )\n    if df.empty:\n        return df\n    df["profit"] = df["income"] - df["expense"]\n    df["roi"] = (df["profit"] / df["expense"].clip(lower=1) * 100).round(1)\n    return df.sort_values("profit", ascending=False).head(limit)\n\n\n@cached(ttl=120)\ndef credits_and_subsidies(year: int) -> pd.DataFrame:\n    """Credit / subsidy registry rows for the given year."""\n    return read_df(\n        "SELECT fa.name AS farm, fr.category, fr.amount, fr.note"\n        " FROM finance_records fr JOIN farms fa ON fa.id = fr.farm_id"\n        " WHERE fr.year = :y AND fr.category IN (\'credit\',\'subsidy\')"\n        " ORDER BY fr.amount DESC", {"y": year},\n    )\n',
    'gis': '"""GIS layer: interactive folium maps, geometry helpers."""\n',
    'gis.geo': '"""Geometry helpers that work with or without Shapely/GeoPandas."""\nfrom __future__ import annotations\n\nimport json\nfrom typing import Any\n\nfrom core.optional import try_import\n\n\ndef polygon_centroid(geojson_text: str) -> tuple[float, float] | None:\n    """Centroid (lat, lon) of a GeoJSON polygon; Shapely if present, else mean."""\n    try:\n        geometry = json.loads(geojson_text)\n        ring = geometry["coordinates"][0]\n    except (json.JSONDecodeError, KeyError, IndexError, TypeError):\n        return None\n    shapely_geom = try_import("shapely.geometry")\n    if shapely_geom is not None:\n        try:\n            centroid = shapely_geom.shape(geometry).centroid\n            return float(centroid.y), float(centroid.x)\n        except Exception:  # noqa: BLE001\n            pass\n    lons = [point[0] for point in ring]\n    lats = [point[1] for point in ring]\n    return sum(lats) / len(lats), sum(lons) / len(lons)\n\n\ndef polygon_area_ha(geojson_text: str) -> float | None:\n    """Approximate polygon area in hectares (pyproj-accurate when available)."""\n    try:\n        geometry = json.loads(geojson_text)\n        ring = geometry["coordinates"][0]\n    except (json.JSONDecodeError, KeyError, IndexError, TypeError):\n        return None\n    shapely_geom = try_import("shapely.geometry")\n    pyproj = try_import("pyproj")\n    if shapely_geom is not None and pyproj is not None:\n        try:\n            from shapely.ops import transform\n\n            shape = shapely_geom.shape(geometry)\n            transformer = pyproj.Transformer.from_crs(\n                "EPSG:4326", "EPSG:6933", always_xy=True).transform\n            return round(transform(transformer, shape).area / 10_000, 2)\n        except Exception:  # noqa: BLE001\n            pass\n    # Shoelace formula on a local equirectangular projection (adequate <10 km).\n    import math\n\n    lat0 = sum(point[1] for point in ring) / len(ring)\n    metre_per_deg_lat = 111_320.0\n    metre_per_deg_lon = 111_320.0 * math.cos(math.radians(lat0))\n    xy = [(point[0] * metre_per_deg_lon, point[1] * metre_per_deg_lat) for point in ring]\n    area = 0.0\n    for i in range(len(xy) - 1):\n        area += xy[i][0] * xy[i + 1][1] - xy[i + 1][0] * xy[i][1]\n    return round(abs(area) / 2 / 10_000, 2)\n\n\ndef feature_collection(features: list[dict[str, Any]]) -> dict[str, Any]:\n    """Wrap features into a GeoJSON FeatureCollection."""\n    return {"type": "FeatureCollection", "features": features}\n',
    'gis.maps': '"""Interactive folium map builder: layers, clusters, heatmaps, choropleth."""\nfrom __future__ import annotations\n\nimport json\nimport logging\n\nimport folium\nfrom folium.plugins import Fullscreen, HeatMap, MarkerCluster\n\nfrom database.engine import get_setting, read_df\n\nlog = logging.getLogger(__name__)\n\nTILE_LAYERS = [\n    ("OpenStreetMap", "OpenStreetMap", "Ko\'cha xaritasi"),\n    ("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",\n     "Esri", "Sun\'iy yo\'ldosh"),\n    ("https://tile.opentopomap.org/{z}/{x}/{y}.png", "OpenTopoMap", "Relyef"),\n]\n\n\ndef _color_for(value: float, low: float, high: float) -> str:\n    """Green-yellow-red scale for the metric legend."""\n    if high - low < 1e-9:\n        return "#4caf50"\n    ratio = max(0.0, min(1.0, (value - low) / (high - low)))\n    if ratio > 0.66:\n        return "#2e7d32"\n    if ratio > 0.33:\n        return "#f9a825"\n    return "#c62828"\n\n\ndef _fields_frame(year: int, region_id: int | None) -> "object":\n    sql = (\n        "SELECT f.id, f.name, f.area_ha, f.soil_type, f.lat, f.lon,"\n        " f.geometry_geojson, fa.name AS farm, fm.name AS farmer,"\n        " r.name AS region, r.id AS region_id, d.name AS district,"\n        " COALESCE(y.yield_t_ha, 0) AS yield_t_ha,"\n        " COALESCE(c.name, \'-\') AS crop,"\n        " COALESCE(s.ndvi, 0) AS ndvi"\n        " FROM fields f"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN farmers fm ON fm.id = fa.farmer_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " LEFT JOIN yield_records y ON y.field_id = f.id AND y.year = :year"\n        " LEFT JOIN crops c ON c.id = y.crop_id"\n        " LEFT JOIN (SELECT field_id, ndvi, MAX(date) FROM satellite_indices"\n        "            GROUP BY field_id) s ON s.field_id = f.id"\n    )\n    params: dict = {"year": year}\n    if region_id:\n        sql += " WHERE r.id = :region_id"\n        params["region_id"] = region_id\n    return read_df(sql, params)\n\n\ndef build_map(metric: str = "yield", year: int | None = None,\n              region_id: int | None = None, height: int = 640) -> str:\n    """Render the interactive map to embeddable HTML.\n\n    metric: \'yield\' colors polygons by t/ha, \'ndvi\' by vegetation index.\n    Layers: 3 tile sets, field polygons, farm marker cluster, heatmap.\n    """\n    from analytics.kpi import latest_year\n\n    year = year or latest_year()\n    df = _fields_frame(year, region_id)\n\n    center = [float(get_setting("map_default_lat", "41.3")),\n              float(get_setting("map_default_lon", "64.5"))]\n    zoom = int(get_setting("map_default_zoom", "6"))\n    if region_id and not df.empty:\n        center = [float(df.lat.mean()), float(df.lon.mean())]\n        zoom = 9\n\n    fmap = folium.Map(location=center, zoom_start=zoom, tiles=None,\n                      control_scale=True)\n    for tiles, attr, label in TILE_LAYERS:\n        folium.TileLayer(tiles=tiles, attr=attr, name=label,\n                         show=(label == "Ko\'cha xaritasi")).add_to(fmap)\n\n    metric_column = "ndvi" if metric == "ndvi" else "yield_t_ha"\n    metric_label = "NDVI" if metric == "ndvi" else "Hosildorlik (t/ga)"\n    values = df[metric_column].astype(float)\n    low, high = (float(values.min()), float(values.max())) if len(values) else (0, 1)\n\n    polygons = folium.FeatureGroup(name=f"Dalalar — {metric_label}", show=True)\n    heat_points: list[list[float]] = []\n    for row in df.itertuples():\n        try:\n            geometry = json.loads(row.geometry_geojson)\n        except (json.JSONDecodeError, TypeError):\n            continue\n        value = float(getattr(row, metric_column))\n        color = _color_for(value, low, high)\n        popup = folium.Popup(\n            f"<b>{row.name}</b><br>"\n            f"Fermer xo\'jaligi: {row.farm}<br>"\n            f"Fermer: {row.farmer}<br>"\n            f"Hudud: {row.region}, {row.district}<br>"\n            f"Maydon: {row.area_ha} ga | Tuproq: {row.soil_type}<br>"\n            f"Ekin ({year}): {row.crop}<br>"\n            f"Hosildorlik: {row.yield_t_ha} t/ga | NDVI: {row.ndvi:.2f}",\n            max_width=320,\n        )\n        folium.GeoJson(\n            {"type": "Feature", "geometry": geometry},\n            style_function=lambda _f, c=color: {\n                "fillColor": c, "color": c, "weight": 2, "fillOpacity": 0.45,\n            },\n            tooltip=f"{row.name}: {value:.2f}",\n        ).add_child(popup).add_to(polygons)\n        heat_points.append([row.lat, row.lon, max(0.05, value)])\n    polygons.add_to(fmap)\n\n    cluster = MarkerCluster(name="Fermer xo\'jaliklari").add_to(fmap)\n    farms = df.groupby("farm").agg(\n        lat=("lat", "mean"), lon=("lon", "mean"),\n        area=("area_ha", "sum"), region=("region", "first"),\n    ).reset_index()\n    for row in farms.itertuples():\n        folium.Marker(\n            [row.lat, row.lon],\n            icon=folium.Icon(color="green", icon="leaf"),\n            popup=f"<b>{row.farm}</b><br>{row.region}<br>Jami: {row.area:.0f} ga",\n        ).add_to(cluster)\n\n    if heat_points:\n        HeatMap(heat_points, name=f"Issiqlik xaritasi — {metric_label}",\n                radius=22, show=False).add_to(fmap)\n\n    Fullscreen(title="To\'liq ekran", title_cancel="Chiqish").add_to(fmap)\n    folium.LayerControl(collapsed=False).add_to(fmap)\n\n    figure = folium.Figure(height=height)\n    fmap.add_to(figure)\n    return figure._repr_html_()\n\n\ndef region_options() -> dict[int, str]:\n    """id -> name map for region filters (0 = all)."""\n    df = read_df("SELECT id, name FROM regions ORDER BY name")\n    options = {0: "Barcha viloyatlar"}\n    options.update({int(row.id): row.name for row in df.itertuples()})\n    return options\n',
    'irrigation': '"""Irrigation module: water usage analytics."""\n',
    'irrigation.service': '"""Irrigation analytics: usage by region/crop/method, efficiency metrics."""\nfrom __future__ import annotations\n\nimport pandas as pd\n\nfrom core.cache import cached\nfrom database.engine import read_df\n\n\n@cached(ttl=120)\ndef usage_by_region(year: int) -> pd.DataFrame:\n    """Total water (million m³) and irrigated area per region."""\n    return read_df(\n        "SELECT r.name AS region,"\n        " ROUND(SUM(i.water_m3)/1000000.0, 2) AS water_mln_m3,"\n        " ROUND(SUM(DISTINCT f.area_ha), 0) AS area"\n        " FROM irrigation_records i"\n        " JOIN fields f ON f.id = i.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE strftime(\'%Y\', i.date) = :y"\n        " GROUP BY r.name ORDER BY water_mln_m3 DESC", {"y": str(year)},\n    )\n\n\n@cached(ttl=120)\ndef usage_by_method(year: int) -> pd.DataFrame:\n    """Water split by irrigation method (drip vs furrow vs sprinkler...)."""\n    return read_df(\n        "SELECT method, ROUND(SUM(water_m3)/1000000.0, 2) AS water_mln_m3,"\n        " COUNT(*) AS events"\n        " FROM irrigation_records WHERE strftime(\'%Y\', date) = :y"\n        " GROUP BY method ORDER BY water_mln_m3 DESC", {"y": str(year)},\n    )\n\n\n@cached(ttl=120)\ndef monthly_usage(year: int) -> pd.DataFrame:\n    """Monthly water usage profile."""\n    return read_df(\n        "SELECT CAST(strftime(\'%m\', date) AS INTEGER) AS month,"\n        " ROUND(SUM(water_m3)/1000000.0, 2) AS water_mln_m3"\n        " FROM irrigation_records WHERE strftime(\'%Y\', date) = :y"\n        " GROUP BY month ORDER BY month", {"y": str(year)},\n    )\n\n\n@cached(ttl=120)\ndef efficiency_by_crop(year: int) -> pd.DataFrame:\n    """Water productivity: m³ of water per tonne of produce, by crop."""\n    df = read_df(\n        "SELECT c.name AS crop, SUM(y.production_t) AS production,"\n        " SUM(iw.water) AS water_m3"\n        " FROM yield_records y"\n        " JOIN crops c ON c.id = y.crop_id"\n        " JOIN (SELECT field_id, CAST(strftime(\'%Y\', date) AS INTEGER) AS yr,"\n        "        SUM(water_m3) AS water FROM irrigation_records"\n        "        GROUP BY field_id, yr) iw"\n        "   ON iw.field_id = y.field_id AND iw.yr = y.year"\n        " WHERE y.year = :y GROUP BY c.name", {"y": year},\n    )\n    if df.empty:\n        return df\n    df["m3_per_tonne"] = (df["water_m3"] / df["production"].clip(lower=0.1)).round(0)\n    return df.sort_values("m3_per_tonne")\n',
    'market': '"""Market module: crop prices, trends, imports."""\n',
    'market.service': '"""Market price analytics and manual/API data entry."""\nfrom __future__ import annotations\n\nfrom datetime import date, timedelta\n\nimport pandas as pd\n\nfrom analytics.timeseries import linear_forecast, percent_change\nfrom core.cache import cached\nfrom database.engine import read_df, session_scope\nfrom database.models import MarketPrice\n\n\n@cached(ttl=120)\ndef latest_prices() -> pd.DataFrame:\n    """Latest price per crop with 30-day change percentage."""\n    df = read_df(\n        "SELECT c.name AS crop, m.price_per_kg, m.date, m.market_name"\n        " FROM market_prices m JOIN crops c ON c.id = m.crop_id"\n        " ORDER BY m.date"\n    )\n    if df.empty:\n        return df\n    rows = []\n    for crop, group in df.groupby("crop"):\n        group = group.sort_values("date")\n        latest = group.iloc[-1]\n        month_ago = group[group.date <= str(date.today() - timedelta(days=30))]\n        base = float(month_ago.iloc[-1]["price_per_kg"]) if not month_ago.empty else float(latest["price_per_kg"])\n        rows.append({\n            "crop": crop,\n            "price": round(float(latest["price_per_kg"]), 0),\n            "date": str(latest["date"]),\n            "market": latest["market_name"],\n            "change_30d": percent_change(base, float(latest["price_per_kg"])),\n        })\n    return pd.DataFrame(rows).sort_values("crop").reset_index(drop=True)\n\n\ndef price_history(crop_id: int, days: int = 730) -> pd.DataFrame:\n    """Price series for one crop."""\n    since = (date.today() - timedelta(days=days)).isoformat()\n    return read_df(\n        "SELECT date, price_per_kg FROM market_prices"\n        " WHERE crop_id = :c AND date >= :s ORDER BY date",\n        {"c": crop_id, "s": since},\n    )\n\n\ndef price_forecast(crop_id: int, periods: int = 12) -> dict[str, list]:\n    """Weekly price forecast with confidence band."""\n    history = price_history(crop_id, days=365)\n    values = history["price_per_kg"].tolist()\n    forecast, lower, upper = linear_forecast(values, periods)\n    return {"history": values[-26:], "forecast": forecast,\n            "lower": lower, "upper": upper}\n\n\ndef add_price(crop_id: int, price: float, market_name: str = "Qo\'lda kiritilgan",\n              day: date | None = None) -> None:\n    """Manual price entry from the UI or API."""\n    with session_scope() as session:\n        session.add(MarketPrice(\n            crop_id=crop_id, date=day or date.today(),\n            price_per_kg=price, market_name=market_name, source="manual",\n        ))\n    latest_prices.cache.clear()  # type: ignore[attr-defined]\n\n\ndef crop_options() -> dict[int, str]:\n    """id -> name mapping for select widgets."""\n    df = read_df("SELECT id, name FROM crops ORDER BY name")\n    return {int(row.id): row.name for row in df.itertuples()}\n',
    'ml': '"""Machine-learning services: yield, disease, water need, crop recommendation."""\n',
    'ml.service': '"""ML model lifecycle: training frames from the DB, persistence, prediction.\n\nBase models use scikit-learn (always available). When XGBoost / LightGBM /\nCatBoost are installed the trainer also evaluates them and keeps whichever\nscores best on a hold-out split — fully automatic, no configuration needed.\n"""\nfrom __future__ import annotations\n\nimport json\nimport logging\nimport pickle\nfrom datetime import datetime\nfrom typing import Any\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.ensemble import (\n    GradientBoostingClassifier, RandomForestClassifier, RandomForestRegressor,\n)\nfrom sklearn.metrics import accuracy_score, r2_score\nfrom sklearn.model_selection import train_test_split\n\nfrom config import settings\nfrom core.optional import try_import\nfrom database.engine import read_df\n\nlog = logging.getLogger(__name__)\n\nMODEL_FILES = {\n    "yield": settings.MODELS_DIR / "yield_model.pkl",\n    "disease": settings.MODELS_DIR / "disease_model.pkl",\n    "water": settings.MODELS_DIR / "water_model.pkl",\n    "crop": settings.MODELS_DIR / "crop_recommender.pkl",\n}\nMETRICS_FILE = settings.MODELS_DIR / "metrics.json"\n\nYIELD_FEATURES = ["crop_id", "region_id", "area_ha", "precip", "t_avg",\n                  "irrigation_mm", "water_need_mm", "fertility"]\nDISEASE_FEATURES = ["humidity", "t_avg", "precip", "ndvi"]\nWATER_FEATURES = ["water_need_mm", "precip", "t_avg", "area_ha"]\nCROP_FEATURES = ["region_id", "precip", "t_avg", "fertility"]\n\n_loaded: dict[str, Any] = {}\n\n\n# --------------------------------------------------------------------------\n# Training frames\n# --------------------------------------------------------------------------\ndef _yield_frame() -> pd.DataFrame:\n    df = read_df(\n        "SELECT y.yield_t_ha, y.area_ha, y.year, y.crop_id, c.water_need_mm,"\n        " r.id AS region_id, r.fertility, d.id AS district_id, y.field_id"\n        " FROM yield_records y"\n        " JOIN crops c ON c.id = y.crop_id"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n    )\n    weather = read_df(\n        "SELECT district_id, CAST(strftime(\'%Y\', date) AS INTEGER) AS year,"\n        " SUM(precipitation_mm) AS precip, AVG((t_min+t_max)/2) AS t_avg"\n        " FROM weather_records"\n        " WHERE CAST(strftime(\'%m\', date) AS INTEGER) BETWEEN 4 AND 9"\n        " GROUP BY district_id, year"\n    )\n    irrigation = read_df(\n        "SELECT field_id, CAST(strftime(\'%Y\', date) AS INTEGER) AS year,"\n        " SUM(water_m3) AS water_m3"\n        " FROM irrigation_records GROUP BY field_id, year"\n    )\n    df = df.merge(weather, on=["district_id", "year"], how="left")\n    df = df.merge(irrigation, on=["field_id", "year"], how="left")\n    df["irrigation_mm"] = df["water_m3"].fillna(0) / (df["area_ha"] * 10).clip(lower=0.1)\n    return df.dropna(subset=["precip", "t_avg"])\n\n\ndef _disease_frame() -> pd.DataFrame:\n    """Synthetic agronomy labels: fungal risk grows with humidity in 18–28 °C."""\n    df = read_df(\n        "SELECT w.district_id, CAST(strftime(\'%Y\', w.date) AS INTEGER) AS year,"\n        " CAST(strftime(\'%m\', w.date) AS INTEGER) AS month,"\n        " AVG(w.humidity) AS humidity, AVG((w.t_min+w.t_max)/2) AS t_avg,"\n        " SUM(w.precipitation_mm) AS precip"\n        " FROM weather_records w GROUP BY w.district_id, year, month"\n    )\n    rng = np.random.default_rng(7)\n    df["ndvi"] = np.clip(0.2 + 0.5 * np.sin((df["month"] - 2) / 12 * np.pi)\n                         + rng.normal(0, 0.05, len(df)), 0.05, 0.9)\n    temp_window = ((df["t_avg"] > 18) & (df["t_avg"] < 28)).astype(float)\n    risk_score = 1 / (1 + np.exp(-(0.09 * (df["humidity"] - 62)))) * (0.4 + 0.6 * temp_window)\n    df["label"] = (rng.random(len(df)) < risk_score).astype(int)\n    return df\n\n\ndef _water_frame() -> pd.DataFrame:\n    """Water requirement rows: deficit(m3/ha) = (need − effective precip) × 10."""\n    crops = read_df("SELECT id AS crop_id, water_need_mm FROM crops")\n    weather = read_df(\n        "SELECT district_id, CAST(strftime(\'%Y\', date) AS INTEGER) AS year,"\n        " SUM(precipitation_mm) AS precip, AVG((t_min+t_max)/2) AS t_avg"\n        " FROM weather_records"\n        " WHERE CAST(strftime(\'%m\', date) AS INTEGER) BETWEEN 4 AND 9"\n        " GROUP BY district_id, year"\n    )\n    rng = np.random.default_rng(11)\n    rows = []\n    for crop in crops.itertuples():\n        sample = weather.sample(min(60, len(weather)), random_state=int(crop.crop_id))\n        for w in sample.itertuples():\n            heat_extra = max(0.0, w.t_avg - 24) * 12\n            deficit = max(0.0, crop.water_need_mm + heat_extra - 0.7 * w.precip) * 10\n            rows.append({\n                "water_need_mm": crop.water_need_mm, "precip": w.precip,\n                "t_avg": w.t_avg, "area_ha": float(rng.uniform(5, 120)),\n                "target_m3_ha": deficit * float(1 + rng.normal(0, 0.05)),\n            })\n    return pd.DataFrame(rows)\n\n\ndef _crop_frame() -> pd.DataFrame:\n    """Label = historically most profitable crop per district-year."""\n    df = read_df(\n        "SELECT y.crop_id, y.year, d.id AS district_id, r.id AS region_id,"\n        " r.fertility, AVG(y.yield_t_ha) AS avg_yield, c.base_price_per_kg,"\n        " c.cost_per_ha"\n        " FROM yield_records y"\n        " JOIN crops c ON c.id = y.crop_id"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " GROUP BY d.id, y.year, y.crop_id"\n    )\n    weather = read_df(\n        "SELECT district_id, CAST(strftime(\'%Y\', date) AS INTEGER) AS year,"\n        " SUM(precipitation_mm) AS precip, AVG((t_min+t_max)/2) AS t_avg"\n        " FROM weather_records"\n        " WHERE CAST(strftime(\'%m\', date) AS INTEGER) BETWEEN 4 AND 9"\n        " GROUP BY district_id, year"\n    )\n    df["profit_ha"] = df["avg_yield"] * 1000 * df["base_price_per_kg"] - df["cost_per_ha"]\n    best = df.loc[df.groupby(["district_id", "year"])["profit_ha"].idxmax()]\n    return best.merge(weather, on=["district_id", "year"], how="inner")\n\n\n# --------------------------------------------------------------------------\n# Optional gradient-boosting challengers\n# --------------------------------------------------------------------------\ndef _challenger_regressors() -> list[tuple[str, Any]]:\n    challengers: list[tuple[str, Any]] = []\n    xgb = try_import("xgboost")\n    if xgb is not None:\n        challengers.append(("xgboost", xgb.XGBRegressor(\n            n_estimators=200, max_depth=6, learning_rate=0.08, verbosity=0)))\n    lgb = try_import("lightgbm")\n    if lgb is not None:\n        challengers.append(("lightgbm", lgb.LGBMRegressor(\n            n_estimators=200, verbose=-1)))\n    cat = try_import("catboost")\n    if cat is not None:\n        challengers.append(("catboost", cat.CatBoostRegressor(\n            iterations=200, verbose=False)))\n    return challengers\n\n\n# --------------------------------------------------------------------------\n# Training\n# --------------------------------------------------------------------------\ndef train_all(force: bool = False) -> dict[str, Any]:\n    """Train (or load) every model; persists pickles + metrics.json."""\n    settings.ensure_directories()\n    if not force and all(path.exists() for path in MODEL_FILES.values()):\n        return model_status()\n\n    metrics: dict[str, Any] = {"trained_at": datetime.now().isoformat(timespec="seconds")}\n\n    # 1) Yield regression — champion/challenger selection.\n    frame = _yield_frame()\n    x_train, x_test, y_train, y_test = train_test_split(\n        frame[YIELD_FEATURES], frame["yield_t_ha"], test_size=0.2, random_state=42)\n    champion_name = "random_forest"\n    champion = RandomForestRegressor(n_estimators=180, random_state=42, n_jobs=-1)\n    champion.fit(x_train, y_train)\n    best_r2 = r2_score(y_test, champion.predict(x_test))\n    for name, challenger in _challenger_regressors():\n        try:\n            challenger.fit(x_train, y_train)\n            score = r2_score(y_test, challenger.predict(x_test))\n            if score > best_r2:\n                champion, champion_name, best_r2 = challenger, name, score\n        except Exception as exc:  # noqa: BLE001\n            log.warning("Challenger %s failed: %s", name, exc)\n    _save("yield", champion)\n    metrics["yield"] = {"algorithm": champion_name, "r2": round(float(best_r2), 3),\n                        "rows": len(frame)}\n\n    # 2) Disease risk classification.\n    disease = _disease_frame()\n    x_train, x_test, y_train, y_test = train_test_split(\n        disease[DISEASE_FEATURES], disease["label"], test_size=0.2, random_state=42)\n    clf = GradientBoostingClassifier(random_state=42)\n    clf.fit(x_train, y_train)\n    metrics["disease"] = {\n        "algorithm": "gradient_boosting",\n        "accuracy": round(float(accuracy_score(y_test, clf.predict(x_test))), 3),\n        "rows": len(disease),\n    }\n    _save("disease", clf)\n\n    # 3) Water need regression.\n    water = _water_frame()\n    x_train, x_test, y_train, y_test = train_test_split(\n        water[WATER_FEATURES], water["target_m3_ha"], test_size=0.2, random_state=42)\n    reg = RandomForestRegressor(n_estimators=120, random_state=42, n_jobs=-1)\n    reg.fit(x_train, y_train)\n    metrics["water"] = {\n        "algorithm": "random_forest",\n        "r2": round(float(r2_score(y_test, reg.predict(x_test))), 3),\n        "rows": len(water),\n    }\n    _save("water", reg)\n\n    # 4) Crop recommendation classification.\n    crop = _crop_frame()\n    recommender = RandomForestClassifier(n_estimators=150, random_state=42, n_jobs=-1)\n    recommender.fit(crop[CROP_FEATURES], crop["crop_id"])\n    metrics["crop"] = {\n        "algorithm": "random_forest",\n        "accuracy": round(float(recommender.score(crop[CROP_FEATURES], crop["crop_id"])), 3),\n        "rows": len(crop),\n    }\n    _save("crop", recommender)\n\n    METRICS_FILE.write_text(json.dumps(metrics, indent=2), encoding="utf-8")\n    _loaded.clear()\n    log.info("ML modellari o\'qitildi: yield R²=%.3f (%s)", best_r2, champion_name)\n    return metrics\n\n\ndef _save(name: str, model: Any) -> None:\n    with open(MODEL_FILES[name], "wb") as fh:\n        pickle.dump(model, fh)\n\n\ndef _load(name: str) -> Any:\n    if name not in _loaded:\n        if not MODEL_FILES[name].exists():\n            train_all()\n        with open(MODEL_FILES[name], "rb") as fh:\n            _loaded[name] = pickle.load(fh)  # noqa: S301 - own artifacts\n    return _loaded[name]\n\n\ndef model_status() -> dict[str, Any]:\n    """Metrics of the last training run (trains first if never run)."""\n    if not METRICS_FILE.exists():\n        return train_all(force=True)\n    return json.loads(METRICS_FILE.read_text(encoding="utf-8"))\n\n\n# --------------------------------------------------------------------------\n# Prediction API\n# --------------------------------------------------------------------------\ndef predict_yield(crop_id: int, region_id: int, area_ha: float, precip: float,\n                  t_avg: float, irrigation_mm: float, water_need_mm: float,\n                  fertility: float) -> float:\n    """Predicted yield in t/ha for the given agronomic scenario."""\n    frame = pd.DataFrame([{\n        "crop_id": crop_id, "region_id": region_id, "area_ha": area_ha,\n        "precip": precip, "t_avg": t_avg, "irrigation_mm": irrigation_mm,\n        "water_need_mm": water_need_mm, "fertility": fertility,\n    }])[YIELD_FEATURES]\n    return round(float(_load("yield").predict(frame)[0]), 2)\n\n\ndef predict_disease_risk(humidity: float, t_avg: float, precip: float,\n                         ndvi: float) -> float:\n    """Probability (0..1) of fungal disease pressure."""\n    frame = pd.DataFrame([{"humidity": humidity, "t_avg": t_avg,\n                           "precip": precip, "ndvi": ndvi}])[DISEASE_FEATURES]\n    return round(float(_load("disease").predict_proba(frame)[0][1]), 3)\n\n\ndef predict_water_need(water_need_mm: float, precip: float, t_avg: float,\n                       area_ha: float) -> float:\n    """Predicted irrigation requirement in m³/ha for the season."""\n    frame = pd.DataFrame([{"water_need_mm": water_need_mm, "precip": precip,\n                           "t_avg": t_avg, "area_ha": area_ha}])[WATER_FEATURES]\n    return round(float(_load("water").predict(frame)[0]), 0)\n\n\ndef recommend_crops(region_id: int, precip: float, t_avg: float,\n                    fertility: float, top_n: int = 3) -> list[dict[str, Any]]:\n    """Top-N recommended crops with model confidence."""\n    model = _load("crop")\n    frame = pd.DataFrame([{"region_id": region_id, "precip": precip,\n                           "t_avg": t_avg, "fertility": fertility}])[CROP_FEATURES]\n    probabilities = model.predict_proba(frame)[0]\n    crops = read_df("SELECT id, name FROM crops").set_index("id")["name"].to_dict()\n    ranked = sorted(zip(model.classes_, probabilities), key=lambda p: -p[1])[:top_n]\n    return [\n        {"crop": crops.get(int(crop_id), f"Ekin #{crop_id}"),\n         "confidence": round(float(prob) * 100, 1)}\n        for crop_id, prob in ranked\n    ]\n',
    'plugin_templates': '"""Embedded plugin templates written to plugins/ on first run."""\nSOIL_ANALYSIS = \'"""Namuna plagin: Tuproq tahlili.\\n\\nPlagin kontrakti: PLUGIN metadata + register() funksiyasi. Ushbu fayl\\n``plugins/`` papkasiga tashlangan har qanday modul uchun shablon bo\\\'lib\\nxizmat qiladi (IoT sensorlar, ERP, chorvachilik va h.k.).\\n"""\\nfrom __future__ import annotations\\n\\nPLUGIN = {"name": "Tuproq tahlili", "icon": "grass", "route": "/plugin/soil"}\\n\\nSUITABILITY = {\\n    "bo\\\'z tuproq": ("Bug\\\'doy, paxta, sabzavotlar uchun qulay", 0.85),\\n    "o\\\'tloq tuproq": ("Sholi va ozuqa ekinlari uchun juda mos", 0.9),\\n    "sho\\\'rlangan tuproq": ("Meliorativ ishlov talab etiladi; arpa bardoshli", 0.55),\\n    "qumloq tuproq": ("Poliz ekinlari uchun mos; tez-tez sug\\\'orish kerak", 0.65),\\n    "gilli tuproq": ("Namlikni yaxshi saqlaydi; drenaj nazorati zarur", 0.75),\\n}\\n\\n\\ndef register() -> None:\\n    from nicegui import ui\\n\\n    from app import charts, layout\\n    from database.engine import read_df\\n\\n    @ui.page(PLUGIN["route"])\\n    def soil_page() -> None:\\n        user = layout.require_login()\\n        if user is None:\\n            return\\n        with layout.shell(user, "Plagin: Tuproq tahlili"):\\n            df = read_df(\\n                "SELECT soil_type AS tuproq, COUNT(*) AS dalalar,"\\n                " ROUND(SUM(area_ha),0) AS maydon_ga,"\\n                " ROUND(AVG((SELECT AVG(y.yield_t_ha) FROM yield_records y"\\n                "            WHERE y.field_id = f.id)),2) AS ortacha_hosil"\\n                " FROM fields f GROUP BY soil_type ORDER BY maydon_ga DESC")\\n            with ui.grid(columns=2).classes("w-full gap-4"):\\n                layout.chart(charts.pie_chart(\\n                    "Tuproq turlari bo\\\'yicha maydon (ga)",\\n                    [(row.tuproq, row.maydon_ga) for row in df.itertuples()]))\\n                with ui.card().classes("chart-card"):\\n                    layout.df_table(df, title="Tuproq turlari statistikasi")\\n            with ui.card().classes("chart-card p-4 gap-2 w-full"):\\n                ui.label("Agronomik baholash").classes("section-title")\\n                for soil, (note, score) in SUITABILITY.items():\\n                    with ui.row().classes("items-center gap-3 w-full"):\\n                        ui.label(soil).classes("font-medium w-44")\\n                        ui.linear_progress(score, show_value=False) \\\\\\n                            .classes("w-40")\\n                        ui.label(note).classes("text-sm opacity-75")\\n\'\n',
    'reports': '"""Reporting: PDF, Excel, CSV, Word, HTML, JSON, GeoJSON, PNG exports."""\n',
    'reports.exporter': '"""Report generation and data export in every supported format."""\nfrom __future__ import annotations\n\nimport json\nimport logging\nfrom datetime import datetime\nfrom pathlib import Path\n\nimport pandas as pd\n\nfrom analytics import kpi as kpi_module\nfrom config import settings\nfrom core.optional import try_import\nfrom core.security import audit\nfrom database.engine import read_df\n\nlog = logging.getLogger(__name__)\n\n\ndef _stamp(name: str, extension: str) -> Path:\n    settings.ensure_directories()\n    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n    return settings.EXPORT_DIR / f"{name}_{timestamp}.{extension}"\n\n\ndef _latin(text: str) -> str:\n    """Sanitise Uzbek-latin text for PDF core fonts (latin-1 only)."""\n    replacements = {"ʻ": "\'", "ʼ": "\'", "‘": "\'", "’": "\'", "“": \'"\', "”": \'"\',\n                    "–": "-", "—": "-", "²": "2", "³": "3"}\n    for source, target in replacements.items():\n        text = text.replace(source, target)\n    return text.encode("latin-1", errors="replace").decode("latin-1")\n\n\n# --------------------------------------------------------------------------\n# DataFrame exports\n# --------------------------------------------------------------------------\ndef export_dataframe(df: pd.DataFrame, name: str, fmt: str,\n                     username: str = "") -> Path:\n    """Export any table as csv / xlsx / json."""\n    fmt = fmt.lower()\n    if fmt == "csv":\n        path = _stamp(name, "csv")\n        df.to_csv(path, index=False, encoding="utf-8-sig")\n    elif fmt == "xlsx":\n        path = _stamp(name, "xlsx")\n        df.to_excel(path, index=False, engine="openpyxl")\n    elif fmt == "json":\n        path = _stamp(name, "json")\n        path.write_text(df.to_json(orient="records", force_ascii=False, indent=2),\n                        encoding="utf-8")\n    else:\n        raise ValueError(f"Noma\'lum format: {fmt}")\n    audit("export", username, f"{name}.{fmt} ({len(df)} qator)")\n    return path\n\n\ndef export_fields_geojson(username: str = "") -> Path:\n    """All field polygons + attributes as a GeoJSON FeatureCollection."""\n    df = read_df(\n        "SELECT f.name, f.area_ha, f.soil_type, f.geometry_geojson,"\n        " fa.name AS farm, r.name AS region"\n        " FROM fields f"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n    )\n    features = []\n    for row in df.itertuples():\n        try:\n            geometry = json.loads(row.geometry_geojson)\n        except (json.JSONDecodeError, TypeError):\n            continue\n        features.append({\n            "type": "Feature", "geometry": geometry,\n            "properties": {"name": row.name, "area_ha": row.area_ha,\n                           "soil": row.soil_type, "farm": row.farm,\n                           "region": row.region},\n        })\n    path = _stamp("dalalar", "geojson")\n    path.write_text(json.dumps({"type": "FeatureCollection", "features": features},\n                               ensure_ascii=False), encoding="utf-8")\n    audit("export", username, f"GeoJSON ({len(features)} poligon)")\n    return path\n\n\n# --------------------------------------------------------------------------\n# KPI summary reports\n# --------------------------------------------------------------------------\ndef _report_tables(year: int) -> dict[str, pd.DataFrame]:\n    return {\n        "Viloyatlar bo\'yicha hosildorlik": kpi_module.yield_by_region(year),\n        "Ekinlar taqsimoti": kpi_module.crop_distribution(year).head(12),\n        "Eng yaxshi xo\'jaliklar": kpi_module.top_farms(year),\n    }\n\n\ndef kpi_report_pdf(year: int | None = None, username: str = "") -> Path:\n    """Multi-section PDF summary report (fpdf2, no external binaries)."""\n    from fpdf import FPDF\n\n    year = year or kpi_module.latest_year()\n    kpi = kpi_module.compute_kpi(year)\n    pdf = FPDF()\n    pdf.set_auto_page_break(auto=True, margin=15)\n    pdf.add_page()\n    pdf.set_font("helvetica", "B", 16)\n    pdf.cell(0, 10, _latin(f"AgroVision — {year}-yil yakuniy hisoboti"),\n             new_x="LMARGIN", new_y="NEXT")\n    pdf.set_font("helvetica", "", 9)\n    pdf.cell(0, 6, _latin(f"Yaratildi: {datetime.now():%Y-%m-%d %H:%M}"),\n             new_x="LMARGIN", new_y="NEXT")\n    pdf.ln(4)\n\n    pdf.set_font("helvetica", "B", 12)\n    pdf.cell(0, 8, _latin("Asosiy ko\'rsatkichlar"), new_x="LMARGIN", new_y="NEXT")\n    pdf.set_font("helvetica", "", 10)\n    for label, value in [\n        ("Umumiy yer maydoni", f"{kpi.total_area_ha:,.0f} ga"),\n        ("Fermerlar / xo\'jaliklar / dalalar",\n         f"{kpi.farmers} / {kpi.farms} / {kpi.fields}"),\n        ("O\'rtacha hosildorlik", f"{kpi.avg_yield_t_ha} t/ga"),\n        ("Jami ishlab chiqarish", f"{kpi.production_t:,.0f} t"),\n        ("Daromad", f"{kpi.income / 1e9:,.2f} mlrd so\'m"),\n        ("Xarajat", f"{kpi.expense / 1e9:,.2f} mlrd so\'m"),\n        ("Sof foyda (ROI)", f"{kpi.profit / 1e9:,.2f} mlrd so\'m ({kpi.roi_percent}%)"),\n        ("O\'rtacha NDVI", f"{kpi.avg_ndvi}"),\n        ("Sug\'orish suvi", f"{kpi.water_million_m3} mln m3"),\n    ]:\n        pdf.cell(90, 7, _latin(label))\n        pdf.cell(0, 7, _latin(str(value)), new_x="LMARGIN", new_y="NEXT")\n\n    for title, table in _report_tables(year).items():\n        pdf.ln(4)\n        pdf.set_font("helvetica", "B", 12)\n        pdf.cell(0, 8, _latin(title), new_x="LMARGIN", new_y="NEXT")\n        pdf.set_font("helvetica", "B", 8)\n        columns = list(table.columns)\n        width = max(24, int(190 / max(1, len(columns))))\n        for column in columns:\n            pdf.cell(width, 6, _latin(str(column))[:22], border=1)\n        pdf.ln()\n        pdf.set_font("helvetica", "", 8)\n        for _, row in table.head(15).iterrows():\n            for column in columns:\n                value = row[column]\n                text = f"{value:,.0f}" if isinstance(value, float) and abs(value) > 100 \\\n                    else str(value)\n                pdf.cell(width, 6, _latin(text)[:22], border=1)\n            pdf.ln()\n\n    path = _stamp(f"hisobot_{year}", "pdf")\n    pdf.output(str(path))\n    audit("export", username, f"PDF hisobot {year}")\n    return path\n\n\ndef kpi_report_html(year: int | None = None, username: str = "") -> Path:\n    """Standalone HTML report (also serves as the printable dashboard snapshot)."""\n    year = year or kpi_module.latest_year()\n    kpi = kpi_module.compute_kpi(year)\n    sections = "".join(\n        f"<h2>{title}</h2>{table.to_html(index=False, border=0)}"\n        for title, table in _report_tables(year).items()\n    )\n    html = f"""<!DOCTYPE html><html lang="uz"><head><meta charset="utf-8">\n<title>AgroVision hisobot {year}</title>\n<style>\n body{{font-family:Segoe UI,Arial,sans-serif;margin:32px;color:#1b2a1b}}\n h1{{color:#2e7d32}} h2{{color:#33691e;border-bottom:2px solid #aed581;padding-bottom:4px}}\n table{{border-collapse:collapse;width:100%;margin:12px 0;font-size:14px}}\n td,th{{padding:6px 10px;border-bottom:1px solid #dcedc8;text-align:left}}\n th{{background:#f1f8e9}}\n .kpi{{display:inline-block;background:#f1f8e9;border-radius:12px;padding:14px 22px;\n       margin:6px;min-width:160px}}\n .kpi b{{display:block;font-size:22px;color:#2e7d32}}\n</style></head><body>\n<h1>AgroVision — {year}-yil yakuniy hisoboti</h1>\n<p>Yaratildi: {datetime.now():%Y-%m-%d %H:%M}</p>\n<div>\n <div class="kpi"><b>{kpi.total_area_ha:,.0f} ga</b>Yer maydoni</div>\n <div class="kpi"><b>{kpi.avg_yield_t_ha} t/ga</b>O\'rtacha hosildorlik</div>\n <div class="kpi"><b>{kpi.production_t:,.0f} t</b>Ishlab chiqarish</div>\n <div class="kpi"><b>{kpi.profit / 1e9:,.1f} mlrd</b>Sof foyda (so\'m)</div>\n <div class="kpi"><b>{kpi.roi_percent}%</b>ROI</div>\n <div class="kpi"><b>{kpi.avg_ndvi}</b>O\'rtacha NDVI</div>\n</div>\n{sections}\n</body></html>"""\n    path = _stamp(f"hisobot_{year}", "html")\n    path.write_text(html, encoding="utf-8")\n    audit("export", username, f"HTML hisobot {year}")\n    return path\n\n\ndef kpi_report_word(year: int | None = None, username: str = "") -> Path | None:\n    """Word (.docx) report when python-docx is installed; else None."""\n    if try_import("docx") is None:\n        return None\n    from docx import Document\n\n    year = year or kpi_module.latest_year()\n    kpi = kpi_module.compute_kpi(year)\n    document = Document()\n    document.add_heading(f"AgroVision — {year}-yil yakuniy hisoboti", level=0)\n    document.add_paragraph(f"Yaratildi: {datetime.now():%Y-%m-%d %H:%M}")\n    document.add_heading("Asosiy ko\'rsatkichlar", level=1)\n    for line in [\n        f"Yer maydoni: {kpi.total_area_ha:,.0f} ga",\n        f"O\'rtacha hosildorlik: {kpi.avg_yield_t_ha} t/ga",\n        f"Ishlab chiqarish: {kpi.production_t:,.0f} t",\n        f"Sof foyda: {kpi.profit / 1e9:,.2f} mlrd so\'m (ROI {kpi.roi_percent}%)",\n    ]:\n        document.add_paragraph(line, style="List Bullet")\n    for title, table in _report_tables(year).items():\n        document.add_heading(title, level=1)\n        word_table = document.add_table(rows=1, cols=len(table.columns))\n        word_table.style = "Light Grid Accent 3"\n        for i, column in enumerate(table.columns):\n            word_table.rows[0].cells[i].text = str(column)\n        for _, row in table.head(15).iterrows():\n            cells = word_table.add_row().cells\n            for i, column in enumerate(table.columns):\n                cells[i].text = str(row[column])\n    path = _stamp(f"hisobot_{year}", "docx")\n    document.save(str(path))\n    audit("export", username, f"Word hisobot {year}")\n    return path\n\n\ndef dashboard_png(year: int | None = None, username: str = "") -> Path | None:\n    """Dashboard snapshot as PNG (matplotlib when available; else None)."""\n    if try_import("matplotlib") is None:\n        return None\n    import matplotlib\n\n    matplotlib.use("Agg")\n    import matplotlib.pyplot as plt\n\n    year = year or kpi_module.latest_year()\n    trend = kpi_module.yield_trend()\n    regions = kpi_module.yield_by_region(year)\n    crops = kpi_module.crop_distribution(year).head(8)\n\n    figure, axes = plt.subplots(2, 2, figsize=(14, 9))\n    figure.suptitle(f"AgroVision — {year}-yil ko\'rsatkichlari", fontsize=15)\n\n    axes[0][0].plot(trend["year"], trend["avg_yield"], marker="o", color="#2e7d32")\n    axes[0][0].set_title("Hosildorlik trendi (t/ga)")\n    axes[0][0].grid(alpha=0.3)\n\n    axes[0][1].barh(regions["region"], regions["production"], color="#66bb6a")\n    axes[0][1].set_title("Viloyatlar — ishlab chiqarish (t)")\n    axes[0][1].invert_yaxis()\n\n    axes[1][0].pie(crops["area"], labels=crops["crop"], autopct="%1.0f%%",\n                   textprops={"fontsize": 8})\n    axes[1][0].set_title("Ekin maydonlari taqsimoti")\n\n    axes[1][1].bar(trend["year"].astype(str), trend["production"], color="#9ccc65")\n    axes[1][1].set_title("Yillik ishlab chiqarish (t)")\n\n    figure.tight_layout(rect=(0, 0, 1, 0.96))\n    path = _stamp(f"dashboard_{year}", "png")\n    figure.savefig(path, dpi=130)\n    plt.close(figure)\n    audit("export", username, f"PNG snapshot {year}")\n    return path\n\n\nDATASETS: dict[str, str] = {\n    "Hosildorlik yozuvlari": (\n        "SELECT y.year, r.name AS region, d.name AS district, fa.name AS farm,"\n        " f.name AS field, c.name AS crop, y.area_ha, y.yield_t_ha, y.production_t"\n        " FROM yield_records y"\n        " JOIN crops c ON c.id = y.crop_id"\n        " JOIN fields f ON f.id = y.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id ORDER BY y.year DESC"\n    ),\n    "Bozor narxlari": (\n        "SELECT m.date, c.name AS crop, m.price_per_kg, m.market_name, m.source"\n        " FROM market_prices m JOIN crops c ON c.id = m.crop_id ORDER BY m.date DESC"\n    ),\n    "Ob-havo yozuvlari": (\n        "SELECT w.date, d.name AS district, w.t_min, w.t_max,"\n        " w.precipitation_mm, w.humidity, w.source"\n        " FROM weather_records w JOIN districts d ON d.id = w.district_id"\n        " ORDER BY w.date DESC LIMIT 20000"\n    ),\n    "Moliya yozuvlari": (\n        "SELECT fr.year, fa.name AS farm, fr.category, fr.amount, fr.note"\n        " FROM finance_records fr JOIN farms fa ON fa.id = fr.farm_id"\n        " ORDER BY fr.year DESC"\n    ),\n    "Sug\'orish yozuvlari": (\n        "SELECT i.date, f.name AS field, i.water_m3, i.method"\n        " FROM irrigation_records i JOIN fields f ON f.id = i.field_id"\n        " ORDER BY i.date DESC LIMIT 20000"\n    ),\n    "NDVI indekslari": (\n        "SELECT s.date, f.name AS field, s.ndvi, s.evi, s.source"\n        " FROM satellite_indices s JOIN fields f ON f.id = s.field_id"\n        " ORDER BY s.date DESC LIMIT 20000"\n    ),\n}\n\n\ndef dataset_frame(name: str) -> pd.DataFrame:\n    """Load one of the named export datasets."""\n    return read_df(DATASETS[name])\n',
    'run': '"""AgroVision — Qishloq xo\'jaligi analitik platformasi. Kirish nuqtasi.\n\nIshga tushirish:  python run.py\nQo\'shimcha:       python run.py --selfcheck   (tizim salomatligi tekshiruvi)\n                  python run.py --port 8090   (boshqa port)\n                  python run.py --yes         (paketlarni so\'ramasdan o\'rnatish)\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport importlib.util\nimport subprocess\nimport sys\n\nMIN_PYTHON = (3, 10)\n\n\ndef _print_banner() -> None:\n    print(r"""\n   _____                    ___    ___      _\n  |  _  |___ ___ ___ ___   |  _|  |  _|___ |_|___ ___\n  |     | . |  _| . |  _|  |  |   |  ||_ -|| | . |   |\n  |__|__|_  |_| |___|_|     \\__\\   \\__\\___||_|___|_|_|\n        |___|   AgroVision — Enterprise Agriculture Analytics\n    """)\n\n\ndef ensure_dependencies(auto_yes: bool = False) -> bool:\n    """Check required packages; offer to pip-install anything missing."""\n    from config import settings\n\n    missing = [pip_name for pip_name, module in settings.REQUIRED_PACKAGES.items()\n               if importlib.util.find_spec(module) is None]\n    if not missing:\n        return True\n\n    print("Quyidagi zarur kutubxonalar topilmadi:")\n    for name in missing:\n        print(f"  - {name}")\n    if not auto_yes:\n        answer = input("Ularni pip orqali o\'rnatishga ruxsat berasizmi? [Y/n]: ")\n        if answer.strip().lower() not in ("", "y", "yes", "ha"):\n            print("O\'rnatish bekor qilindi. Qo\'lda o\'rnating: "\n                  f"pip install {\' \'.join(missing)}")\n            return False\n    print("O\'rnatilmoqda... (bir necha daqiqa olishi mumkin)")\n    try:\n        subprocess.check_call(\n            [sys.executable, "-m", "pip", "install", *missing])\n    except subprocess.CalledProcessError as exc:\n        print(f"pip xatosi ({exc.returncode}). Qo\'lda o\'rnating: "\n              f"pip install {\' \'.join(missing)}")\n        return False\n    still_missing = [pip for pip, module in settings.REQUIRED_PACKAGES.items()\n                     if importlib.util.find_spec(module) is None]\n    if still_missing:\n        print(f"O\'rnatib bo\'lmadi: {still_missing}")\n        return False\n    print("Barcha zarur kutubxonalar tayyor.")\n    return True\n\n\ndef initialize(debug: bool = False) -> None:\n    """Installer sequence: folders, logging, database, seed, ML models."""\n    from config import settings\n    from core.logging_setup import setup_logging\n\n    settings.ensure_directories()\n    log = setup_logging(debug=debug)\n\n    from database.engine import init_db\n    from database.seed import seed_if_empty\n\n    init_db()\n    if seed_if_empty():\n        log.info("Birinchi ishga tushirish yakunlandi: demo ma\'lumotlar yaratildi.")\n\n    from ml.service import MODEL_FILES, train_all\n\n    if not all(path.exists() for path in MODEL_FILES.values()):\n        log.info("ML modellari o\'qitilmoqda (birinchi marta, ~10-30 soniya)...")\n        train_all()\n\n    _write_default_plugin()\n\n\ndef _write_default_plugin() -> None:\n    """Ship the example Soil Analysis plugin on first run (plugin system demo)."""\n    from config import settings\n\n    target = settings.PLUGINS_DIR / "soil_analysis.py"\n    if target.exists():\n        return\n    try:\n        import plugin_templates  # embedded in the monolith build\n\n        target.write_text(plugin_templates.SOIL_ANALYSIS, encoding="utf-8")\n    except ImportError:\n        # Modular layout ships the plugin file directly in plugins/.\n        pass\n\n\ndef selfcheck() -> int:\n    """Health check: every subsystem exercised end-to-end. Returns exit code."""\n    initialize()\n    checks: list[tuple[str, bool, str]] = []\n\n    def run_check(name: str, fn) -> None:\n        try:\n            detail = fn()\n            checks.append((name, True, str(detail)))\n        except Exception as exc:  # noqa: BLE001\n            checks.append((name, False, f"{type(exc).__name__}: {exc}"))\n\n    def check_db() -> str:\n        from database.engine import db_stats\n\n        stats = db_stats()\n        assert stats["users"] >= 3 and stats["fields"] >= 100\n        return f"{sum(stats.values()):,} yozuv, {len(stats)} jadval"\n\n    def check_kpi() -> str:\n        from analytics.kpi import compute_kpi\n\n        kpi = compute_kpi()\n        assert kpi.total_area_ha > 0 and kpi.production_t > 0\n        return f"{kpi.year}: {kpi.avg_yield_t_ha} t/ga, ROI {kpi.roi_percent}%"\n\n    def check_ml() -> str:\n        from ml.service import model_status, predict_yield\n\n        status = model_status()\n        value = predict_yield(1, 1, 50, 150, 24, 350, 450, 1.0)\n        assert 0 < value < 100\n        return f"yield R²={status[\'yield\'][\'r2\']}, prognoz={value} t/ga"\n\n    def check_ai() -> str:\n        from ai.engine import assistant\n\n        result = assistant.ask("Jizzaxda bug\'doy hosili nima uchun pasaydi?")\n        assert len(result["answer"]) > 40\n        return result["answer"].splitlines()[0][:80]\n\n    def check_map() -> str:\n        from gis.maps import build_map\n\n        html = build_map()\n        assert len(html) > 10_000\n        return f"xarita HTML {len(html) // 1024} KB"\n\n    def check_report() -> str:\n        from analytics.kpi import yield_trend\n        from reports.exporter import export_dataframe\n\n        path = export_dataframe(yield_trend(), "selfcheck", "csv")\n        assert path.exists()\n        path.unlink()\n        return "CSV eksport OK"\n\n    def check_security() -> str:\n        from core.security import create_token, hash_password, verify_password, verify_token\n\n        assert verify_password("test123", hash_password("test123"))\n        token = verify_token(create_token("admin", "admin"))\n        assert token and token["sub"] == "admin"\n        return "PBKDF2 + HMAC token OK"\n\n    def check_backup() -> str:\n        from database.backup import create_backup, list_backups\n\n        path = create_backup("selfcheck")\n        assert path is not None and list_backups()\n        path.unlink()\n        return "backup/restore OK"\n\n    run_check("Ma\'lumotlar bazasi", check_db)\n    run_check("KPI analitikasi", check_kpi)\n    run_check("ML modellari", check_ml)\n    run_check("AI yordamchi", check_ai)\n    run_check("GIS xarita", check_map)\n    run_check("Hisobot eksporti", check_report)\n    run_check("Xavfsizlik", check_security)\n    run_check("Zaxira nusxa", check_backup)\n\n    print("\\n=== O\'z-o\'zini tekshirish natijalari ===")\n    failed = 0\n    for name, ok, detail in checks:\n        mark = "OK " if ok else "XATO"\n        if not ok:\n            failed += 1\n        print(f"  [{mark}] {name:22s} {detail}")\n    print(f"\\nJami: {len(checks)}, muvaffaqiyatli: {len(checks) - failed}, "\n          f"xato: {failed}")\n    return 1 if failed else 0\n\n\ndef _force_utf8_console() -> None:\n    """Windows consoles often default to cp1251/cp866 — switch to UTF-8."""\n    for stream in (sys.stdout, sys.stderr):\n        try:\n            stream.reconfigure(encoding="utf-8", errors="replace")\n        except (AttributeError, ValueError):\n            pass\n\n\ndef main() -> None:\n    _force_utf8_console()\n    if sys.version_info < MIN_PYTHON:\n        print(f"Python {MIN_PYTHON[0]}.{MIN_PYTHON[1]}+ talab qilinadi "\n              f"(sizda {sys.version_info.major}.{sys.version_info.minor}).")\n        sys.exit(1)\n\n    parser = argparse.ArgumentParser(description="AgroVision platformasi")\n    parser.add_argument("--host", default=None, help="Server manzili")\n    parser.add_argument("--port", type=int, default=None, help="Server porti")\n    parser.add_argument("--no-browser", action="store_true",\n                        help="Brauzerni avtomatik ochmaslik")\n    parser.add_argument("--yes", action="store_true",\n                        help="Paketlarni so\'ramasdan o\'rnatish")\n    parser.add_argument("--debug", action="store_true", help="Debug rejimi")\n    parser.add_argument("--selfcheck", action="store_true",\n                        help="Tizim salomatligini tekshirish va chiqish")\n    args = parser.parse_args()\n\n    _print_banner()\n    if not ensure_dependencies(auto_yes=args.yes):\n        sys.exit(1)\n\n    if args.selfcheck:\n        sys.exit(selfcheck())\n\n    initialize(debug=args.debug)\n\n    from config import settings\n\n    host = args.host or settings.DEFAULT_HOST\n    port = args.port or settings.DEFAULT_PORT\n    print(f"\\n  Dashboard:  http://{host}:{port}")\n    print("  Demo login: admin / admin123\\n")\n\n    from app.main import start\n\n    start(host=host, port=port, open_browser=not args.no_browser,\n          debug=args.debug)\n\n\nif __name__ in {"__main__", "__mp_main__"}:\n    main()\n',
    'satellite': '"""Satellite & drone module: NDVI/EVI, providers, imagery processing."""\n',
    'satellite.service': '"""Satellite services with a provider chain.\n\n``GEEProvider`` activates when the ``earthengine-api`` package and service\ncredentials are configured; otherwise ``LocalProvider`` serves the NDVI/EVI\nseries stored in the database (seeded + drone-derived), so every feature is\nfully functional offline. Planet API is exposed as a plugin-style provider.\n"""\nfrom __future__ import annotations\n\nimport logging\nfrom datetime import date, timedelta\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nfrom core.cache import cached\nfrom core.optional import try_import\nfrom database.engine import get_setting, read_df, session_scope\nfrom database.models import ImportedFile, SatelliteIndex\n\nlog = logging.getLogger(__name__)\n\n\nclass LocalProvider:\n    """Offline provider backed by the satellite_indices table."""\n\n    name = "Lokal demo (Sentinel-2 uslubi)"\n\n    def ndvi_series(self, field_id: int, days: int = 730) -> pd.DataFrame:\n        since = (date.today() - timedelta(days=days)).isoformat()\n        return read_df(\n            "SELECT date, ndvi, evi FROM satellite_indices"\n            " WHERE field_id = :f AND date >= :s ORDER BY date",\n            {"f": field_id, "s": since},\n        )\n\n\nclass GEEProvider(LocalProvider):\n    """Google Earth Engine provider (Sentinel-2 SR) when credentials exist."""\n\n    name = "Google Earth Engine (Sentinel-2)"\n\n    def __init__(self) -> None:\n        import ee  # noqa: PLC0415 - optional import guarded by get_provider\n\n        account = get_setting("gee_service_account")\n        key_file = get_setting("gee_key_file")\n        credentials = ee.ServiceAccountCredentials(account, key_file)\n        ee.Initialize(credentials)\n        self._ee = ee\n\n    def ndvi_series(self, field_id: int, days: int = 730) -> pd.DataFrame:\n        field = read_df("SELECT lat, lon FROM fields WHERE id = :f", {"f": field_id})\n        if field.empty:\n            return super().ndvi_series(field_id, days)\n        try:\n            ee = self._ee\n            point = ee.Geometry.Point([float(field.iloc[0].lon), float(field.iloc[0].lat)])\n            start = (date.today() - timedelta(days=days)).isoformat()\n            collection = (\n                ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")\n                .filterBounds(point).filterDate(start, date.today().isoformat())\n                .filter(ee.Filter.lt("CLOUDY_PIXEL_PERCENTAGE", 30))\n            )\n\n            def to_feature(image):  # type: ignore[no-untyped-def]\n                ndvi = image.normalizedDifference(["B8", "B4"]).rename("ndvi")\n                stats = ndvi.reduceRegion(ee.Reducer.mean(), point.buffer(300), 20)\n                return ee.Feature(None, {\n                    "date": image.date().format("YYYY-MM-dd"), "ndvi": stats.get("ndvi"),\n                })\n\n            features = collection.map(to_feature).getInfo()["features"]\n            rows = [\n                {"date": f["properties"]["date"],\n                 "ndvi": round(float(f["properties"]["ndvi"]), 3),\n                 "evi": round(float(f["properties"]["ndvi"]) * 0.85, 3)}\n                for f in features if f["properties"].get("ndvi") is not None\n            ]\n            if rows:\n                return pd.DataFrame(rows).sort_values("date").reset_index(drop=True)\n        except Exception as exc:  # noqa: BLE001\n            log.warning("GEE so\'rovi muvaffaqiyatsiz, lokal rejimga o\'tildi: %s", exc)\n        return super().ndvi_series(field_id, days)\n\n\ndef get_provider() -> LocalProvider:\n    """Provider chain: GEE (if configured) -> local demo."""\n    if try_import("ee") is not None and get_setting("gee_service_account"):\n        try:\n            return GEEProvider()\n        except Exception as exc:  # noqa: BLE001\n            log.warning("GEE ulanmadi (%s); lokal provayder ishlatiladi.", exc)\n    return LocalProvider()\n\n\ndef ndvi_series(field_id: int, days: int = 730) -> pd.DataFrame:\n    """NDVI/EVI time series for a field through the active provider."""\n    return get_provider().ndvi_series(field_id, days)\n\n\n@cached(ttl=300)\ndef field_health() -> pd.DataFrame:\n    """Latest NDVI per field with a simple health classification."""\n    df = read_df(\n        "SELECT f.id AS field_id, f.name AS field, fa.name AS farm,"\n        " r.name AS region, s.ndvi, s.evi, MAX(s.date) AS date"\n        " FROM satellite_indices s"\n        " JOIN fields f ON f.id = s.field_id"\n        " JOIN farms fa ON fa.id = f.farm_id"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " GROUP BY f.id"\n    )\n    if df.empty:\n        return df\n\n    def classify(ndvi: float) -> str:\n        if ndvi >= 0.55:\n            return "A\'lo"\n        if ndvi >= 0.4:\n            return "Yaxshi"\n        if ndvi >= 0.25:\n            return "O\'rtacha"\n        return "Zaif"\n\n    df["holat"] = df["ndvi"].apply(classify)\n    return df.sort_values("ndvi", ascending=False)\n\n\ndef process_drone_image(path: Path, field_id: int | None = None,\n                        username: str = "") -> str:\n    """Process an uploaded GeoTIFF/TIFF/JPG/PNG orthomosaic or NDVI raster.\n\n    With rasterio: reads bands, computes NDVI when NIR+Red exist, stores the\n    result as a satellite index record. Without rasterio: Pillow-based\n    brightness statistics as the fallback vegetation proxy.\n    """\n    summary: str\n    ndvi_value: float | None = None\n    rasterio = try_import("rasterio")\n    if rasterio is not None and path.suffix.lower() in {".tif", ".tiff"}:\n        try:\n            with rasterio.open(path) as src:\n                bands = src.count\n                if bands >= 4:  # assume R,G,B,NIR orthomosaic\n                    red = src.read(1).astype(float)\n                    nir = src.read(4).astype(float)\n                    denominator = np.where((nir + red) == 0, 1e-6, nir + red)\n                    ndvi_value = float(np.clip(np.mean((nir - red) / denominator), -1, 1))\n                    summary = (f"GeoTIFF qabul qilindi: {bands} kanal, "\n                               f"{src.width}x{src.height}px, o\'rtacha NDVI={ndvi_value:.3f}")\n                elif bands == 1:\n                    data = src.read(1).astype(float)\n                    ndvi_value = float(np.clip(np.nanmean(data), -1, 1))\n                    summary = (f"NDVI raster qabul qilindi: {src.width}x{src.height}px, "\n                               f"o\'rtacha qiymat={ndvi_value:.3f}")\n                else:\n                    summary = f"GeoTIFF qabul qilindi: {bands} kanal, {src.width}x{src.height}px."\n        except Exception as exc:  # noqa: BLE001\n            summary = f"Rasterni o\'qishda xato: {exc}"\n    else:\n        pil = try_import("PIL.Image")\n        if pil is not None:\n            try:\n                with pil.open(path) as image:\n                    gray = np.asarray(image.convert("L"), dtype=float) / 255.0\n                    greenness = float(gray.mean())\n                    ndvi_value = round(0.1 + greenness * 0.6, 3)\n                    summary = (f"Tasvir qabul qilindi: {image.size[0]}x{image.size[1]}px, "\n                               f"vegetatsiya bahosi≈{ndvi_value:.3f} (Pillow rejimi)")\n            except Exception as exc:  # noqa: BLE001\n                summary = f"Tasvirni o\'qishda xato: {exc}"\n        else:\n            summary = f"Fayl saqlandi: {path.name} (raster kutubxonalari o\'rnatilmagan)."\n\n    with session_scope() as session:\n        session.add(ImportedFile(filename=path.name, file_type=path.suffix.lstrip("."),\n                                 uploaded_by=username, summary=summary))\n        if ndvi_value is not None and field_id:\n            session.add(SatelliteIndex(\n                field_id=field_id, date=date.today(), ndvi=round(ndvi_value, 3),\n                evi=round(ndvi_value * 0.85, 3), source="dron",\n            ))\n    field_health.cache.clear()  # type: ignore[attr-defined]\n    return summary\n\n\ndef field_options() -> dict[int, str]:\n    """id -> label map for field select widgets."""\n    df = read_df(\n        "SELECT f.id, f.name || \' — \' || fa.name AS label"\n        " FROM fields f JOIN farms fa ON fa.id = f.farm_id ORDER BY f.id"\n    )\n    return {int(row.id): row.label for row in df.itertuples()}\n',
    'utils': '"""Utilities: file import pipeline, global search."""\n',
    'utils.importer': '"""Universal import pipeline.\n\nAccepts CSV / Excel / JSON / GeoJSON / Shapefile / KML / TIFF / GeoTIFF / ZIP\nuploads, auto-detects the payload type by extension + column signature, and\nroutes rows into the right tables. Optional geo libraries improve fidelity;\npure-Python fallbacks keep every path working.\n"""\nfrom __future__ import annotations\n\nimport io\nimport json\nimport logging\nimport re\nimport zipfile\nfrom datetime import date, datetime\nfrom pathlib import Path\n\nimport pandas as pd\n\nfrom config import settings\nfrom core.cache import clear_all_caches\nfrom core.optional import try_import\nfrom core.security import audit\nfrom database.engine import session_scope\nfrom database.models import (\n    Crop, Farm, Field, ImportedFile, MarketPrice, YieldRecord,\n)\n\nlog = logging.getLogger(__name__)\n\nPRICE_COLUMNS = {"crop", "ekin", "price", "narx"}\nYIELD_COLUMNS = {"crop", "ekin", "yield", "hosildorlik", "year", "yil"}\n\n\ndef handle_upload(filename: str, content: bytes, username: str = "") -> str:\n    """Entry point for every UI upload; returns a human-readable summary."""\n    settings.ensure_directories()\n    safe_name = re.sub(r"[^\\w.\\-]", "_", filename)\n    target = settings.UPLOAD_DIR / f"{datetime.now():%Y%m%d_%H%M%S}_{safe_name}"\n    target.write_bytes(content)\n    extension = target.suffix.lower()\n    try:\n        if extension == ".zip":\n            summary = _handle_zip(target, username)\n        elif extension in {".csv", ".xlsx", ".xls"}:\n            summary = _handle_table(target, username)\n        elif extension in {".geojson", ".json"}:\n            summary = _handle_geojson(target, username)\n        elif extension == ".shp":\n            summary = _handle_shapefile(target, username)\n        elif extension == ".kml":\n            summary = _handle_kml(target, username)\n        elif extension in {".tif", ".tiff", ".jpg", ".jpeg", ".png"}:\n            from satellite.service import process_drone_image\n\n            summary = process_drone_image(target, username=username)\n        elif extension in {".db", ".sqlite"}:\n            summary = (f"SQLite fayl saqlandi: {target.name}. Uni tiklash uchun "\n                       f"Administrator sahifasidagi Backup bo\'limidan foydalaning.")\n        else:\n            summary = f"Fayl saqlandi: {target.name} (avtomatik import qo\'llanmaydi)."\n    except Exception as exc:  # noqa: BLE001\n        log.exception("Import xatosi: %s", filename)\n        summary = f"Import xatosi ({filename}): {exc}"\n\n    _register(target.name, extension.lstrip("."), username, summary)\n    clear_all_caches()\n    audit("import", username, f"{filename}: {summary[:200]}")\n    return summary\n\n\ndef _register(filename: str, file_type: str, username: str, summary: str) -> None:\n    with session_scope() as session:\n        session.add(ImportedFile(filename=filename, file_type=file_type,\n                                 uploaded_by=username, summary=summary[:900]))\n\n\n# --------------------------------------------------------------------------\n# Tabular data (CSV / Excel) — auto-detected as prices or yields\n# --------------------------------------------------------------------------\ndef _read_table(path: Path) -> pd.DataFrame:\n    if path.suffix.lower() == ".csv":\n        return pd.read_csv(path, encoding="utf-8-sig")\n    return pd.read_excel(path)\n\n\ndef _handle_table(path: Path, username: str) -> str:\n    df = _read_table(path)\n    df.columns = [str(column).strip().lower() for column in df.columns]\n    columns = set(df.columns)\n    if columns & {"price", "narx", "price_per_kg"}:\n        return _import_prices(df)\n    if columns & {"yield", "hosildorlik", "yield_t_ha"}:\n        return _import_yields(df)\n    return (f"Jadval saqlandi ({len(df)} qator), lekin ustunlar bo\'yicha "\n            f"avtomatik moslik topilmadi. Kutilgan ustunlar: "\n            f"narx importi uchun [ekin, narx, sana]; hosildorlik uchun "\n            f"[ekin, yil, hosildorlik].")\n\n\ndef _column(df: pd.DataFrame, *names: str) -> str | None:\n    for name in names:\n        if name in df.columns:\n            return name\n    return None\n\n\ndef _parse_date(value: object) -> date:\n    if isinstance(value, (datetime, pd.Timestamp)):\n        return value.date()\n    try:\n        return pd.to_datetime(str(value)).date()\n    except (ValueError, TypeError):\n        return date.today()\n\n\ndef _import_prices(df: pd.DataFrame) -> str:\n    crop_column = _column(df, "crop", "ekin", "ekin_nomi")\n    price_column = _column(df, "price", "narx", "price_per_kg")\n    date_column = _column(df, "date", "sana")\n    if not crop_column or not price_column:\n        return "Narx importi uchun \'ekin\' va \'narx\' ustunlari topilmadi."\n    imported = skipped = 0\n    with session_scope() as session:\n        crops = {crop.name.lower(): crop.id for crop in session.query(Crop).all()}\n        for _, row in df.iterrows():\n            crop_id = crops.get(str(row[crop_column]).strip().lower())\n            try:\n                price = float(row[price_column])\n            except (ValueError, TypeError):\n                crop_id = None\n            if crop_id is None:\n                skipped += 1\n                continue\n            session.add(MarketPrice(\n                crop_id=crop_id, price_per_kg=price,\n                date=_parse_date(row[date_column]) if date_column else date.today(),\n                market_name="Import", source="import",\n            ))\n            imported += 1\n    return f"Bozor narxlari importi: {imported} qator qo\'shildi, {skipped} o\'tkazildi."\n\n\ndef _import_yields(df: pd.DataFrame) -> str:\n    crop_column = _column(df, "crop", "ekin")\n    yield_column = _column(df, "yield", "hosildorlik", "yield_t_ha")\n    year_column = _column(df, "year", "yil")\n    field_column = _column(df, "field", "dala", "field_id")\n    if not crop_column or not yield_column or not year_column:\n        return "Hosildorlik importi uchun \'ekin\', \'yil\', \'hosildorlik\' ustunlari kerak."\n    imported = skipped = 0\n    with session_scope() as session:\n        crops = {crop.name.lower(): crop.id for crop in session.query(Crop).all()}\n        fields = {field.name.lower(): field for field in session.query(Field).all()}\n        default_field = next(iter(fields.values()), None)\n        for _, row in df.iterrows():\n            crop_id = crops.get(str(row[crop_column]).strip().lower())\n            field = fields.get(str(row[field_column]).strip().lower()) \\\n                if field_column else default_field\n            field = field or default_field\n            try:\n                yield_value = float(row[yield_column])\n                year = int(row[year_column])\n            except (ValueError, TypeError):\n                crop_id = None\n            if crop_id is None or field is None:\n                skipped += 1\n                continue\n            session.add(YieldRecord(\n                field_id=field.id, crop_id=crop_id, year=year,\n                area_ha=field.area_ha, yield_t_ha=yield_value,\n                production_t=round(yield_value * field.area_ha, 1),\n            ))\n            imported += 1\n    return f"Hosildorlik importi: {imported} qator qo\'shildi, {skipped} o\'tkazildi."\n\n\n# --------------------------------------------------------------------------\n# Geo formats\n# --------------------------------------------------------------------------\ndef _import_features(features: list[dict], source: str) -> str:\n    """Create Field rows from GeoJSON-like features, attached to an import farm."""\n    from gis.geo import polygon_area_ha, polygon_centroid\n\n    created = 0\n    with session_scope() as session:\n        farm = session.query(Farm).filter(Farm.name == "Import xo\'jaligi").first()\n        if farm is None:\n            any_farm = session.query(Farm).first()\n            if any_farm is None:\n                return "Import uchun kamida bitta xo\'jalik mavjud bo\'lishi kerak."\n            farm = Farm(name="Import xo\'jaligi", farmer_id=any_farm.farmer_id,\n                        district_id=any_farm.district_id, area_ha=0.0)\n            session.add(farm)\n            session.flush()\n        for i, feature in enumerate(features, start=1):\n            geometry = feature.get("geometry") or {}\n            if geometry.get("type") != "Polygon":\n                continue\n            geometry_text = json.dumps(geometry)\n            centroid = polygon_centroid(geometry_text)\n            if centroid is None:\n                continue\n            properties = feature.get("properties") or {}\n            area = properties.get("area_ha") or polygon_area_ha(geometry_text) or 1.0\n            name = str(properties.get("name") or f"{source}-kontur-{i}")\n            session.add(Field(\n                farm_id=farm.id, name=name[:120], area_ha=float(area),\n                soil_type=str(properties.get("soil", "bo\'z tuproq"))[:32],\n                lat=centroid[0], lon=centroid[1], geometry_geojson=geometry_text,\n            ))\n            farm.area_ha = round(farm.area_ha + float(area), 1)\n            created += 1\n    return f"{source} importi: {created} ta dala poligoni qo\'shildi."\n\n\ndef _handle_geojson(path: Path, _username: str) -> str:\n    payload = json.loads(path.read_text(encoding="utf-8"))\n    if payload.get("type") == "FeatureCollection":\n        return _import_features(payload.get("features", []), "GeoJSON")\n    if payload.get("type") == "Feature":\n        return _import_features([payload], "GeoJSON")\n    return "JSON fayl saqlandi (GeoJSON strukturasi topilmadi)."\n\n\ndef _handle_shapefile(path: Path, _username: str) -> str:\n    shapefile = try_import("shapefile")  # pyshp\n    if shapefile is None:\n        return ("Shapefile saqlandi. To\'liq import uchun \'pyshp\' paketini "\n                "o\'rnating: pip install pyshp")\n    reader = shapefile.Reader(str(path))\n    features = []\n    for shape_record in reader.shapeRecords():\n        geo = shape_record.shape.__geo_interface__\n        if geo["type"] == "Polygon":\n            features.append({"geometry": geo,\n                             "properties": dict(shape_record.record.as_dict())})\n    return _import_features(features, "Shapefile")\n\n\ndef _handle_kml(path: Path, _username: str) -> str:\n    """Minimal KML polygon parser (stdlib XML, no external deps)."""\n    import xml.etree.ElementTree as ET\n\n    namespace = {"kml": "http://www.opengis.net/kml/2.2"}\n    tree = ET.parse(path)\n    features = []\n    for placemark in tree.iter(f"{{{namespace[\'kml\']}}}Placemark"):\n        name_node = placemark.find("kml:name", namespace)\n        for coords_node in placemark.iter(f"{{{namespace[\'kml\']}}}coordinates"):\n            points = []\n            for token in (coords_node.text or "").split():\n                parts = token.split(",")\n                if len(parts) >= 2:\n                    points.append([float(parts[0]), float(parts[1])])\n            if len(points) >= 4:\n                features.append({\n                    "geometry": {"type": "Polygon", "coordinates": [points]},\n                    "properties": {"name": name_node.text if name_node is not None else None},\n                })\n    return _import_features(features, "KML")\n\n\ndef _handle_zip(path: Path, username: str) -> str:\n    """Extract a ZIP and recursively import each supported member."""\n    summaries = []\n    with zipfile.ZipFile(path) as archive:\n        for member in archive.namelist()[:20]:\n            extension = Path(member).suffix.lower()\n            if extension in {".csv", ".xlsx", ".geojson", ".json", ".kml",\n                             ".shp", ".tif", ".tiff", ".jpg", ".png"}:\n                summaries.append(\n                    f"{member}: "\n                    + handle_upload(Path(member).name, archive.read(member), username)\n                )\n    if not summaries:\n        return "ZIP ichida import qilinadigan fayl topilmadi."\n    return " | ".join(summaries[:5])\n',
    'utils.search': '"""Global search across farmers, farms, fields, crops, regions and districts."""\nfrom __future__ import annotations\n\nimport pandas as pd\n\nfrom database.engine import read_df\n\n\ndef global_search(query: str, limit: int = 30) -> pd.DataFrame:\n    """Case-insensitive LIKE search across every named entity."""\n    like = f"%{query.strip()}%"\n    if not query.strip():\n        return pd.DataFrame(columns=["turi", "nomi", "tafsilot"])\n    df = read_df(\n        "SELECT \'Fermer\' AS turi, fm.name AS nomi,"\n        " d.name || \', tel: \' || fm.phone AS tafsilot"\n        " FROM farmers fm JOIN districts d ON d.id = fm.district_id"\n        " WHERE fm.name LIKE :q"\n        " UNION ALL "\n        "SELECT \'Xo\'\'jalik\', fa.name, r.name || \' — \' ||"\n        " CAST(ROUND(fa.area_ha) AS INTEGER) || \' ga\'"\n        " FROM farms fa"\n        " JOIN districts d ON d.id = fa.district_id"\n        " JOIN regions r ON r.id = d.region_id WHERE fa.name LIKE :q"\n        " UNION ALL "\n        "SELECT \'Dala\', f.name, fa.name || \' — \' ||"\n        " CAST(f.area_ha AS TEXT) || \' ga, \' || f.soil_type"\n        " FROM fields f JOIN farms fa ON fa.id = f.farm_id WHERE f.name LIKE :q"\n        " UNION ALL "\n        "SELECT \'Ekin\', c.name, c.category || \', \' || c.season || \' — bazaviy narx \' ||"\n        " CAST(CAST(c.base_price_per_kg AS INTEGER) AS TEXT) || \' so\'\'m/kg\'"\n        " FROM crops c WHERE c.name LIKE :q"\n        " UNION ALL "\n        "SELECT \'Viloyat\', r.name, \'Markaz: \' || CAST(ROUND(r.lat,2) AS TEXT) ||"\n        " \', \' || CAST(ROUND(r.lon,2) AS TEXT) FROM regions r WHERE r.name LIKE :q"\n        " UNION ALL "\n        "SELECT \'Tuman\', d.name, r.name FROM districts d"\n        " JOIN regions r ON r.id = d.region_id WHERE d.name LIKE :q"\n        " LIMIT :n",\n        {"q": like, "n": limit},\n    )\n    return df\n',
    'weather': '"""Weather integrations: Open-Meteo, NASA POWER, offline cache fallback."""\n',
    'weather.service': '"""Weather service with live providers and a guaranteed offline path.\n\nOnline: Open-Meteo (default, no API key) or NASA POWER. Every successful\nresponse is cached to disk and mirrored into the ``weather_records`` table,\nso the dashboard keeps working from the last known data when offline.\n"""\nfrom __future__ import annotations\n\nimport json\nimport logging\nimport socket\nfrom datetime import date, datetime, timedelta\nfrom typing import Any\n\nimport pandas as pd\nimport requests\n\nfrom config import settings\nfrom core.cache import cached\nfrom database.engine import get_setting, read_df, session_scope\nfrom database.models import District, WeatherRecord\n\nlog = logging.getLogger(__name__)\n\nOPEN_METEO_URL = "https://api.open-meteo.com/v1/forecast"\nNASA_POWER_URL = "https://power.larc.nasa.gov/api/temporal/daily/point"\nREQUEST_TIMEOUT = 8\n\n\n@cached(ttl=60)\ndef is_online() -> bool:\n    """Cheap connectivity probe honouring the offline_mode setting."""\n    mode = get_setting("offline_mode", "auto")\n    if mode == "on":\n        return False\n    if mode == "off":\n        return True\n    try:\n        socket.create_connection(("8.8.8.8", 53), timeout=3).close()\n        return True\n    except OSError:\n        return False\n\n\ndef _cache_file(lat: float, lon: float) -> Any:\n    return settings.CACHE_DIR / f"forecast_{lat:.2f}_{lon:.2f}.json"\n\n\ndef fetch_forecast(lat: float, lon: float, days: int = 7) -> dict[str, Any] | None:\n    """7-day forecast: live when online, otherwise the last cached response."""\n    cache_path = _cache_file(lat, lon)\n    if is_online():\n        try:\n            response = requests.get(OPEN_METEO_URL, params={\n                "latitude": lat, "longitude": lon,\n                "daily": "temperature_2m_max,temperature_2m_min,"\n                         "precipitation_sum,relative_humidity_2m_mean",\n                "forecast_days": days, "timezone": "Asia/Tashkent",\n            }, timeout=REQUEST_TIMEOUT)\n            response.raise_for_status()\n            payload = response.json()\n            payload["_fetched_at"] = datetime.now().isoformat(timespec="seconds")\n            payload["_source"] = "open-meteo (jonli)"\n            cache_path.write_text(json.dumps(payload), encoding="utf-8")\n            return payload\n        except (requests.RequestException, ValueError) as exc:\n            log.warning("Open-Meteo so\'rovi muvaffaqiyatsiz: %s", exc)\n    if cache_path.exists():\n        try:\n            payload = json.loads(cache_path.read_text(encoding="utf-8"))\n            payload["_source"] = f"kesh ({payload.get(\'_fetched_at\', \'noma`lum\')})"\n            return payload\n        except (json.JSONDecodeError, OSError):\n            pass\n    return None\n\n\ndef fetch_nasa_power(lat: float, lon: float, start: date, end: date) -> pd.DataFrame | None:\n    """Historical daily data from NASA POWER (used when provider=nasa-power)."""\n    if not is_online():\n        return None\n    try:\n        response = requests.get(NASA_POWER_URL, params={\n            "parameters": "T2M_MAX,T2M_MIN,PRECTOTCORR,RH2M",\n            "community": "AG", "latitude": lat, "longitude": lon,\n            "start": start.strftime("%Y%m%d"), "end": end.strftime("%Y%m%d"),\n            "format": "JSON",\n        }, timeout=REQUEST_TIMEOUT * 2)\n        response.raise_for_status()\n        block = response.json()["properties"]["parameter"]\n        rows = []\n        for key, t_max in block["T2M_MAX"].items():\n            rows.append({\n                "date": datetime.strptime(key, "%Y%m%d").date(),\n                "t_max": t_max, "t_min": block["T2M_MIN"].get(key),\n                "precipitation_mm": block["PRECTOTCORR"].get(key, 0),\n                "humidity": block["RH2M"].get(key, 50),\n            })\n        return pd.DataFrame(rows)\n    except (requests.RequestException, KeyError, ValueError) as exc:\n        log.warning("NASA POWER so\'rovi muvaffaqiyatsiz: %s", exc)\n        return None\n\n\ndef refresh_all_districts() -> int:\n    """Background job: pull recent live daily data into weather_records."""\n    if not is_online():\n        return 0\n    updated = 0\n    with session_scope() as session:\n        districts = session.query(District).all()\n    for district in districts[:6]:  # polite batch per hourly cycle\n        try:\n            response = requests.get(OPEN_METEO_URL, params={\n                "latitude": district.lat, "longitude": district.lon,\n                "daily": "temperature_2m_max,temperature_2m_min,"\n                         "precipitation_sum,relative_humidity_2m_mean",\n                "past_days": 7, "forecast_days": 1, "timezone": "Asia/Tashkent",\n            }, timeout=REQUEST_TIMEOUT)\n            response.raise_for_status()\n            daily = response.json()["daily"]\n        except (requests.RequestException, KeyError, ValueError):\n            continue\n        with session_scope() as session:\n            for i, day_str in enumerate(daily["time"]):\n                day = datetime.strptime(day_str, "%Y-%m-%d").date()\n                if day >= date.today():\n                    continue\n                exists = session.query(WeatherRecord).filter_by(\n                    district_id=district.id, date=day).first()\n                values = {\n                    "t_max": float(daily["temperature_2m_max"][i] or 0),\n                    "t_min": float(daily["temperature_2m_min"][i] or 0),\n                    "precipitation_mm": float(daily["precipitation_sum"][i] or 0),\n                    "humidity": float(daily["relative_humidity_2m_mean"][i] or 50),\n                    "source": "open-meteo",\n                }\n                if exists is None:\n                    session.add(WeatherRecord(district_id=district.id, date=day, **values))\n                    updated += 1\n                elif exists.source == "demo":\n                    for key, value in values.items():\n                        setattr(exists, key, value)\n                    updated += 1\n    if updated:\n        log.info("Ob-havo yangilandi: %d yozuv.", updated)\n    return updated\n\n\ndef history_frame(district_id: int | None = None,\n                  days: int = 365) -> pd.DataFrame:\n    """Daily history for charts (optionally filtered by district)."""\n    since = (date.today() - timedelta(days=days)).isoformat()\n    if district_id:\n        return read_df(\n            "SELECT date, t_min, t_max, precipitation_mm, humidity"\n            " FROM weather_records WHERE district_id = :d AND date >= :s"\n            " ORDER BY date", {"d": district_id, "s": since},\n        )\n    return read_df(\n        "SELECT date, AVG(t_min) AS t_min, AVG(t_max) AS t_max,"\n        " AVG(precipitation_mm) AS precipitation_mm, AVG(humidity) AS humidity"\n        " FROM weather_records WHERE date >= :s GROUP BY date ORDER BY date",\n        {"s": since},\n    )\n\n\ndef monthly_climate(district_id: int) -> pd.DataFrame:\n    """Long-term monthly averages for the climate profile chart."""\n    return read_df(\n        "SELECT CAST(strftime(\'%m\', date) AS INTEGER) AS month,"\n        " ROUND(AVG(t_max),1) AS t_max, ROUND(AVG(t_min),1) AS t_min,"\n        " ROUND(SUM(precipitation_mm)/COUNT(DISTINCT strftime(\'%Y\', date)),1) AS precip,"\n        " ROUND(AVG(humidity),1) AS humidity"\n        " FROM weather_records WHERE district_id = :d"\n        " GROUP BY month ORDER BY month", {"d": district_id},\n    )\n\n\ndef season_summary(region_name: str, year: int) -> dict[str, float] | None:\n    """Season (Apr–Sep) precipitation and temperature for a region-year."""\n    df = read_df(\n        "SELECT SUM(w.precipitation_mm) AS precip,"\n        " AVG((w.t_min+w.t_max)/2) AS t_avg, AVG(w.humidity) AS humidity"\n        " FROM weather_records w"\n        " JOIN districts d ON d.id = w.district_id"\n        " JOIN regions r ON r.id = d.region_id"\n        " WHERE r.name = :r AND CAST(strftime(\'%Y\', w.date) AS INTEGER) = :y"\n        " AND CAST(strftime(\'%m\', w.date) AS INTEGER) BETWEEN 4 AND 9",\n        {"r": region_name, "y": year},\n    )\n    if df.empty or pd.isna(df.iloc[0]["precip"]):\n        return None\n    row = df.iloc[0]\n    # Region has 2 districts — normalise the precipitation sum per district.\n    return {"precip": float(row["precip"]) / 2, "t_avg": float(row["t_avg"]),\n            "humidity": float(row["humidity"])}\n',
}


class _EmbeddedFinder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    """Serves every embedded module straight from the _SOURCES dictionary."""

    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _SOURCES:
            return None
        return importlib.util.spec_from_loader(
            fullname, self, origin=f"<embedded:{fullname}>",
            is_package=fullname in _PACKAGES)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        origin = f"<embedded:{module.__name__}>"
        module.__file__ = origin
        code = compile(_SOURCES[module.__name__], origin, "exec")
        exec(code, module.__dict__)


def _install_finder() -> None:
    if not any(isinstance(f, _EmbeddedFinder) for f in sys.meta_path):
        sys.meta_path.insert(0, _EmbeddedFinder())


if __name__ in {"__main__", "__mp_main__"}:
    _install_finder()
    import run

    run.main()
